INSERT INTO m229_art VALUES
(0,0,$m229$الديباجة$m229$,$m229$قانون رقم 72 لسنة 2017 بتاريخ 31/05/2017 بإصدار قانون الاستثمار$m229$,'77cc3a6d687e1d9027d67e1697e1511c'),
(1,-1,$m229$المادة الأولى إصدار$m229$,$m229$يعمل فى شأن الاستثمار فى جمهورية مصر العربية بأحكام القانون المرافق.
وتسرى أحكامه على الاستثمار المحلى والأجنبى أيا كأن حجمه، ويكون الاستثمار وفقا لأحكام هذا القانون إما بنظام الاستثمار الداخلى أو بنظام المناطق الاستثمارية أو بنظام المناطق التكنولوجية، أو بنظام المناطق الحرة.$m229$,'76a5b102106927343e30d52028a9629f'),
(1,0,$m229$المادة 1$m229$,$m229$فى تطبيق أحكام هذا القانون يقصد بالكلمات والعبارات التالية المعاني المبينة قرين كل منها:
الاستثمار: استخدام المال لأن شاء مشروع استثمارى أو توسيعه أو تطويره أو تمويله أو تملكه أو إدارته بما يسهم في تحقيق التنمية الشاملة والمستدامة للبلاد.
المستثمر: كل شخص طبيعي أو اعتباري مصريا كأن أو اجنبيا أيا كأن النظام القانوني الخاضع له يقوم بالإستثمار في جمهورية مصر العربية وفقا لأحكام هذا القانون.
المشروع الإستثمارى: مزاولة أحد الأنشطة الإستثمارية في قطاعات الصناعة والزراعة والتجارة والتعليم والصحة والنقل والسياحة والإسكان والتشييد والبناء والرياضة والكهرباء والطاقة والثروات الطبيعية والمياه والإتصالات والتكنولوجيا.
ويجوز للوزير المختص بشئون الإستثمار بالتنسيق مع الوزارة أو الوزارت المعنية إضافة قطاعات أخرى وفقا لخطة التنمية الأقتصادية للدولة، وتبين اللائحة التنفيذية لهذا القانون شروط ونطاق وضوابط مزاولة هذه الأنشطة.
الحوافز الخاصة: الحوافز المنصوص عليها فى المادتين (11 و 11 مكررا) من هذا القانون.
الأموال: جميع أنواع الأصول التي تدخل في المشروع الأستثمارى أيا كان نوعها وتكون لها قيمة مادية سواء كانت نقدية أو عينية أو معنوية، وتشمل علي الأخص:
1 - الأموال الثابتة والمنقولة، وكذلك أي حقوق عينية أصلية أو تبعية أخرى.
2 - الأسهم وحصص تأسيس الشركات، والسندات غير الحكومية.
3 - حقوق الملكية الفكرية والحقوق المعنوية التي تستخدم في إنشاء المشروعات أو التوسع فيها، كبراءات الاختراع والعلامات والأسماء التجارية المسجلة فى دولة من دول المنظمة العالمية للملكية الفكرية أو وفقا لقواعد التسجيل الدولية التي تضمنتها الاتفاقيات الدولية النافذة في هذا الشأن.
4 - الامتيازات أو العقود التي تمنح بمقتضي قوانين التزامات المرافق العامة والقوانين ذات الطبيعة المماثلة لها وكذلك جميع الحقوق المماثلة الأخري التي تعطي بناء علي القانون.
المجلس الأعلي: المجلس الأعلى للاستثمار.
الوزير المختص: الوزير المختص بشئون الاستثمار.
الوزارة المختصة: الوزراة المختصة بشئون الأستثمار.
الهيئة: الهيئة العامة للاستثمار والمناطق الحرة.
الأستثمار الداخلي: أحد نظم الاستثمار يتم خلاله إقامة أو أن شاء أو تشغيل مشروع استثماري وفقا لأحكام هذا القانون في غير المناطق الحرة.
المنطقة الحرة: جزء من إقليم يدخل ضمن حدودها ويخضع لسلطاتها الإدارية ويتم التعامل فيه وفقا لأحكام جمركية وضريبية خاصة.
المنطقة الإستثمارية: منطقة جغرافية محددة المساحة والحدود، تخصص لإقامة نشاط معين أو أكثر من الأنشطة الاستثمارية المتخصصة وغيرها من الأنشطة المكملة لها، يقوم علي تنميتها ووضع بنيتها الأساسية مطور لتلك المنطقة.
المطور: كل شخص اعتبارى يرخص له أن شاء منطقة استثمارية أو إدارتها أو تطويرها أو تنميتها وفقا لأحكام هذا القانون.
الجهات المختصة: الجهات الإدارية أو شركات المرافق العامة المختصة بإصدار الموافقات أو التصاريح أو التراخيص.
مركز خدمات المستثمرين: وحدة إدارية منشأة بالهيئة أو أحد فروعها تتولي تطبيق نظام لتيسير وتبسيط إجراءات حصول المستثمر علي جميع الموافقات والتصاريح والتراخيص اللازمة لمشروعه الاستثماري خلال المدد القانونية المنصوص عليها في هذا القانون، وإتاحة ما يلزم لذلك من بيانات ومعلومات.
ممثل الجهة المختصة: المسئول المنتدب من الجهات الإدارية المختصة أو المكلف من شركات المرافق العامة، للعمل في نظام مركز خدمات المستثمرين بالهيئة أو أحد فروعها، والذي تنتقل إليه بموجب أحكام هذه القانون سلطة إصدار الموافقات والتصاريح والتراخيص، بحسب الاشتراطات الفنية الواردة بالقوانين المنظمة لها و دليل إجراءات الاستثمار الذي تصدره الهيئة، وكذا جميع الصلاحيات المقررة للسلطة المختصة في مجال تخصيص العقارات و إعطاء الموافقات والتصاريح والتراخيص اللازمة لتبسيط عمل المستثمر وتيسيره وتشجيع الاستثمار و تنميته.
السلطة المختصة: الوزير أو المحافظ أو رئيس الهيئة أو المصلحة أو مجلس إدارتها أو رئيس مجلس إدارة شركة الموافق العامة أو مجلس إدارتها بحسب الأحوال.
مكاتب الإعتماد: المكاتب المرخص لها من الهيئة بمنح الموافقات والتصاريح والتراخيص، بالعمل في مجال فحص الإجراءات والمستندات الخاصة بالمشروعات الإستثمارية وتقديم شهادات الإعتماد.
*أستبدل بتعريف الحوافز الخاصة الوارد بالمادة (1) بوجب قانون رقم 160 لسنة 2023.$m229$,'cac352e97d44f8ee60bb2f96749837a1'),
(2,-1,$m229$المادة الثانية إصدار$m229$,$m229$لا تخل أحكام القانون المرافق بالمزايا والإعفاءات الضريبية وغيرها من الضمانات والحوافز المقررة للشركات والمنشآت القائمة وقت العمل به، وتظل هذه الشركات والمنشآت محتفظة بتلك المزايا والإعفاءات والضمانات والحوافز إلى أن تنتهي المدد الخاصة بها وذلك طبقا للتشريعات والاتفاقيات المستمدة منها.
ولا تخل أحكام القانون المرافق بأحكام القانون رقم 7 لسنة 1991 بشأن أملاك الدولة الخاصة وقانون المناطق الاقتصادية ذات الطبيعة الخاصة الصادر بالقانون رقم 83 لسنة 2002، والقانون رقم 14 لسنة 2012 في شأن التنمية المتكاملة في شبه جزيرة سيناء، و قانون تيسير إجراءات منح تراخيص المنشآت الصناعية الصادر بالقانون رقم 15 لسنة 2017.
كما لا تخل أحكام القانون المرافق بالشروط الموضوعية المقررة لمنح الموافقات والتصاريح والتراخيص المنصوص عليها فى أي قوانين أخرى.$m229$,'29572659e759c6841ac71f4a49192958'),
(2,0,$m229$المادة 2$m229$,$m229$يهدف الاستثمار في جمهورية مصر العربية إلي رفع معدلات النمو الاقتصادي للبلاد، وزيادة معدلات الأنتاج المحلي، وتوفير فرص العمل، وتشجيع التصدير، وزيادة التنافسية، بما يسهم في تحقيق التنمية الشاملة والمستدامة.
وتعمل جميع أجهزة الدولة المختصة علي جذب وتحفيز الاستثمارات المحلية والأجنبية.
ويحكم الاستثمار المبادئ الأتية:
1 - المسأو اة فى الفرص الاستثمارية ومراعاة تكافؤ الفرص بغض النظر عن حجم المشروع ومكأنه ودون تمييز بسبب الجنس.
2 - دعم الدولة للشركات الناشئة وزيادة الأعمال والمشروعات متناهية الصغر والصغيرة والمتوسطة لتمكين الشباب وصغار المستثمرين.
3 - مراعاة جميع النواحي ذات البعد الاجتماعي وحماية البيئة والصحة العامة.
4 - حرية المنافسة ومنع الممارسات الاحتكارية وحماية المستهلك.
5 - اتباع مبادئ الحوكمة والشفافية والإدارة الرشيدة وعدم تضارب المصالح.
6 - العمل على استقرار السياسيات الإستثمارية وثابتها.
7 - سرعة أنجاز معاملات المستثمرين والتيسير عليهم بما يحقق مصالحهم المشروعة.
8 - حق الدولة فى الحفاظ على الأمن القومى والمصلحة العامة.
وتسرى مبادئ الاستثمار المشار إليها علي المستثمر والدولة كل فيما يخصه.$m229$,'fca4034985cd3b96fcd576fb2af7bb5b'),
(3,-1,$m229$المادة الثالثة إصدار$m229$,$m229$تستبدل عبارة (قانون الاستثمار) بعبارة (قانون ضمانات وحوافز الاستثمار)، أينما وردت فى القوانين والقرارات الأخرى.$m229$,'6c7cd829b4d4665587f55a9a79da3027'),
(3,0,$m229$المادة 3$m229$,$m229$تتمتع جميع الاستثمارات المقامة فى جمهورية مصر العربية بالمعاملة العادلة والمنصفة.
وتكفل الدولة للمستثمر الأجنبي معاملة مماثلة لتلك التي تمنحها للمستثمر الوطني.
ويجوز استثناء بقرار من مجلس الوزراء تقرير معاملة تفضيلية للمستثمرين الأجانب تطبيقا لمبدأ المعاملة بالمثل.
ولا تخضع الأموال المستثمرة لأي إجراءات تعسفية أو قرارات تتسم بالتمييز.
وتمنح الدولة المستثمرين غير المصريين إقامة فى جمهورية مصر العربية طوال مدة المشروع، وذلك دون الإخلال بأحكام القوانين المنظمة لذلك وعلي النحو الذي تبينه اللائحة التنفيذية لهذا القانون.
وتلتزم الدولة باحترام وإنفاذ العقود التي تبرمها ولا يتمتع المشروع الاستثماري المقام بناء علي غش أو تدليس أو فساد بالحماية أو الضمانات أو المزايا أو الإعفاءات المقررة بموجب أحكام هذا القانون، ويكون اثبات ذلك كله بموجب حكم قضائي بات صادر من القضاء المختص أو بحكم تحكيم.
وفي مجال تطبيق أحكام هذا القانون، تكون جميع القرارات المتعلقة بشئون المشروع الإستثمارى مسببة، ويخطر ذوو الشأن بها، وذلك علي النحو الذي تنظمه اللائحة التنفيذية لهذا القانون.$m229$,'703dce7cbf0dcb3418492cd2b3ec03fc'),
(4,-1,$m229$المادة الرابعة إصدار$m229$,$m229$تستثنى شركات المساهمة الخاضعة لأحكام هذا القانون من تطبيق أحكام القانون رقم 113 لسنة 1958 في شأن التعيين في وظائف شركات المساهمة والمؤسسات العامة.
كما لا تخضع شركات المساهمة لأحكام القانون رقم 73 لسنة 1973 بشأن تحديد شروط وإجراءات أنتخاب ممثلي العمال في مجالس إدارة وحدات القطاع العام والشركات المساهمة والجمعيات والمؤسسات الخاصة، ويبين نظام الشركة طريقة اشتراك العاملين في إدارتها.$m229$,'cb54867fbcf82a04b562d28f2cfe8f14'),
(4,0,$m229$المادة 4$m229$,$m229$لا يجوز تأميم المشروعات الاستثمارية.
ولا يجوز نزع ملكية أموال المشروعات الاستثمارية إلا للمنفعة العامة، وبمقابل تعويض عادل يدفع مقدما دون تأخير، وتكون قيمته معادلة للقيمة الإقتصادية العادلة للمال المنزوع ملكيته في اليوم السابق علي صدور قرار نزع الملكية، وتكون التعويضات قابلة للتحويل دون قيد.
ولا يجوز بالطريق الإدارى فرض الحراسة علي تلك المشروعات، ولا تفرض الحراسة عليها إلا بموجب حكم قضائي نهائى، كما لا يجوز التحفظ عليها إلا بموجب أمر أو حكم قضائي، ولا يكون ذلك كله إلا في الأحوال المبينة في القانون.
ولا يجوز الحجز علي أموال المشروعات الاستثمارية أو مصاردتها أو تجميدها إلا بناء علي أمر قضائي أو حكم نهائي، وذلك عدا الديون الضريبية، واشتراكات التأمينات الاجتماعية المستحقة للدولة التي يجوز تحصيلها عن طريق الحجز بجميع أنواعه، مع عدم الاخلال بما يتفق عليه في العقود التي تبرمها الدولة أو الأشخاص الاعتبارية العامة مع المستثمر.
ولا يجوز لأي جهة إدارية إصدار قرارات تنظيمة عامة تضيف أعباء مالية أو إجرائية، تتعلق بإنشاء أو تشغيل مشروعات تخضع لأحكام هذا القانون أو فرض رسوم أو مقابل خدمات عليها أو تعديلها، إلا بعد أخذ رأي مجلس إدارة الهيئة وموافقة كل من مجلس الوزراء والمجلس الأعلى.$m229$,'46bc6327bce98a8ea76f393afd4501f9'),
(5,-1,$m229$المادة الخامسة إصدار$m229$,$m229$تستثنى المنازعات الناشئة عن تطبيق أحكام هذا القانون والقانون المرافق له، من الخضوع لأحكام القانون رقم 7 لسنة 2000 بأنشاء لجان التوفيق فى بعض المنازعات التى تكون الوزارات والاشخاص الاعتبارية العامة طرفا فيها.$m229$,'489fc0f24cb248746beeed71f7ca36e0'),
(5,0,$m229$المادة 5$m229$,$m229$لا يجوز للجهات الإدارية إلغاء التراخيص الصادرة للمشروع الاستثماري أو وقفها أو سحب العقارات التي تم تخصيصها للمشروع إلا بعد أن ذار المستثمر بالمخالفات المنسوبة إليه، وسماع وجهة نظره، وإعطائه مهلة مناسبة لإزالة أسباب المخالفة.
وفي جميع الأحوال، يجب أخذ رأي الهيئة قبل إصدار القرارات المشار إليها في الفقرة الأو لي، وتبدي الهيئة رأيها خلال سبعة أيام من تاريخ ورود الطلب إليها مستوفيا جميع الإجراءات القانونية المقررة.
ويحق للمستثمر التظلم من هذا القرار أمام اللجنة المنصوص عليها بالمادة (83) من هذا القانون.
وتنظم اللائحة التنفيذية لهذا القانون قواعد تطبيق أحكام هذه المادة وضوابطها.$m229$,'910227c2c64c7c44248c92c443921e8f'),
(6,-1,$m229$المادة السادسة إصدار$m229$,$m229$تحال التظلمات والطلبات المنظورة أمام لجنتي فض منازعات الاستثمار و تسوية منازعات عقود الاستثمار القائمتين، إلى اللجنتين المنصوص عليهما فى المادتين 85، 88 من القانون المرافق فور تشكيلها دون الحاجة إلى أى إجراء آخر.$m229$,'3b99a303988f9ffb5404e47e789a3702'),
(6,0,$m229$المادة 6$m229$,$m229$للمستثمر الحق فى أنشاء وإقامة المشروع الاستثماري وتوسيعه، وتمويله من الخارج دون قيود وبالعملة الأجنبية، كما يكون من حقه تملكه، وإدارته، واستخدامه، والتصرف فيه، وجنى أرباحه وتحويلها إلى الخارج، وتصفية المشروع، وتحويل ناتج هذه التصفية كله أو بعضه إلى الخارج، وذلك دون الإخلال بحقوق الغير.
وتسمح الدولة باتاحة جميع عمليات التحويل النقدي المتصل بالاستثمار الاجنبي بحرية وبدون إبطاء إلي أراضيها وإلى خارجها، بعملة قابلة للتحويل الحر كما تسمح الدولة بتحويل العملة المحلية إلي عملة قابلة للاستخدام بحرية دون تأخير.
وفى حالة التصفية تلتزم الجهات الإدارية المختصة بإخطار الهيئة والشركة تحت التصفية ببيأن ما عليها من التزامات خلال مدة اقصاها مائة وعشرون يوما تبدأ من تاريخ تقديم المصفى طلبا بذلك مرفقا به المستندات اللازمة ويعتبر إنقضاء هذه المدة دون بيأن تلك الالتزامات إبراء لذمة الشركات تحت التصفية وذلك دون الاخلال بالمسئولية الجنائية والتأديبية للمسئول عن اصدار بيان على خلاف الواقع أو من تسبب فى فوات الميعاد المشار إلية دون الرد على الطلب.
وذلك كله وفقا لما تحدده اللائحة التنفيذية لهذا القانون.$m229$,'f7a12218d21035529eaaba10342ba811'),
(7,-1,$m229$المادة السابعة إصدار$m229$,$m229$يستمر العاملون المخاطبون بحكم الفقرة الثالثة من المادة (20) من قانون الاستثمار الصادر بالقانون رقم 230 لسنة 1989 فى التمتع بذات الأو ضاع المقررة لهم ولا تخل هذه الأحكام بنظام توزيع الأرباح المطبق على الشركات القائمة وقت نفاذ هذا القانون إذا كأن ذلك أفضل لهم$m229$,'e78b0cf382df4dbf2ad4bf2190b5a9bc'),
(7,0,$m229$المادة 7$m229$,$m229$مع عدم الإخلال بأحكام القوانيين واللوائح والقرارات المنظمة للإستيراد، يحق للمشروعات الاستثمارية الخاضعة لأحكام هذا القانون أن تستورد بذاتها أو عن طريق الغير، ما تحتاج إلية فى إنشائها أو التوسع فيها أو تشغيلها من المواد الخام ومستلزمات الأنتاج والآلات وقطع الغيار ووسائل النقل المناسبة لطبيعة نشاطها، دون حاجه لقيدها فى سجل المستوردين.
كما يحق لهذه المشروعات أن تصدر منتجاتها بالذات أو بالوساطة دون ترخيص وبغير حاجة لقيدها فى سجل المصدرين.
وتلتزم المشروعات الاستثمارية التى تقوم بالاستيراد أو التصدير وفقا لأحكام هذه المادة سواء بنفسها أو عن طريق الغير بإخطار الهيئة بتقرير ربع سنوى عن الكميات والأنواع المستوردة أو المصدرة بحسب الاحوال.$m229$,'03b51fdca78147334071da59021765c7'),
(8,-1,$m229$المادة الثامنة إصدار$m229$,$m229$يلغى قانون ضمانات وحوافز الاستثمار الصادر بالقانون رقم 8 لسنة 1997، كما يلغى كل حكم يخالف أحكام هذا القانون والقانون المرافق له.$m229$,'c74e28f7c75c8ae4f52491aa9b2c7ad1'),
(8,0,$m229$المادة 8$m229$,$m229$للمشروع الاستثمارى الحق فى استخدام عاملين أجانب فى حدود نسبة (10%) من إجمالى عدد العاملين بالمشروع، وتجوز زيادة هذه النسبة إلى مالا يزيد على (20%) من إجمالى عدد العاملين بالمشروع، وذلك فى حالة عدم إمكانية استخدام عمالة وطنية تملك المؤهلات اللازمة، وذلك وفقا للضوابط والقواعد التى تبينها اللائحة التنفيذية لهذا القانون.
ويجوز فى بعض المشروعات الاستراتيجية ذات الأهمية الخاصة التى يصدر بتحديدها قرار من المجلس الاعلى الاستثناء من النسب المشار إليها بشرط مراعاة تدريب العمالة الوطنية.
وللعاملين الأجانب فى المشروع الاستثمارى الحق فى تحويل مستحقاتهم المالية كلها أو بعضها إلى الخارج.$m229$,'0f0b1d9d39e2a2001f4366e2faf3efa9'),
(9,-1,$m229$المادة التاسعة إصدار$m229$,$m229$يصدر رئيس مجلس الوزراء اللائحة التنفيذية للقانون المرافق، بناء على عرض الوزير المختص وبعد موافقة مجلس الوزراء خلال تسعين يوما من تاريخ العمل بهذا القانون، وإلى أن تصدر هذه اللائحة يستمر العمل باللوائح والقرارات السارية القائمة في تاريخ العمل به فيما لا يتعارض مع أحكامه.$m229$,'64298ee7d204b0365e833ee9c02eb15f'),
(9,0,$m229$المادة 9$m229$,$m229$تتمتع جميع المشروعات الاستثمارية الخاضعة لأحكام هذا القانون، سواء المقامة قبل العمل بأحكامه أو بعده، أيا كان النظام القانونى الخاضعة له، بالحوافز العامة الواردة فى هذا الفصل، وذلك فيما عدا المشروعات المقامة بنظام المناطق الحرة.
*معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'fbed6db4e3885ef0ff3c9251c781a5a6'),
(10,-1,$m229$المادة العاشرة إصدار$m229$,$m229$ينشر هذا القانون في الجريدة الرسمية، ويعمل به من اليوم التالي لتاريخ نشره.
يبصم هذا القانون بخاتم الدولة، وينفذ كقانون من قوأن ينها.
صدر برئاسة الجمهورية فى 5 رمضأن سنة 1438 هـ (الموافق 31 مايو سنة 2017).
عبد الفتاح السيسى$m229$,'68420e2166406914ddb2d63a26902b4a'),
(10,0,$m229$المادة 10$m229$,$m229$تعفى من ضريبة الدمغة ومن رسوم التوثيق والشهر عقود تأسيس الشركات والمنشآت وعقود التسهيلات الإئتمانية والرهن المرتبطة بأعمالها، وذلك لمدة خمس سنوات من تاريخ قيدها فى السجل التجارى.
كما تعفى من الضريبة والرسوم المشار إليها عقود تسجيل الأراضى اللازمة لإقامة الشركات والمنشآت.
وتسرى على الشركات والمنشآت الخاضعة لأحكام هذا القانون أحكام المادة (4) من قانون تنظيم الإعفاءات الجمركية الصادرة بالقانون رقم 186 لسنة 1986 الخاصة بتحصيل ضريبة جمركية بفئة موحدة مقدارها (2%) اثنان بالمائة من القيمة، وذلك على جميع ما تستورده من آلات ومعدات وأجهزة لازمة لإنشائها.
كما تسرى هذه الفئة الموحدة على جميع ما تستورده الشركات والمنشآت التى تعمل فى مشروعات المرافق العامة، من آلات ومعدات وأجهزة لازمة لإنشائها أو إستكمالها.
ومع عدم الإخلال بأحكام الافراج المؤقت المنصوص عليها فى قانون الجمارك الصادر بالقانون رقم 66 لسنة 1963، يكون للمشروعات الاستثمارية ذات الطبيعة الصناعية الخاضعة لأحكام هذا القانون استيراد القوالب والأسطمبات وغيرها من مستلزمات الإنتاج ذات الطبيعة المماثلة دون رسوم جمركية وذلك لاستخدامها فترة مؤقتة فى تصنيع منتجاتها، وإعادة تصديرها إلى الخارج.
ويكون الإفراج والإعادة إلى الخارج بموجب مستندات الوصول، على أن تسجل مستندات الدخول وإعادة الشحن فى سجلات تعد لهذا الغرض بالهيئة وذلك بالتنسيق مع وزارة المالية.$m229$,'029ea63612fa097e8a54fc22ac9a90f5'),
(11,0,$m229$المادة 11$m229$,$m229$تمنح المشروعات الاستثمارية التى تقام بعد العمل بهذا القانون وفقا للخريطة الاستثمارية، حافزا استثماريا خصما من صافى الأرباح الخاضعة للضريبة، على النحو الآتى:
1 - نسبة (50%) خصما من التكاليف الاستثمارية للقطاع (أ):
ويشمل المناطق الجغرافية الأكثر احتياجا للتنمية طبقا للخريطة الاستثمارية وبناء على البيانات والإحصاءات الصادرة من الجهاز المركزى للتعبئة العامة والإحصاء، المعتمدة بالخطة العامة للتنمية الاقتصادية والاجتماعية ووفقا لتوزيع أنشطة الاستثمار بها على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.
2 - نسبة (30%) خصما من التكاليف الاستثمارية للقطاع (ب):
ويشمل باقى أنحاء الجمهورية وفقا لتوزيع أنشطة الاستثمار، وذلك للمشروعات الاستثمارية الآتية:
المشروعات كثيفة الاستخدام للعمالة وفقا للضوابط المنصوص عليها فى اللائحة التنفيذية لهذا القانون.
المشروعات المتوسطة والصغيرة.
المشروعات التى تعتمد على الطاقة المتجددة أو تنتجها.
المشروعات القومية والاستراتيجية التى يصدر بتحديدها قرار من المجلس الأعلى.
المشروعات السياحية التى يصدر بتحديدها قرار من المجلس الأعلى.
مشروعات إنتاج الكهرباء، وتوزيعها التى يصدر بتحديدها قرار من رئيس مجلس الوزراء بناء على عرض مشترك من الوزير المختص والوزير المعنى بشئون الكهرباء ووزير المالية.
المشروعات التى يصدر إنتاجها إلى خارج الإقليم الجغرافى لجمهورية مصر العربية.
صناعة السيارات والصناعات المغذية لها.
الصناعات الخشبية والأثاث والطباعة والتغليف والصناعات الكيماوية.
صناعات المضادات الحيوية وأدوية الأورام ومستحضرات التجميل.
الصناعات الغذائية والحاصلات الزراعية وتدوير المخلفات الزراعية.
الصناعات الهندسية والمعدنية والنسيجية والجلود.
وفى جميع الاحوال يجب ألا يجاوز الحافز الاستثمارى (80%) من رأس المال المدفوع حتى تاريخ بدء مزاولة النشاط وذلك وفقا لأحكام قانون الضريبة على الدخل الصادر بالقانون رقم 91 لسنة 2005.
كما يجب الاتزيد مدة الخصم على سبع سنوات من تاريخ بدء مزاولة النشاط.
ويصدر رئيس مجلس الوزراء قرارا بناء على عرض مشترك من الوزير المختص ووزير المالية والوزير المعنى، بتحديد توزيع القطاعات الفرعية لأنشطة الاستثمار بالقطاعين (أ)، و (ب) المشار إليهما.
وتبين اللائحة التنفيذية لهذا القانون مفهوم التكلفة الاستثمارية، والنطاق الجغرافى للقطاعين (أ) و (ب)، وشروط منح الحوافز الخاصة وضوابطه، وتدرج بها أنشطة الاستثمار الفرعية التى يتضمنها قرار رئيس مجلس الوزراء المشا إلية فور صدوره.
وتجوز إضافة أنشطة جديدة للتمتع بالحوافز الخاصة بقرار من المجلس الأعلى.
*البند (1) معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'94de46e68bcd70f64f2238bb6887604f'),
(11,1,$m229$المادة 11 مكرراً$m229$,$m229$مع عدم الإخلال بالحوافز والمزايا والإعفاءات المنصوص عليها فى هذا الفصل، تمنح المشروعات الاستثمارية التي تزاول أحد الأنشطة الصناعية التي يتم تحديدها وفقا لهذه المادة، وتوسعاتها وفقا لحكم الفقرة الأخيرة من المادة (12) من هذا القانون، حافزا استثماريا نقديا لا يقل عن نسبة (35%) ولا يجاوز نسبة (55%) من قيمة الضريبة المسددة مع الإقرار الضريبي على الدخل المتحقق من مباشرة النشاط فى المشروع الاستثمارى، أو توسعاته بحسب الأحوال، وتلتزم وزارة المالية بصرف الحافز خلال خمسة وأربعين يوما من نهاية الأجل المحدد لتقديم الإقرار الضريبى، وإلا استحق عليها مقابل تأخير يحسب على أساس سعر الائتمان والخصم المعلن من البنك المركزي فى الأول من يناير السابق على تاريخ استحقاق الحافز مع استبعاد كسور الشهر والجنيه، ولا يعد هذا الحافز دخلا خاضعا للضريبة.
ويشترط لمنح الحافز المنصوص عليه فى هذه المادة أن يعتمد المشروع، أو توسعاته، بحسب الأحوال، فى تمويله حتى تاريخ بدء مزاولة النشاط، على النقد الأجنبي من الخارج بنسبة (50%) على الأقل من أمواله، وأن يبدأ مزاولة النشاط خلال ست سنوات من تاريخ العمل بهذه المادة، ويجوز مد هذه المدة بحد أقصى ست سنوات بقرار من مجلس الوزراء، بناء على عرض مشترك من الوزير المختص والوزير المعنى بشئون الصناعة ووزير المالية.
ويصدر مجلس الوزراء، بناء على عرض مشترك من الوزير المختص والوزير المعنى بشئون الصناعة ووزير المالية، قرارا يتضمن الصناعات والمناطق التى تتمتع بالحافز المنصوص عليه فى هذه المادة، ومدد منح الحافز لكل منها بما لا يجاوز عشر سنوات، وكذا شروط وقواعد وفئات منح الحافز وآليات صرفه.
*مضافة بوجب قانون رقم 160 لسنة 2023.$m229$,'c06e5468f6de3b8182c83c1fd4673d4e'),
(12,0,$m229$المادة 12$m229$,$m229$يشترط لتمتع المشروعات الاستثمارية بالحوافز الخاصة المنصوص عليها فى المادة (11) من هذا القانون، توافر الشروط الآتية:
1 - أن يتم تأسيس شركة أو منشأة جديدة لإقامة المشروع الاستثمارى.
2 - أن تؤسس الشركة أو المنشأة خلال مدة أقصاها ثلاث سنوات من تاريخ العمل باللائحة التنفيذية لهذا القانون، ويجوز بقرار من مجلس الوزراء، بناء على عرض الوزير المختص، مد هذه المدة لمدد أخرى لا يجاوز مجموعها تسع سنوات.
3 - أن تمسك الشركة أو المنشأة حسابات منتظمة، وإذا كانت الشركة أو المنشأة تعمل فى أكثر من منطقة فلها أن تستفيد بالنسبة المقررة لكل منطقة بشرط أن يكون لكل منطقة حسابات مستقلة.
4 - ألا يكون أى من المساهمين أو الشركاء أو أصحاب المنشآت قد قدم أو ساهم أو استخدم فى إنشاء أو تأسيس أو إقامة المشروع الاستثمارى المتمتع بالحافز أيا من الأصول المادية لشركة أو منشأة قائمة وقت العمل بأحكام هذا القانون أو قام بتصفية تلك الشركة أو المنشأة خلال المدة المبينة بالبند (2) من هذه المادة بغرض إنشاء مشروع استثمارى جديد يتمتع بالحوافز الخاصة المشار إليها، ويترتب على مخالفة ذلك سقوط التمتع بالحافز المشار إليه والتزام الشركة أو المنشأة بسداد جميع المستحقات الضريبية.
ويجوز أن تتمتع توسعات المشروعات الاستثمارية القائمة بالفعل بالحوافز المنصوص عليها فى المادتين (11)، (13) من هذا القانون، ويقصد بالتوسعات فى حكم هذه المادة زيادة رأس المال المستخدم بإضافة أصول جديدة تؤدى إلى زيادة الطاقة الإنتاجية للمشروع، وذلك كله طبقا للقواعد والشروط التى يصدر بتحديدها قرار من مجلس الوزراء.
*البند (2) معدلة بوجب قانون رقم 160 لسنة 2023.
*الفقرة الأخيرة مضافة بموجب قانون رقم 141 لسنة 2019.$m229$,'eaaf9123b1455f35344adcfd5cd680fd'),
(13,0,$m229$المادة 13$m229$,$m229$مع عدم الإخلال بالحوافز والمزايا والإعفاءات المنصوص عليها فى هذا الفصل، يجوز بقرار من مجلس الوزراء منح حوافز إضافية للمشروعات المنصوص عليها فى المادتين (11 و 11 مكررا) من هذا القانون، وذلك على النحو الآتى:
1 - السماح بإنشاء منافذ جمركية خاصة لصادرات المشروع الاستثماري أو وارداته بالاتفاق مع وزير المالية.
2 - تحمل الدولة قيمة ما يتكلفه المستثمر لتوصيل المرافق إلى العقار المخصص للمشروع الاستثماري أو جزءا منها، وذلك بعد تشغيل المشروع.
3 - تحمل الدولة جزءا من تكلفة التدريب الفني للعاملين.
4 - رد نصف قيمة الأرض المخصصة للمشروعات الصناعية فى حالة بدء الإنتاج خلال عامين من تاريخ تسليم الأرض.
5 - تخصيص أراض بالمجان لبعض الأنشطة الاستراتيجية وفقا للضوابط المقررة قانونا فى هذا الشأن.
6 - الإعفاء من مقابل الانتفاع بالأراضى المخصصة لإقامة المشروع لمدة عشر سنوات كحد أقصى تبدأ من بداية التشغيل، وذلك بناء على عرض الوزير المختص.
ويجوز بقرار من رئيس مجلس الوزراء بناء على عرض الوزير المختص، إعفاء المشروعات المشار إليها فى المادتين (11 و 11 مكررا) من المساهمة فى تكاليف إنشاء البنية الأساسية والخدمات والمرافق العامة بنسبة لا تجاوز (50%) منها، وفقا للضوابط التي يصدر بتحديدها قرار من المجلس الأعلى.
ويجوز أن تتحمل الخزانة العامة نسبة لا تزيد على (50%) من مقابل استهلاك المشروع للمرافق الأساسية لمدة عشر سنوات كحد أقصى، وذلك وفقا للضوابط التي يصدر بتحديدها قرار من المجلس الأعلى.
كما يجوز بقرار من مجلس الوزراء بناء على عرض الوزير المختص استحداث حوافز أخرى غير ضريبية كلما دعت الحاجة إلى ذلك.
وتبين اللائحة التنفيذية لهذا القانون قواعد منح الحوافز الإضافية المقررة فى هذه المادة وضوابطه وشروطه.
*معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'96d426dc6405255096af7ddace4f5258'),
(14,0,$m229$المادة 14$m229$,$m229$يختص الرئيس التنفيذى للهيئة أو من يفوضه بإصدار الشهادة اللازمة للتمتع بالحوافز المنصوص عليها فى المواد (10، 11، 11 مكررا، 13) من هذا القانون للشركات والمنشآت الخاضعة لأحكامه.
وتعتبر هذه الشهادة نهائية ونافذة بذاتها دون حاجة إلى موافقة جهات أخرى ويتعين على جميع الجهات العمل بموجبها والالتزام بما ورد بها من بيانات.
*الفقرة الأولى معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'414e8d8ee888223de96342b1c1b581ac'),
(15,0,$m229$المادة 15$m229$,$m229$يحوز للمستثمر تحقيقا لأهداف التنمية الشاملة والمستدامة تخصيص نسبة من أرباحه السنوية لاستخدامها فى إنشاء نظام للتنمية المجتمعية، خارج مشروعه الاستثمارى، من خلال مشاركته فى كل المجالات الآتية أو بعضها:
1 - اتخاذ التدابير اللازمة لحماية البيئة وتحسينها.
2 - تقديم خدمات أو برامج فى مجالات الرعاية الصحية أو الاجتماعية أو الثقافية أو فى إحدى مجالات التنمية الأخرى.
3 - دعم التعليم الفنى أو تمويل البحوث والدراسات وحملات التوعية التى تستهدف تطوير الإنتاج وتحسينه بالاتفاق مع إحدى الجامعات أو مؤسسات البحث العلمى.
4 - التدريب والبحث العلمى.
ويعد ما ينفقه المستثمر من مبالغ فى إحدى المجالات المنصوص عليها فى الفقرة السابقة بما لا يجاوز نسبة (10%) من أرباحه السنوية الصافية من التكاليف والمصروفات واجبة الخصم وفقا لنص المادة (23) (بند 8) من قانون الضريبة على الدخل الصادر بالقانون رقم 91 لسنة 2005.
ويجوز للوزير المختص بالتنسيق مع الوزارات المعنية إنشاء قائمة لأفضل المشروعات الاستثمارية التى تقوم بأنشطة تنمية مجتمعية سواء من الناحية الجغرافية أو القطاعية أو غيرها ويعلن عنه للرأى العام.
وفى جميع الأحوال يحظر استخدام المشروعات أو البرامج أو الخدمات المقدمة بنظام المسئولية المجتمعية لتحقيق أغراض سياسية أو حزبية أو دينية أو تنطوى على تمييز بين المواطنين.
وتبين اللائحة التنفيذية للقانون ما يلزم من ضوابط وقواعد أخرى لتطبيق نظام المسئولية المجتمعية.$m229$,'5b259aa84f0c495e8f7695bdbc88a527'),
(16,0,$m229$المادة 16$m229$,$m229$تقترح الوزارة المختصة الخطة الاستثمارية، وتتضمن هذه الخطة وضع السياسات الاستثمارية موضع التطبيق، وأولويات مشروعات الاستثمار المستهدفة بما يتفق مع السياسة العامة للدولة وخطة التنمية الاقتصادية والاجتماعية، ونظم الاستثمار المطبقة، ويتم إقرارها من المجلس الأعلى.$m229$,'0f42c6a2a2a6a5a014c3a5d2a846336d'),
(17,0,$m229$المادة 17$m229$,$m229$تتضمن الخطة الاستثمارية وضع خريطة استثمارية تحدد نوعية، ونظام الاستثمار، وتعد الهيئة مشروع هذه الخريطة بالتنسيق والتعاون الكامل مع جميع أجهزة الدولة المعنية.
ويجب أن تشتمل الخريطة الاستثمارية على جميع البيانات والمعلومات اللازمة، وعلى الأخص طبيعة العقار وموقعه الجغرافي، النشاط، القطاع، التسعير، نظام التصرف، المرافق، المزايا والحوافز الممنوحة للنشاط، الضمانات، حجم السوق المستهدف، حوافز التصدير، الموافقات والتصاريح والتراخيص المطلوبة لمزاولة النشاط، الجهات المختصة بنشاط المشروع، المدد المقررة لاستخراجها، الرسوم ومقابل الخدمات المستحقة لحساب الجهات المختصة نظير هذه الموافقات أو التصاريح أو التراخيص وتقديم الخدمات، وتلتزم جميع جهات الولاية والجهات المعنية بنشاط المشروع، كل فى نطاق اختصاصه، بتزويد الهيئة بجميع البيانات اللازمة لإعداد هذه الخريطة.
ويجب مراجعة كل من الخطة والخريطة الاستثمارية مرة على الأقل كل ثلاث سنوات، وكلما دعت الحاجة لذلك بناء على اقتراح الهيئة.
*معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'b17786e6d83aaadb2961f8dd19d3124f'),
(18,0,$m229$المادة 18$m229$,$m229$تكون الإجراءات والمدد المنصوص عليها فى هذا القانون واجبة التطبيق عند الحصول على خدمات الاستثمار، دون أن يخل ذلك بتطبيق أى قوانين أو إجراءات تتيح للمستثمر الحصول على الموافقات أو التصاريح أو التراخيص بإجراءات أيسر أو خلال مدد زمنية أقل من المنصوص عليها فى هذا القانون ولائحته التنفيذية.$m229$,'fd239826aa9383160af7a6535e6fad33'),
(19,0,$m229$المادة 19$m229$,$m229$تصدر الهيئة خلال تسعين يوما من تاريخ العمل بهذا القانون وبعد التنسيق مع الجهات المختصة، دليلا يتضمن الشروط والإجراءات والمواعيد المقررة لتخصيص العقارات وإصدار الموافقات والتصاريح والتراخيص المتعلقة بالأنشطة الاستثمارية الخاضعة لأحكام هذا القانون، ويتاح هذا الدليل من خلال الموقع الإليكترونى للهيئة ومطبوعاتها المختلفة وغيرها من الجهات.
وتلتزم الهيئة بمراجعة هذا الدليل وتحديثه دوريا، وكلما دعت الحاجة إلى ذلك، فى ضوء التعديلات التى تطرأ على التشريعات السارية فى الدولة.
كما تلتزم الجهات المختلفة بموافاة الهيئة خلال ستين يوما علي الاكثر من تاريخ العمل بهذا القانون بجميع البيانات والمستندات والنماذج اللازمة لاعداد هذا الدليل.
وتحدد اللائحة التنفيذية لهذا القانون الضوابط الازمة في هذا الشأن.$m229$,'785a647ffd3e852a02489db41d3f3b5b'),
(20,0,$m229$المادة 20$m229$,$m229$مع عدم الإخلال بأحكام المادة (23) من هذا القانون، يجوز بقرار من مجلس الوزراء منح الشركات، أيا كان شكلها القانونى، القائمة أو التى تؤسس لإقامة مشروعات استثمارية جديدة، أو مشروعات استراتيجية أو قومية تسهم فى تحقيق التنمية فى المجالات وبالمعايير التى يصدر بتحديدها قرار من مجلس الوزراء، أو مشروعات المشاركة بين القطاع الخاص والدولة أو القطاع العام أو قطاع الأعمال العام فى أنشطة المرافق العامة والبنية التحتية أو الطاقة الجديدة والمتجددة أو الطرق والمواصلات أو الموانئ، موافقة واحدة على إقامة المشروع وتشغيله وإدارته بما فى ذلك تراخيص البناء، وتخصيص العقارات اللازمة له، وتكون هذه الموافقة نافذة بذاتها دون حاجة إلى اتخاذ أي إجراء آخر.
ويجوز أن تتضمن هذه الموافقة سريان حافز أو أكثر من الحوافز الواردة بهذا القانون على المشروع.
وتتولى الهيئة بمشاركة الجهات المختصة متابعة التزام الشركات المشار إليها فى الفقرة الأولى من هذه المادة باشتراطات وضوابط إقامة المشروع وتشغيله وإدارته وفقا للقوانين واللوائح المنظمة بمعرفة لجنة تشكل لهذا الغرض، وفى حالة مخالفة الشركة للاشتراطات والضوابط المشار إليها، وجب إنذارها بموجب خطاب مسجل مصحوب بعلم الوصول بالمخالفات المنسوبة إليها، وسماع أوجه دفاعها، وإعطاؤها مهلة مناسبة لإزالة أسباب المخالفة أو تصحيحها، فإذا انقضت هذه المهلة دون قيام الشركة بإزالتها أو تصحيحها، يجوز وقف تنفيذ أعمال المشروع أو نشاطه، أو وقف تمتعه بحافز أو أكثر من الحوافز المقررة له، وذلك بحسب جسامة المخالفة لمدة محددة لا تجاوز سنة، فإن استمرت ذات المخالفة، يجوز بقرار من مجلس الوزراء بناء على عرض مشترك من الوزير المختص والوزير المعنى إلغاء الموافقة الواحدة الصادرة للشركة.
وتبين اللائحة التنفيذية لهذا القانون شروط وضوابط وإجراءات تطبيق أحكام هذه المادة.
*معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'385376c717805a84abb6a77b98746921'),
(21,0,$m229$المادة 21$m229$,$m229$تنشأ بالهيئة وفروعها، لتبسيط إجراءات الأستثمار وتيسيرها، وحدة إدارية تسمى (مركز خدمات المستثمرين).
ويتولى المركز تقديم خدمات تأسيس الشركات وإنشاء فروعها واعتماد محاضر مجالس الإدارة والجمعيات العامة وزيادة رأس المال وتغيير النشاط وأعمال التصفية وغيرها من المسائل المتصلة بالشركات.
كما يتولى المركز تلقى طلبات المستثمرين لإصدار الموافقات والتصاريح وتخصيص العقارات والتراخيص اللازمة بأنواعها لإنشاء المشروعات الإستثمارية أو إدارتها، والبت فيها طبقا للقوانين واللوائح خلال المواعيد المنصوص عليها فى هذا القانون.
وتقدم تدريجيا وفى أسرع وقت ممكن خدمات المركز بطريقة مميكنة وآلية وفقا لما تحدده اللائحة التنفيذية من خلال شبكات الربط الإلكترونى وغيرها من الوسائل الفنية اللازمة.
ويضم المركز ممثلين عن الجهات المختصة بحسب القوانين المنظمة، ويخضع ممثلو تلك الجهات لإشراف الهيئة خلال فترة وجودهم بمركز خدمات المستثمرين ويلتزمون بالقواعد والضوابط التى يضعها مجلس إدارة الهيئة لتنظيم عمل المركز.
واستثناء من أحكام أى قانون آخر، تنتقل الى ممثلى الجهات المختصة بموجب أحكام هذا القانون سلطة إصدار الموافقات والتصاريح والتراخيص، بحسب الاشتراطات الفنية الواردة بالقوانين المنظمة لها ودليل إجراءات الاستثمار الذى تصدره الهيئة، وكذا جميع الصلاحيات المقررة للسلطة المختصة فى مجال تخصيص العقارات وإعطاء الموافقات والتصاريح والتراخيص اللازمة لعمل المستثمر والاستثمار وفقا لاحكام هذا القانون.
ويحدد مجلس ادارة الهيئة الجهات الحكومية وشركات المرافق العامة التى يتكون منها مركز خدمات المستثمرين، ويقوم الرئيس التنفيذى للهيئة بالتنسيق مع تلك الجهات لتحديد العدد اللازم من العاملين الأصليين والاحتياطيين لتمثيلها فى المركز ودرجاتهم الوظيفية التى تسمح لهم باداء واجباتهم فى مركز خدمات المستثمرين، كما تحدد اللائحة التنفيذية ضوابط اختيار هؤلاء العاملين وطريقة إلحاقهم بالمركز.
وفى غير حالات تقديم شهادات الإعتماد المنصوص عليها فى المواد التالية يجب على ممثلى الجهات بمركز خدمات المستثمرين والموظفين المسئولين بالجهات الإدارية طلب استيفاء المستندات اللازمة لاستخراج الموافقات أو التصاريح أو التراخيص خلال يومى عمل من تاريخ تقديمهما إليهم، وإلا اعتبرت مستوفاة، ولا يجوز طلب أى مستندات إضافية من المستثمر بعد مرور تلك المدة.
وفى جميع الأحوال يكون من حق المستثمر أن يقوم باستيفاء الإشتراطات الفنية وغيرها من الاشتراطات والإجراءات اللازمة للاستثمار عن طريق مكاتب الاعتماد، أو باللجوء مباشرة الى الجهات المختصة أو من خلال ممثليها بمركز خدمات المستثمرين.$m229$,'65cbfda0f66be7c9018f3e871b5ecf6f'),
(22,0,$m229$المادة 22$m229$,$m229$يجوز لطالب الاستثمار أو من ينوب عنه، أن يعهد الى مكاتب الاعتماد المرخص لها من الهيئة بفحص المستندات الخاصة بالحصول على الموافقات والتصاريح والتراخيص اللازمة لإنشاء المشروع الاستثمارى وتشغيله والتوسع فيه، لتحديد مدى استيفائه الاشتراطات الفنية والمالية اللازمة وغيرها من الاجراءات المنصوص عليها فى أحكام هذا القانون والقوانين المنظمة لمنح الموافقات والتصاريح والتراخيص.
وتلتزم مكاتب الاعتماد فى ممارسة عملها بقواعد المسئولية المهنية التى تحددها اللائحة التنفيذية، وعلى الأخص القواعد الآتية:
الالتزام بأحكام القوانين والقرارات ذات الصلة.
بذل العناية الواجبة فى الفحص والاستيفاء والاعتماد.
تجنب تعارض المصالح.
الحفاظ على سرية وخصوصية المعلومات المتعلقة بطالبى الاعتماد.
ويجوز أن تعمل مكاتب الاعتماد منفردة أو بالإشتراك مع مجموعة من مكاتب الاعتماد المتخصصة.
وتحدد اللائحة التنفيذية لهذا القانون الشكل القانونى لمكاتب الاعتماد.
ويصدر الترخيص لمكاتب الاعتماد التى يتوافر لديها الخبرة اللازمة لممارسة هذا النشاط وفقا للشروط والقواعد والاجراءات التى تحددها اللائحة التنفيذية لهذا القانون بما فى ذلك الالتزام بابرام وثيقة تأمين سنوية لتغطية المخاطر والأضرار الناتجة عما تقوم به هذه المكاتب من أنشطة وأسس تحدد مقابل الخدمات التى تقوم بتقديمها.
وينشأ بالهيئة سجل خاص تقيد فيه مكاتب الاعتماد المرخص لها توافى به الجهات الإدارية المختصة.
ويكون الترخيص لمكاتب الاعتماد مقابل رسم لا يجاوز عشرين ألف جنيه تحدد فئاته اللائحة التنفيذية، ويجدد الترخيص سنويا، ويسرى على تجديد الترخيص ذات الرسوم المقررة لمنح التراخيص.
وتصدر مكاتب الاعتماد للمستثمر وعلى مسئوليتها شهادة اعتماد صالحة لمدة عام، تتضمن بيان مدى استيفاء المشروع الاستثمارى كل شروطه أو بعضها طبقا للقوانين واللوائح المنظمة لإصدار الموافقات والتصاريح والتراخيص، على أن تقوم بارسال نسخة الى الجهة المختصة بالطريقة التى تبينها اللائحة التنفيذية لهذا القانون.
ولا يعتد بالشهادات التى تقدم بعد مضى عام من تاريخ صدورها.
وتكون هذه الشهادة مقبولة لدى الجهة المختصة وممثلها بمركز خدمات المستثمرين وغيرها من الجهات الإدارية، ولا يحول ذلك دون إبداء الجهة المختصة أو ممثلها اعتراضا مسببا على الشهادة المشار إليها، فى موعد غايته عشرة أيام عمل من تاريخ تقديمها، وفى حالة إنقضاء هذه المدة دون رد، اعتبر ذلك قبولا لطلب المستثمر يصدر به موافقة من الرئيس التنفيذى للهيئة، وذلك على النحو المنصوص عليه فى المادة (25) من هذا القانون.
وتعتبر هذه الشهادة محررا رسميا فى تطبيق أحكام قانون العقوبات.
ومع عدم الإخلال بالمسئولية المدنية أو الجنائية بحسب الأحوال، يترتب على إصدار هذه الشهادة على خلاف الحقيقة أو بالمخالفة للقواعد المنصوص عليها فى المادة (25) من هذا القانون، استحقاق قيمة التأمين وصرفها للمستفيدين منها وشطب المكتب الصادرة عنه من سجل القيد لدى الهيئة مدة لا تجاوز ثلاث سنوات بقرار من مجلس إدارة الهيئة وفى حالة تكرار ارتكاب المخالفة يكون الشطب نهائيا من السجل.
وذلك كله على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.$m229$,'a0e18cd7726f0aa7687006ac2ea1c0a8'),
(23,0,$m229$المادة 23$m229$,$m229$يؤدى المستثمر للهيئة جميع الرسوم وغيرها من المبالغ التى تفرضها القوانين، لحساب الجهات التى تقدم خدمات الإستثمار.
وتستحق الهيئة مقابلا لما تؤديه للمستثمرين من خدمات فعلية، ويصدر مجلس إدارة الهيئة قرارا بتحديد فئات هذا المقابل والقواعد والشروط والإجراءات المنظمة لتحصيله.$m229$,'3c65e7f88e9230f9e4593caed270e67d'),
(24,0,$m229$المادة 24$m229$,$m229$مع عدم الإخلال بالمدد المقررة للبت فى الطلب المرفق به شهادة من أحد مكاتب الاعتماد، تتولى الجهات المختصة فحص طلبات الاستثمار التى تقدم اليها من خلال مركز خدمات المستثمرين، والتأكد من مدى توافر الشروط اللازمة لقبولها على النحو المبين فى هذا القانون، ويجب البت فيها مدة لا تتجاوز ستين يوما من تاريخ تقديم الطلب مستوفيا جميع مستنداته، وفى حالة إنقضاء هذه المدة دون قرار منها، اعتبر ذلك قبولا لطلب المستثمر يصدر به موافقة من الرئيس التنفيذى للهئية وذلك على النحو المنصوص عليه فى المادة (25) من هذا القانون.
وفى جميع الأحوال، يجب إخطار مقدم الطلب بالقرار الصادر فى طلبه سواء بالموافقة أو الرفض، بموجب خطاب مسجل بعلم الوصول، خلال سبعة أيام من تاريخ إنقضاء المدة المنصوص عليها فى الفقرة الأولى من هذة المادة.
ولذوى الشأن التظلم من قرار الرفض أمام اللجنة المنصوص عليها فى المادة (83) من هذا القانون.$m229$,'21672cf832129b66c5f0aa127cecb5fd'),
(25,0,$m229$المادة 25$m229$,$m229$يتولى الرئيس التنفيذى للهيئة إصدار الموافقات المنصوص عليها فى المادتين (22، 24) من هذا القانون على النموذجين المعدين لهذا الغرض، وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.$m229$,'bd0ad38b7e410109ed6eab3e5e5c4a2d'),
(26,0,$m229$المادة 26$m229$,$m229$فى إطار خطة التنمية الاقتصادية للدولة أو لأغراض استكمال الخريطة الاستثمارية، يجور للهيئة استخراج الموافقات أو التصاريح أو التراخيص اللازمة لإقامة النشاط على قطع الأراضى المخصصة للاستثمار قبل تخصيصها للمستثمرين، وفى هذة الحالة تحصل قيمة الرسوم وغيرها من الاعباء المالية المستحقة لحساب الجهات المختصة نظير هذة الموافقات أو التصاريح أو التراخيص من المستثمر عند اتمام اجراءات تخصيص الأرض، ويتعين على هذه الجهات الالتزام بتيسير إجراءات منح تلك الموافقات أو التصاريح أو التراخيص وفقا للإجراءات والمواعيد التى تحددها اللائحة التنفيذية لهذا القانون.$m229$,'51c4ce22ad7f4096eb88ae18a4dc8486'),
(27,0,$m229$المادة 27$m229$,$m229$يلتزم العاملون القائمون على تنفيذ أحكام هذا القانون، فى جميع الجهات المختصة ذات الصلة بمراعاة الأهداف والمبادئ والإجراءات والمواعيد الواردة به وبلائحته التنفيذية.
ويكون تيسير الاجراءات على المستثمرين وسرعة و إنجاز مصالحهم المشروعة، من المؤشرات الأساسية لقياس أداء هؤلاء العاملين وأحد سبل تحديد مسئوليتهم الوظيفية.$m229$,'c99ff47f4547cb4ed75e5081696bf9b3'),
(28,0,$m229$المادة 28$m229$,$m229$يجوز بقرار من رئيس مجلس الوزراء بناء على اقتراح مجلس ادارة الهيئة وعرض الوزير المختص والوزير المعنى إنشاء مناطق استثمارية متخصصة فى مختلف مجالات الاستثمار بما فيها المناطق اللوجيستية والزراعية والصناعية، على أن يتضمن قرار إنشاء المنطقة موقعها وإحداثياتها وطبيعة الأنشطة التى تزوال فيها، والمدة التى يجب اتخاذ الإجراءات اللازمة لإنشاء المنطقة خلالها، بالإضافة الى أى شروط عامة ترتبط بمزاولة تلك الأنشطة.
وعلى المطور الذى يتولى أمر المنطقة الاستثمارية اتخاذ الاجراءات اللازمة نحو إنشائها وفقا للبرنامج الزمنى للتنفيذ المحدد بالترخيص وإلا اعتبر الترخيص كأن لم يكن.
ويجوز بقرار من رئيس مجلس الوزراء أو من يفوضه منح المرخص له مهلة إضافية فى ضوء المبررات المقدمة منه بعد موافقة مجلس إدارة الهيئة.
وتسرى على المشروعات العاملة داخل المناطق الاستثمارية، أحكام البابين الأول والثانى من هذا القانون، وذلك فيما لا يتعارض مع طبيعة العمل بأحكام هذا النظام.
كما تسرى عليها القواعد الخاصة بالسماح الجمركى المؤقت والدورباك الواردة بالقوانين واللوائح والقرارات المنظمة لذلك.
وتجوز إضافة أنشطة أخرى بقرار من رئيس مجلس الوزراء بناء على عرض الوزير المختص.$m229$,'35df450042e67ec1dded5094a4a14509'),
(29,0,$m229$المادة 29$m229$,$m229$يكون لكل منطقة استثمارية مجلس إدارة يصدر بتشكيله قرار من الوزير المختص بالاتفاق مع الوزير المعنى بحسب نوع وتخصص المنطقة.
ويختص مجلس لإدارة المنطقة بوضع خطة عمل المنطقة والضوابط والمعايير اللازمة لممارسة النشاط، واعتمادها من مجلس إدارة الهيئة، كما يختص بالموافقة على إقامة المشروعات الاستثمارية داخل حدود المنطقة، كما يلتزم مجلس الادارة بتقديم تقارير ربع سنوية الى الهيئة وفقا لما تحدده اللائحة التنفيذية، ويرسل محاضر اجتماعات مجلس الإدارة لاعتمادها من الهيئة.
ولمجلس إدارة المنطقة أن يرخص لشركات من القطاع الخاص بتنمية تلك المناطق وإدارتها أو الترويج للاستثمار بها.
ويلتزم أعضاء مجلس الإدارة بالإفصاح عن جميع اموالهم، على أن يتم تقديم هذا الإفصاح ومراجعته سنويا من جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلى أو محتمل للمصالح، على أن يرفع بذلك تقرير الى المجلس الأعلى عن طريق الوزير المختص.$m229$,'ce93ae89f73df4b069458757866a5a3f'),
(30,0,$m229$المادة 30$m229$,$m229$يكون للمنظمة الاستثمارية مكتب تنفيذى من العاملين بالهيئة يصدر بهم قرار من الرئيس التنفيذى للهيئة باعتماد من الوزير المختص، ويتولى المكتب تنفيذ قرارات مجلس إدارة المنطقة فيما يخص الموافقات والتصاريح والتراخيص اللازمة ومتابعة تنفيذها وإصدار تراخيص البناء للمشروعات داخل حدود المنطقة.
ويؤدى المستثمر للهئية مقابلا عن كل خدمة فعلية يقدمها المكتب التنفيذى بما لا يجاوز واحدا فى الألف من التكاليف الاستثمارية عن جميع الخدمات المقدمة، وذلك على النحو الذى تحدده اللائحة التنفيذية لهذا القانون.$m229$,'37fe2cb6df457c70c333ca5b391b4aae'),
(31,0,$m229$المادة 31$m229$,$m229$يختص رئيس مجلس إدارة المنطقة، فضلا عما هو منوط به، بالترخيص للمشروعات داخل حدود المنطقة الاستثمارية بمزاولة نشاطها.
ويجب أن يتضمن الترخيص بيانا بالأغراض التى منح من اجلها ومدة سريانه ولا يجوز النزول عن الترخيص كليا أو جزئيا إلا بموافقة مجلس إدارة المنطقة الاستثمارية ويكون رفض منح الترخيص أو عدم الموافقة على النزول عنه بقرار مسبب، ولصاحب الشأن أن يتظلم منه الى اللجنة المنصوص عليها بالمادة (83) من هذا القانون.
ويكتفى بهذا الترخيص عند التعامل مع أجهزة الدولة المختلفة للحصول على الخدمات والتيسيرات والمزايا والإعفاءات للمشروع دون حاجة للقيد بالسجل الصناعى، ما لم يطلب المستثمر غير ذلك، مع إخطار الجهة المختصة بصورة من الترخيص لأغراض الحصر، ولا يجوز لأى جهة إدارية أخرى اتخاذ أى اجراءات داخل المناطق الاستثمارية أو المشروعات العاملة داخلها إلا بعد موافقة الهيئة.
ولا يتمتع المرخص له بالضمانات والحوافز والمزايا المنصوص عليها فى هذا القانون الا فى حدود الأغراض المبينة فى الترخيص.$m229$,'bfcdf55d050148add5c14a48c2f1c7f7'),
(32,0,$m229$المادة 32$m229$,$m229$لرئيس مجلس الوزراء بناء على اقتراح مجلس إدارة الهيئة وبطلب من الوزير المعني بشئون الاتصالات وتكنولوجيات المعلومات الترخيص بإنشاء مناطق تكنولوجية في مجال صناعة تكنولوجيا المعلومات والاتصالات بما تشمله من أنشطة صناعية وتصميم وتطوير الإلكترونيات ومراكز البيانات وأنشطة التعهيد وتطوير البرمجيات والتعليم التكنولوجي وغيرها من الأنشطة المرتبطة بها أو المكملة لها وذلك كله وفقا لما تبينه اللائحة التنفيذية لهذا القانون.
وتجوز إضافة أنشطة أخرى بقرار من رئيس مجلس الوزراء بناء على عرض مشترك من الوزير المختص والوزير المعنى بشئون الاتصالات وتكنولوجيا المعلومات.
ولا تخضع جميع الأدوات والمهمات والآلات اللازمة لمزاوالة النشاط المرخص به للمشروعات المتواجدة داخل المناطق التكنولوجية بجميع أن واعها للضرائب والرسوم الجمركية، وفقا للشروط والإجراءات التي تبينها اللائحة التنفيذية.
وتتمتع المشروعات المقامة في المناطق التكنولوجية بالحوافز الخاصة المنصوص عليها في المادة (11) من هذا القانون بحسب القطاع المقامة به.
ويكون لكل منطقة مجلس إدارة يصدر بتشكيله قرار من الوزير المختص بشؤون الاتصالات وتكنولوجيا المعلومات بالاتفاق مع الوزير المختص، ويختص مجلس إدارة المنطقة بوضع الضوابط والمعايير اللازمة لممارسة النشاط، كما يختص بالموافقة على إقامة المشروعات داخل حدود المنطقة.
ويلتزم أعضاء مجلس الإدارة بالإفصاح عن جميع أموالهم، على أن يتم تقديم هذا الإفصاح ومراجعته سنويا من جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلي أو محتمل للمصالح، على أن يرفع بذلك تقرير إلى المجلس الأعلى عن طريق الوزير المختص.
وتسري على الاستثمار بنظام المناطق التكنولوجية أحكام البابين الأول والثاني من هذا القانون فيما لا يتعارض مع طبيعة العمل بهذا النظام.
وتبين اللائحة التنفيذية لهذا القانون اشتراطات وضوابط العمل فيها وأسلوب إدارتها.$m229$,'26f12cb6c668ed91f6fae1e907af87f7'),
(33,0,$m229$المادة 33$m229$,$m229$يكون إنشاء المنطقة الحرة التي تشمل مدينة بأكملها بقانون.
ولمجلس الوزراء بناء على عرض الوزير المختص بعد موافقة مجلس إدارة الهيئة إنشاء مناطق حرة عامة لإقامة المشروعات التى يرخص بها، أيا كان شكلها القانوني، تهدف بالأساس إلى التصدير خارج البلاد، ويجب أن يتضمن القرار الصادر بإنشاء المنطقة الحرة بيانا بموقعها وحدودها.
ويتولى إدارة المنطقة الحرة العامة مجلس إدارة يصدر بتشكيله وتعيين رئيسه قرار من الرئيس التنفيذي للهيئة باعتماد من الوزير المختص، ويقوم أعضاء مجلس الإدارة بالإفصاح عن أموالهم، على أن يقدم ويراجع هذا الإفصاح سنويا من قبل جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلي أو محتمل للمصالح، على أن يرفع بذلك تقرير إلى المجلس الأعلى عن طريق الوزير المختص.
ويختص مجلس إدارة المنطقة الحرة العامة على الاخص باقتراح اللوائح والنظم اللازمة لإدارة المنطقة الحرة، واعتمادها من مجلس إدارة الهيئة، وتنفيذ أحكام هذا القانون ولائحته التنفيذية التي تصدرها الهيئة.
كما يجوز لمجلس الوزراء بناء على عرض الوزير المختص الموافقة على إنشاء مناطق حرة خاصة تقتصر كل منها على مشروع أو أكثر في أنشطة مماثلة متى اقتضت طبيعتها ذلك، وتنظم اللائحة التنفيذية سائر أوضاع العمل بالمناطق الحرة الخاصة بما يضمن حسن قيامها بأعمالها وحوكمتها.$m229$,'eb643f0504cfe176ac474b72c94abc9e'),
(34,0,$m229$المادة 34$m229$,$m229$مع عدم الإخلال بأحكام القانون رقم 133 لسنة 2010 بالترخيص لمشروعات تكرير البترول بالعمل بنظام المناطق الحرة، ومع مراعاة المراكز القانونية للشركات المرخص لها بإقامة مشروعات بنظام المناطق الحرة القائمة وقت العمل بهذا القانون، يجوز بعد موافقة المجلس الأعلى للطاقة الترخيص بإقامة مشروعات بنظام المناطق الحرة فى مجال تصنيع البترول، وصناعات الأسمدة، والحديد والصلب، وتصنيع وتسييل ونقل الغاز الطبيعي والصناعات كثيفة استخدام الطاقة.
ولا يجوز الترخيص بإقامة مشروعات بنظام المناطق الحرة فى مجال صناعات الخمور والمواد الكحولية، وصناعات الأسلحة والذخائر والمتفجرات وغيرها مما يرتبط بالأمن القومى.
*معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'84f1a4eb9121d975ef9a10805ea686e4'),
(35,0,$m229$المادة 35$m229$,$m229$مع عدم الإخلال بنص الفقرة الأولى من المادة (10) من هذا القانون، تخضع جميع المشروعات التي تستثمر بنظام المناطق الحرة للرقابة الجمركية والضريبية وفقا للقواعد التي يصدر بها قرار من مجلس إدارة الهيئة بالتنسيق مع مصلحتي الجمارك والضرائب المصرية.
ويلتزم مجلس إدارة المنطقة الحرة بإخطار الجهات التي يحددها الوزير المعنى بشئون الصناعة بجميع البيانات المتعلقة بالمشروعات الإنتاجية الصناعية التى تقام بالمناطق الحرة، ويكون للوزير المختص بالتفاق مع الوزير المعنى بشئون الصناعة وضع ضوابط مباشرة المشروعات الإنتاجية الصناعية لأنشطتها، وعلى الأخص ما تلتزم به هذه المشروعات من نسب تصديرية.$m229$,'acdc17fb11e4f57f55a7322684e8916f'),
(36,0,$m229$المادة 36$m229$,$m229$مع مراعاة أحكام قانون سوق رأس المال الصادر بقانون رقم 95 لسنة 1992، وقانون البنك المركزى والجهاز المصرفي والنقد الصادر بالقانون رقم 88 لسنة 2003، والقانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية، يختص مجلس إدارة المنطقة الحرة العامة بالموافقة النهائية على إقامة المشروعات داخل المنطقة، أو في المنطقة الحرة الخاصة التي تقع في نطاقها الجغرافى، ويختص رئيس مجلس إدارة المنطقة بالترخيص لها بمزاولة نشاطها.
ويجب أن يتضمن الترخيص بيانا بالأغراض التي منح من اجلها و مدة سريانه ومقدار ونوع الضمان المالى الذي يؤديه المرخص له بما لا يجاوز اثنان بالمائة (2%) من التكاليف الاستثمارية وفقا للنسب التي تبينها اللائحة التنفيذية لهذا القانون، ولا يجوز النزول عن الترخيص كليا أو جزئيا، إلا بموافقة مجلس إدارة المنطقة.
ولا يتمتع المشروع المرخص له بالإعفاءات أو المزايا المنصوص عليها في القانون إلا في حدود الأغراض المبينة في الترخيص، ويكتفي بهذا الترخيص عند التعامل مع أجهزة الدولة المختلفة، للحصول على الخدمات والتيسيرات والمزايا للمشروع، دون حاجة للقيد بالسجل الصناعي، ما لم يتطلب المشروع ذلك، مع إخطار الجهة المختصة بصورة من هذا الترخيص لأغراض الحصر والإحصاء.$m229$,'0c50b0d89b880b2dc1fe7f16991e5993'),
(37,0,$m229$المادة 37$m229$,$m229$يكون تخصيص العقارات اللازمة لإقامة المشروعات للعمل بنظام المناطق الحرة العامة بنظام الترخيص بالأنتفاع وفقا للقواعد والأحكام التي تبينها اللائحة التنفيذية لهذا القانون.
وعلى المستثمر التقدم لإدارة المنطقة خلال ثلاثين يوما من تاريخ إبلاغه بالموافقة على إقامة مشروعه لاستلام الأرض لتنفيذ المشروع و التوقيع على عقد الأنتفاع وسداد القيمة المقررة.
وتسقط الموافقة على المشروع إذا لم يقم المستثمر باتخاذ إجراءات جدية في تنفيذ المشروع خلال تسعين يوما من تاريخ إخطاره باستلام الأرض وفقا للشروط المتفق عليها في عقد الأنتفاع، ويجوز مد هذه الفترة لمدة اخرى في ضوء المبررات التي يقدمها المستثمر أو من يمثله ويقدرها مجلس إدارة المنطقة الحرة.
وتبين اللائحة التنفيذية لهذا القانون الضوابط والإجراءات اللازمة لتنفيذ هذه الأحكام.$m229$,'a64e4a2d0851ea1497f7cd9caf4486fe'),
(38,0,$m229$المادة 38$m229$,$m229$يلتزم المستثمر بتسليم الأرض المخصصة له إلى إدارة المنطقة عند إلغاء المشروع أو سقوط الموافقة الصادرة له خالية من الإشغالات، وفي حالة وجود مبان أو منشآت أو موجودات بالموقع يلتزم بإخلائها على نفقته الخاصة خلال المدة التى يحددها مجلس إدارة المنطقة بما لا يجاوز ستة أشهر من تاريخ إخطاره بذلك بخطاب مسجل بعلم الوصول.
فإذا لم يقم بالإخلاء خلال هذه المدة، يصدر مجلس إدارة المنطقة قرارا باسترداد الأرض بالطريق الإدارى بما عليها من مبان وإنشاءات وتقوم إدارة المنطقة والجمارك فى حالة وجود موجودات بالموقع بجردها وحصرها وتسليمها إلى إدارة الجمارك للاحتفاظ بها مؤقتا أو بيعها وفقا لأحكام قانون الجمارك بشأن المهمل أو المتروك وإيداع ثمنها فى حساب لدى الهيئة لصالح المستثمر، بعد خصم مستحقات الهيئة ثم الديون الحكومية وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون، وتعتبر مستحقات الهيئة فى تطبيق أحكام هذه المادة من الديون الممتازة التالية للمصروفات القضائية ومستحقات الخزانة العامة.$m229$,'47da210900f7e8345681001b71a60d9e'),
(39,0,$m229$المادة 39$m229$,$m229$مع مراعاة الأحكام التى تقررها القوانين واللوائح بشأن منع تداول بعض البضائع والمواد، لا تخضع البضائع التى تصدرها مشروعات المنطقة الحرة إلى خارج البلاد أو تستوردها من خارج البلاد لمزاولة نشاطها لقواعد الخاصة بالاستيراد والتصدير و للإجراءات الجمركية الخاصة بالصادرات والواردات، كما لا تخضع للضرائب الجمركية والضريبة على القيمة المضافة وغيرها من الضرائب والرسوم.
ويكون تصدير مستلزمات الإنتاج من السوق المحلى إلى المشروعات الإنتاجية بالمناطق الحرة وفقا للقواعد التى يصدر بها قرار من الوزير المعنى بشئون التجارة الخارجية بالاتفاق مع الوزير المختص ووزير المالية.
وفيما عدا سيارات الركوب تعفى الضرائب الجمركية والضريبة على القيمة المضافة وغيرها من الضرائب والرسوم، جميع الأدوات والمهمات والآلات ووسائل النقل الضرورية بجميع أنواعها واللازمة لمزاولة النشاط المرخص به للمشروعات الموجودة داخل المناطق الحرة بجميع أنواعها و لو اقتضت طبيعة مزاولة هذا النشاط وضروراتها خروجها مؤقتا من المنطقة الحرة إلى داخل البلاد وإعادتها إليها وذلك بالنسبة إلى الأدوات والمهمات والآلات وفى الحالات وبالضمانات والشروط والإجراءات التى يصدر بها قرار من مجلس الوزراء بناء على عرض الوزير المختص ووزير المالية.
وتبين اللائحة التنفيذية لهذا القانون إجراءات نقل البضائع وتأمينها من بدء تفريغها حتى وصولها إلى المناطق الحرة وبالعكس.
وللهيئة السماح بإدخال البضائع والمواد والأجزاء والخامات المحلية والأجنبية، المملوكة للمشروع أو للغير من داخل البلاد إلى المنطقة الحرة مؤقتا لإصلاحها أو لإجراء عمليات صناعية عليها وإعادته للداخل دون خضوعها لقواعد الاستيراد المطبقة وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.
وتحصل الضريبة الجمركية على قيمة الإصلاح وفقا لأحكام القوانين الجمركية.$m229$,'3c40c12f4cb5d0681a7a766866d966db'),
(40,0,$m229$المادة 40$m229$,$m229$يكون الاستيراد من المناطق الحرة إلى داخل البلاد طبقا للقواعد العامة للاستيراد من الخارج.
واستثناء من ذلك، يسمح بدخول المواد والنفايات والمخلفات الناتجة عن أنشطة المشروعات العاملة بالمناطق الحرة إلى داخل البلاد متى كان دخولها إلى البلاد بغرض التخلص منها أو إعادة تدويرها على نفقة صاحب الشأن، وذلك بالطرق والوسائل الآمنة المقررة وفقا لقانونى البيئة الصادر بالقانون رقم 4 لسنة 1994، وتنظيم إدارة المخلفات الصادر بالقانون رقم 202 لسنة 2020
وتطبق أحكام قانون تنظيم إدارة المخلفات المشار إليه فى شأن حظر استيراد المخلفات الخطرة من الخارج، ولا يعد دخول المواد والنفايات والمخلفات الخطرة الناتجة عن أنشطة المشروعات العاملة بالمناطق الحرة إلى داخل البلاد بمثابة استيراد من الخارج فى حكم تطبيق هذه الفقرة.
وتؤدى الضرائب الجمركية على البضائع التى تستورد من المنطقة الحرة الى السوق المحلى كما لو كانت مستوردة من خارج البلاد.
اما المنتجات المستوردة من مشروعات المناطق الحرة والتى تشمل على مكونات محلية وأخرى أجنبية، فيكون وعاء الضريبة الجمركية بالنسبة لها هو قيمة المكونات الأجنبية بالسعر السائد وقت خروجها من المنطقة الحرة إلى داخل البلاد، بشرط ألا تزيد الضريبة الجمركية المستحقة على المكونات الأجنبية على الضريبة المستحقة على المنتج النهائى المستورد من الخارج.
وتتمثل المكونات الاجنبية فى الاجزاء والمواد الأجنبية المستوردة حسب حالتها عند الدخول الى المناطق الحرة دون حساب تكاليف التشغيل بتلك المنطقة وتعتبر المنطقة الحرة فيما يتعلق بحساب النولون بلد المنشأ بالنسبة للمنتجات المصنعة فيها.
*الفقرتان الثانية والثالثة معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'c3da9829ff7d9a2530523277a9ca3247'),
(41,0,$m229$المادة 41$m229$,$m229$لا تخضع المشروعات داخل المناطق الحرة والأرباح التى توزعها لإحكام قوانين الضرائب والرسوم السارية فى مصر.
ومع ذلك تخضع هذه المشروعات للمعاملة الآتية:
أولا - تخضع المشروعات فى المناطق الحرة العامة:
1 - لرسم مقداره اثنان بالمائة (2%) من قيمة السلع عند الدخول (سيف) بالنسبة لمشروعات التخزين ولرسم مقداره واحد بالمائة (1%) من قمية السلع عند الخروج (فوب) بالنسبة لمشروعات التصنيع والتجميع، وتعفى من الرسم تجارة البضائع العابرة (ترانزيت) المحددة الوجهة.
2 - لرسم مقداره واحد بالمائة (1%) من إجمالى الإيرادات التى تحققها بالنسبة للمشروعات التى لا تقتضى نشاطها الرئيسى إدخال سلع أو إخراجها وذلك من واقع القوائم المالية المعتمدة من أحد المحاسبين القانونيين.
ثانيا - تخضع المشروعات فى المناطق الحرة الخاصة:
1 - لرسم مقداره واحد بالمائة (1%) من إجمالى الإيرادات التى تحققها بالنسبة لمشروعات التصنيع و التجميع عند تصدير السلع الى خارج البلاد، واثنان بالمائة (2%) من إجمالى ايرادات هذه المشروعات عند دخولها البلاد، وتعفى من الرسوم تجارة البضائع العابرة (ترانزيت) المحددة الوجهة.
2 - لرسم مقداره اثنان بالمائة %2 من إجمالى الإيرادات التى تحققها وذلك فيما بتعلق بغير ذلك من المشروعات الواردة بالبند السابق.
3 - وتئول حصيلة الرسوم الواردة بالبند أولا من هذه المادة الى الهيئة وتوزع حصيلة الرسوم الواردة بالبند (ثانيا) من هذه المادة مناصفة بين وزارة المالية والهيئة.
وفى جميع الأحوال تلتزم المشرعات المقامة فى المناطق الحرة العامة والخاصة بأداء مقابل سنوىا للخدمات للهيئة لا يجاوز مقداره (واحدا في الألف) (%.001) من رأس المال بحد أقصى مائة الف جنيه وفقا للنسب التى تبينها اللائحة التنفيذية لهذا القانون ويجوز أداء ما يعادل قيمتها بالعملة التى يحددها الوزير المختص.
كما تلتزم هذه المشروعات بتقديم القوائم المالية معتمدة من أحد المحاسبين القانونيين إلى كل من وزارتى المالية والاستثمار.$m229$,'7cafa7a303e530664a52361f25440e02'),
(42,0,$m229$المادة 42$m229$,$m229$تعفى مشروعات النقل البحرى التى تنشأ فى المناطق الحرة من الشروط الخاصة بجنسية مالك السفينة والعاملين عليها المنصوص عليها فى القانون رقم 84 لسنة 1949، بشأن تسجيل السفن التجارية، وقانون التجارة البحرية الصادرة بالقانون رقم 8 لسنة 1990.
كما تستثنى السفن المملوكة لهذه المشروعات من أحكام القانون رقم 12 لسنة 1964 بإنشاء المؤسسة المصرية العامة للنقل البحرى.$m229$,'78c846356cc1e6c9d711202cc971a966'),
(43,0,$m229$المادة 43$m229$,$m229$يلتزم المستثمر بالتأمين الشامل على المبانى والآلات والمعدات ضد جميع الحوادث، والمخاطر التى تنشأ من مزاولة النشاط المرخص به.
ولمجلس إدارة المنطقة إصدار قرار بإزالة منشآت المشروع فى حالة وقوع الحادث أو الخطر المؤمن ضده، ويجب أن يكون القرار مسببا ويعلن به المستثمر أو من يمثله خلال أسبوع من تاريخ صدوره بموجب خطاب مسجل مصحوبا بعلم الوصول ويجوز لإدارة المنطقة تقصير هذا الميعاد للضرورة.
وعلى المستثمر تنفيذ قرار الإزالة على نفقته وخلال الموعد الذى تحدده إدارة المنطقة ويكون لمجلس إدارة المنطقة فى حالة امتناع المستثمر عن التنفيذ وقف نشاط المشروع أو إلغاؤه، بحسب جسامة المخالفة.$m229$,'9ff88a8a552fb90a474642315af00ae3'),
(44,0,$m229$المادة 44$m229$,$m229$فى جميع الأحوال التى ترد فيها الرسائل من الخارج و يفرج عنها من الجمارك برسم المناطق الحرة، يتم معاينتها بواسطة لجنة ثلاثية من المنطقة و الجمرك المختص وصاحب الشأن أو من ينيبه داخل مقر المشروع، ويحرر بيان بتوقيعهم موضحا به نتيجة المعاينة بعد المطابقة على الفواتير أو بيان العبوة، وتسلم الرسالة إلى صاحب الشأن وتصبح فى عهدته وتحت مسئوليته الكاملة، وتلتزم مصلحة الجمارك بتقدير قيمة هذه الرسالة وإبلاغ إدارة المنطقة بها.
وعلى مدير جمرك المنطقة إخطار رئيس المنطقة بحالات النقص أو الزيادة غير المبررة عما أدرج قائمة الشحن سواء فى عدد الطرود أو محتوياتها أو البضائع المحفوظة أو المنفرطة (الصب).
ويصدر بتنظيم المسئولية عن الحالات المنصوص عليها فى الفقرة السابقة وينسب التسامح فيها، قرار من مجلس إدارة الهيئة.$m229$,'cd0400525f3bbca74b83ac9df17fd8cb'),
(45,0,$m229$المادة 45$m229$,$m229$لا تخضع المشروعات فى المناطق الحرة لأحكام القانون رقم 113 لسنة 1958 بشأن التعيين فى وظائف شركات المساهمة والمؤسسات العامة.
وتطبق احكام قانون العمل على علاقات العمل والسلامة والصحة المهنية بهذه المناطق، وتعد هذه الأحكام فيما تضمنته من حقوق للعمال حدا أدنى لما يجوز الاتفاق عليه فى عقود العمل الفردية أو الجماعية، التى تبرم مع العاملين فى المشروعات المرخص لها بالعمل فى هذه المناطق.
وتضع المشروعات فى المناطق الحرة لائحة داخلية بنظام العمل بها تكون ملزمة لها، وتقدمها للرئيس التنفيذى للهيئة أو من يفوضه للتصديق عليها، وتكون هذه اللائحة مكملة لعقود العمل الفردية أو الجماعية.
وللرئيس التنفيذى للهيئة الاعتراض على ما تضمنته اللائحة الداخلية من أحكام تخالف النظام العام أو إذا تضمنت مزايا أقل من المقررة فى قانون العمل.
وتسرى أحكام قانون التأمين الاجتماعى الصادر بالقانون رقم 79 لسنة 1975 على العاملين بالمشروعات التى تمارس نشاطها فى المناطق الحرة، وكذا قانون التأمين على أصحاب الأعمال ومن فى حكمهم الصادر بالقانون رقم 108 لسنة 1976.$m229$,'bd2f181074c5b9b32e5540c1018adbcf'),
(46,0,$m229$المادة 46$m229$,$m229$لا يجوز لأى شخص أن يزاول مهنة أو حرفة فى المنطقة الحرة العامة لحسابه بصفة دائمة إلا بعد الحصول على تصريح بذلك من رئيس مجلس إدارة المنطقة طبقا للشروط والأوضاع التى تبينها اللائحة التنفيذية لهذا القانون وبعد سداد رسم سنوى لا يجاوز خمسة آلاف جنيه.
ويعاقب بغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرين ألف جنيه كل من يخالف حكم الفقرة الأولى من هذه المادة، ولا ترفع الدعوى الجنائية فى هذه الحالة إلا بإذن الوزير المختص، وفى جميع الأحوال تحظر إقامة المشروعات تزاول المهن الحرة والاستشارات فى المناطق الحرة، ويكون دخول المناطق الحرة وفقا للشروط التى يصدر بها قرار من مجلس إدارة الهيئة.$m229$,'4e2e9204376fec43b120af6bee47e063'),
(47,0,$m229$المادة 47$m229$,$m229$تسرى على الاستثمار بنظام المناطق الحرة الأهداف، والمبادئ والضمانات، والمادة (11) من هذا القانون فيما لا يتعارض مع طبيعة العمل بهذا النظام.
ويجوز للمشروعات العاملة بهذا النظام التحول للعمل بنظام الاستثمار الداخلى، وتحدد اللائحة التنفيذية لهذا القانون شروط التحول وضوابطه والمعاملة الجمركية للمعدات والآلات وأجهزة الأنتاج وخطوطه وقطاع الغيار التى يقتضيها النشاط المرخص لها به.$m229$,'07ba6a94ceeaa8888a7ce7489dd01e51'),
(48,0,$m229$المادة 48$m229$,$m229$مع مراعاة حكم المادة (71) من هذا القانون، تلتزم الهيئة بتقديم خدمات التأسيس وما بعد التأسيس ومركز خدمات المستثمرين للشركات الخاضعة لأحكام هذا القانون، وقانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981، وميكنتها وتوحيد إجراءاتها، وتسرى إجراءات التأسيس الإلكترونى دون غيرها فور تفعيلها بالهيئة، ولا تتقيد الهيئة فى ذلك بأى إجراءات منصوص عليها فى القوانين الأخرى.
وتحدد اللائحة التنفيذية لهذا القانون الأحكام المنظمة لنشر النظام الأساسى للشركة وإجراءات تعديله وضوابط العمل بنظام التأسيس الإلكترونى، والخدمات للشركات والمنشآت الخاضعة لأحكام هذا القانون، وقانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة المشار إليه.
وفى جميع الأحوال، يتعين التصديق على توقيعات الشركاء أو من ينوب عنهم، على عقود الشركات أيا كان نظام الاستثمار الخاضعة له مقابل رسم تصديق مقداره ربع فى المائة من قيمة رأس المال المدفوع بحد أقصى مقداره عشرة آلاف جنيه أو ما يعادله من النقد الأجنبى، بحسب الأحوال، سواء تم التصديق فى مصر أو لدى السلطات المصرية فى الخارج، وتسرى هذه الأحكام على كل تعديل فى نظام الشركة.
*الفقرة الأخيرة مضافة بموجب قانون رقم 141 لسنة 2019.$m229$,'e9ef9cb57cdfa21a40784b8b5bab6f3c'),
(49,0,$m229$المادة 49$m229$,$m229$يصدر بقرار من الوزير المختص نموذج عقد لكل نوع من أنواع الشركات ونظامها الأساسى بحسب الأحوال.
ويسدد طالب التأسيس، دفعة واحدة، للهيئة جميع ما تفرضه التشريعات من الرسوم المقررة وغيرها من المبالغ للجهات التى تقدم الخدمات المتصلة بالتأسيس، وما بعد التأسيس، وتحصل الهيئة هذه الرسوم لحساب تلك الجهات.
وتستحق الهيئة مقابلا لما تؤديه للمستثمرين من خدمات فعلية، ويصدر مجلس إدارة الهيئة قرارا بتحديد فئات هذا المقابل والقواعد والشروط والإجراءات المنظمة لتحصيله.$m229$,'99a7a1b73889699100014c285c5a91e9'),
(50,0,$m229$المادة 50$m229$,$m229$تلتزم الجهات المختصة بتوفيق أوضاعها لتفعيل نظام الخدمات الإلكترونية لدى الهيئة، وذلك بموافاتها بجميع المستندات والنماذج والبيانات و ربط أنظمة العمل وقواعد البيانات لدى تلك الجهات بنظام الخدمات الإلكترونية بالهيئة وقاعدة بياناتها، وذلك خلال تسعين يوما من تاريخ العمل بأحكام هذا القانون.
كما تلتزم الجهات المختصة بالاعتداد بالتوقيعات الإلكترونية والمستندات والنماذج المعدة بإحدى الوسائل التكنولوجية، وقبول السداد الإلكترونى لجميع مدفوعاتها، وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.$m229$,'903218ad11263402b9ddcde5c98035d9'),
(51,0,$m229$المادة 51$m229$,$m229$تلتزم الهيئة بالبت فى طلب التأسيس خلال يوم عمل كامل على الأكثر بعد تقديمه مستوفيا، وتكتسب الشركة الشخصية الاعتبارية بمجرد قيدها فى السجل التجارى، ويصدر لها شهادة بالتأسيس، يحدد بياناتها قرار من الرئيس التنفيذى.
وعلى جميع الجهات المختصة والبنوك والجهات ذات الصلة كافة الاعتداد بهذه الشهادة كمستند رسمى فى تعاملاتها فور إصدارها.
وتلتزم الشركات التى يتم تأسيسها وفقا لأحكام هذا القانون بتقديم شهادة تفيد إيداع الأوراق المالية للشركة لدى شركة إيداع مركزى.
وتقوم الهيئة بوضع نظام يتيح إصدار شهادة للمشروع الاستثمارى، يصدر بتنظيمها قرار من الرئيس التنفيذى للهيئة.
كما يكون لكل منشأة أو شركة، أيا كان شكلها القانونى، رقم قومى موحد معتمد لجميع معاملات المستثمر مع أجهزة وجهات الدولة المختلفة كافة فور تفعيله.
وذلك كله وفقا لما تبنيه اللائحة التنفيذية لهذا القانون.$m229$,'d0054f1f69bfc95f46ff960aeff1ba9d'),
(52,0,$m229$المادة 52$m229$,$m229$يجوز تحديد رأسمال الشركات الخاضعة لأحكام هذا القانون بأى عملة قابلة للتحويل وإعداد قوائمها المالية ونشرها بهذه العملة بشرط أن يكون الاكتتاب فى رأسمالها بذات العملة، وبالنسبة لشركات الأموال يتم سداد النسبة المحددة من رأس المال المدفوع وفقا لأحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشراكات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981.
كما يجوز تحويل مسمى رأسمال الشركات الخاضعة لأحكام هذا القانون من الجنيه المصرى إلى أى عملة قابلة للتحويل، وفقا لسعر الصرف المعلن من البنك المركزى فى تاريخ التحويل. وتحدد اللائحة التنفيذية لهذا القانون الضوابط المنظمة فى هذا الشأن.$m229$,'60c442370bf8c7f4b15299b479e4291a'),
(53,0,$m229$المادة 53$m229$,$m229$استثناء من أحكام المادة (45) من قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981، يجوز تداول حصص التأسيس والأسهم لشركات الأموال الخاضعة لأحكام هذا القانون، خلال السنتين الماليتين الأوليين للشركة بموافقة الوزير المختص.$m229$,'8c2d7a3161682fa63271fa48ad373281'),
(54,0,$m229$المادة 54$m229$,$m229$تلتزم الهيئة بإصدار القرارات التى تيسر على المستثمرين وتحقق سرعة تقديم الخدمات لهم فى كل ما تختص به من إجراءات، ويكون لها فى سبيل تحقيق ذلك، ودون التقيد بأى إجراءات منصوص عليها فى القوانين الأخرى، وضع الضوابط التى تكفل فصل تنظيم إجراءات الاستثمار عن الرقابة اللاحقة على الشركات، بما لا يخل بمبادئ الشفافية والحوكمة والإدارة الرشيدة والمسئولية، وذلك من خلال الآتى:
1 - تيسير جميع الإجراءات المتعلقة بالجمعيات العامة ومجالس إدارات الشركات والتصديق على محاضرها، بما فى ذلك استخدام سبل التكنولوجيا الحديثة، بما لا يجاوز خمسة عشر يوما من تاريخ تقديمها مستوفاة.
2 - الاستعاضة عن الدفاتر والمستندات بوسائل إلكترونية تتماشى مع التطور التكنولوجى.
3 - تطوير وتوحيد وتبسيط إجراءات زيادة أو تخفيض رأس المال ونظم التقييم المالى، وإجراءات التحقق مما إذا كانت القيم المحددة لها قد قدرت تقديرا صحيحا، وذلك دون الإخلال بالاختصاص المقرر قانونا للهيئة العامة للرقابة المالية.
وذلك كله وفقا لما تحدده اللائحة التنفيذية لهذا القانون.$m229$,'1f8e4acbb3dd295a8cec4a59bb598cfd'),
(55,0,$m229$المادة 55$m229$,$m229$للمستثمر الحق فى الحصول على العقارات اللازمة لمباشرة نشاطه أو التوسع فيه، أيا كانت نسبة مشاركته أو مساهمته فى رأس المال، وذلك مع مراعاة القواعد الخاصة ببعض العقارات الواقعة فى المناطق الجغرافية التى تنظمها قوانين خاصة، وذلك إما من خلال الجهة صاحبة الولاية على العقارات وفقا للقواعد المنصوص عليها فى قوانينها و لوائحها بعد الإعلان عنها، أو من خلال الهيئة وفقا لأحكام التصرف المنصوص عليها فى هذا القانون.$m229$,'11961290829bffabb97f0af5a304a0ce'),
(56,0,$m229$المادة 56$m229$,$m229$تلتزم الجهات الإدارية صاحبة الولاية بعد التنسيق مع جميع الجهات المختصة والمركز الوطنى لتخطيط استخدامات أراضى الدولة من خلال تسعين يوما من تاريخ العمل بهذا القانون، بموافاة الهيئة بخرائط تفصيلية محددا عليها جميع العقارات الخاضعة لولايتها والمتاحة للاستثمار، بالإضافة إلى قاعدة بيانات كاملة تتضمن الموقع والمساحة والارتفاعات المقررة والسعر التقديرى والأنشطة الاستثمارية الملائمة لطبيعتها وأسلوب التصرف فيها، كما تلتزم هذه الجهات بتحديث تلك البيانات دوريا كل ستة أشهر أو كلما طلبت الهيئة ذلك.
ويصدر رئيس الجمهورية بعد موافقة مجلس الوزراء قرارا بنقل الملكية أو الولاية أو الإشراف على بعض العقارات، من الجهات الإدارية صاحبة الولاية إلى الهيئة متى استلزم تنفيذ الخطة الاستثمارية ذلك، على أن تتولى الهيئة التصرف فيها وفقا لأحكام هذا القانون.$m229$,'690703c811962f950e82f1d7a4c0f7cc'),
(57,0,$m229$المادة 57$m229$,$m229$يكون التصرف للمستثمرين فى العقارات المملوكة ملكية خاصة للدولة أو غيرها من الأشخاص الاعتبارية العامة بغرض الاستثمار طبقا للأحكام والضوابط والإجراءات المنصوص عليها فى هذا القانون بمراعاة الخطة الاستثمارية للدولة، وحجم المشروع الاستثمارى وطبيعة نشاطه، وقيمة الأموال المستثمرة فيه.
ولا تسرى على هذا التصرف أحكام قانون تنظيم المناقصات والمزايدات الصادر بالقانون رقم 89 لسنة 1998، إلا فيما لم يرد فى شأنه نص خاص فى هذا القانون وبما لا يتعارض مع أحكامه.
وعلى المستثمر الالتزام بالجدول الزمنى المقدم منه لتنفيذ المشروع الاستثمارى المعتمد من الجهة المختصة، ما دامت تلك الجهة قد أوفت بالتزاماتها تجاه المستثمر.
ولا يجوز للمستثمر ادخال تعديلات على المشروع الاستثمارى بتعديل غرضه أو توسعته أو زيادة حجمه أو غير ذلك من تعديلات إلا بعد موافقة الجهة المختصة كتابة على ذلك سواء كان ذلك مباشرة أو من خلال ممثلها بمركز خدمات المستثمرين.$m229$,'1fefd1b9fe5855fcef23a2d36a6b7e30'),
(58,0,$m229$المادة 58$m229$,$m229$مع مراعاة حكم المادة (37) من هذا القانون، يجوز التصرف فى العقارات اللازمة للمشروعات الاستثمارية وفقا لأحكام هذا القانون بإحدى الصور الآتية: البيع، الإيجار، الإيجار المنتهى بالتملك، الترخيص بالأنتفاع.
ويكون ذلك إما على طلب المستثمر، أو دعوة أو إعلان من الهيئة وفقا لأحكام هذا القانون.
ويجوز للجهات الإدارية صاحبة الولاية على العقارات أن تشترك فى المشروعات الاستثمارية بتلك العقارات كحصة عينية أو بالمشاركة فى الأحوال التى يصدر بها قرار من مجلس الوزراء، وتبين اللائحة التنفيذية لهذا القانون أوضاع و إجراءات وكيفية اشتراك تلك الجهات بالعقارات فى المشروع الاستثمارى.$m229$,'f58529ec4ed4ae717d248d567b7f2045'),
(59,0,$m229$المادة 59$m229$,$m229$فى الأحوال التى يطلب فى المستثمر توفير عقارات من أملاك الدولة الخاصة لإقامة مشروع استثمارى، يتعين أن يبين فى طلبه الغرض والمساحة والمكان الذى يرغب في إقامة المشروع عليه. وتتولى الهيئة عرض العقارات المتوفرة لديها أو لدى الجهات الإدارية صاحبة الولاية التى تلائم النشاط الاستثمارى لطالب الاستثمار وبيان طبيعة العقار، والاشتراطات المتعلقة بها، وبيان ما إذا كانت مزودة بالمرافق وصور التصرف فيها، ومقابل ذلك، وغيرها من الاشتراطات والبيانات اللازمة.$m229$,'78f4539705090ecec7207c5710e14ae6'),
(60,0,$m229$المادة 60$m229$,$m229$يجوز لأغراض التنمية دون غيرها وطبقا للخريطة الاستثمارية، فى المناطق التى يصدر بتحديدها رئيس الجمهورية بعد موافقة مجلس الوزراء، التصرف دون مقابل فى العقارات المملوكة للدولة ملكية خاصة للمستثمرين الذين تتوافر فيهم الشروط الفنية والمالية التى يتم تحديدها بقرار من مجلس الوزراء، ويسرى ذلك على صور التصرف المنصوص عليها فى المادة (58) من هذا القانون.
وفى جميع أحوال التصرف فى العقارات دون مقابل، يجب على المستثمر تقديم ضمان نقدى أو ما يقوم مقامه إلى جهة التصرف بما لا يزيد على خمسة بالمئة (5%) من قيمة التكاليف الاستثمارية للمشروع، وذلك وفقا للمعايير والضوابط التى تبينها اللائحة التنفيذية لهذا القانون، على أن يسترد ذلك الضمان بعد مرور ثلاث سنوات على بدء الأنتاج الفعلى للمشروعات ذات الطبيعة الأنتاجية، أو بدء مزاولة النشاط لغير ذلك من المشروعات، شريطة التزام المستثمر بشروط التصرف.$m229$,'a027bc2f584f61f82f3a2981abb8c7a6'),
(61,0,$m229$المادة 61$m229$,$m229$فى الحالات التى يكون فيها التصرف فى العقارات بنظام الترخيص بالأنتفاع بمقابل، يكون الترخيص مدة لا تزيد على 50 عاما قابلة للتجديد، بالشروط المتفق عليها مادام المشروع مستمرا فى نشاطه، ودون أن يخل ذلك بحق الجهة صاحبة الولاية فى تعديل قيمة مقابل الأنتفاع عند التجديد.
ويكون الترخيص للمستثمرين الذين تتوفر فيهم الشروط الفنية والمالية التى تحددها الهيئة بالتنسيق مع الجهة الإدارية صاحبة الولاية.
وتسرى ذات الأحكام السابقة على أحوال التصرف بالتأجير.$m229$,'69488753b9b42bb1cce9807e902b6e47'),
(62,0,$m229$المادة 62$m229$,$m229$فى الحالات التى يكون التصرف فى العقارات بالبيع، يجوز لكل مستثمر لأغراض إقامة المشروعات الاستثمارية أو توسيعها أن يقدم طلبا بالتعاقد عليها، بشرط أن تتوفر فيه الشروط الفنية والمالية التى تحددها الهيئة بالتنسيق مع الجهة الإدارية صاحبة الولاية.
ولا تنتقل ملكية العقارات إلى المستثمر فى هذه الحالات إلا بعد سداد كامل الثمن وبدء الأنتاج الفعلى للمشروعات ذات الطبيعة الأنتاجية أو الأنتهاء من تنفيذ المشروعات العقارية أو السياحية، أو بدء مزاولة النشاط لغير ذلك، ويجب أن يتضمن العقد المبرم مع المستثمر نصا بذلك.
ويجوز للهيئة بناء على طلب المستثمر بعد موافقة الجهة الإدارية صاحبة الولاية، الاتفاق على تأجيل سداد كامل الثمن أو بعضه أو غير ذلك من التيسيرات إلى ما بعد التشغيل الفعلى للمشروع، ويحدد العقد ما يلزم لذلك من ضمانات وإجراءات.
وتسرى ذات الأحكام السابقة على نظام الإيجار المنتهى بالتملك.$m229$,'c38841b7d2d7fcd37c8cfd4a8cc13244'),
(63,0,$m229$المادة 63$m229$,$m229$عند تزاحم طلبات المستثمرين فى التعامل على العقارات اللازمة لإقامة مشروعات استثمارية سواء بنظام البيع أو التأجير أو التأجير المنتهى بالتملك أو الترخيص بالأنتفاع، تكون المفاضلة بين من استوفى منهم الشروط الفنية والمالية اللازمة للاستثمار بنظام النقاط وفقا لأسس مفاضلة من بينها قيمة العرض المقدم من المستثمر أو المواصفات الفنية أو المالية الأخرى.
وإذا تعذرت المفاضلة بين المتزاحمين بنظام النقاط جاز إجراؤها وفقا لأعلى سعر يقدم منهم.
وتبين اللائحة التنفيذية لهذا القانون أحوال التزاحم، وضوابط إجراء تلك المفاضلة والأسس التى تتم بناء عليها.$m229$,'092d24204ec8b291898a548d038bc2f8'),
(64,0,$m229$المادة 64$m229$,$m229$فى تطبيق أحكام هذا الفصل، يكون تقدير ثمن البيع أو القيمة الإيجارية أو مقابل الأنتفاع عن طريق إحدى الجهات الآتية: الهيئة العامة للخدمات الحكومية، اللجنة العليا لتثمين أراضى الدولة بوزارة الزراعة، هيئة المجتمعات العمرانية الجديدة، الهيئة العامة للتنمية الصناعية، وذلك وفقا لطبيعة النشاط المستهدف إقامته.
وتلتزم جهة التقدير بضم ممثلين من ذوى الخبرة فى عضوية لجان التقدير، وأنهاء عملية التقدير خلال مدة لا تجاوز ثلاثين يوما من تاريخ تقديم طلب التقدير إليها.
وتبين اللائحة التنفيذية لهذا القانون المعايير والضوابط والإجراءات اللازمة لمباشرة عملية التقدير، ومدة صلاحيته، والأتعاب التى يتم سدادها لجهة التسعير من الجهة صاحبة الولاية عند إتمام التخصيص.$m229$,'17c7afb0b6156cf035094ede773e89f3'),
(65,0,$m229$المادة 65$m229$,$m229$تشكل بقرار من الرئيس التنفيذى للهيئة وباعتماد من الوزير المختص لجنة أو أكثر تضم عناصر فنية ومالية وقانونية تتناسب وظائفهم وخبراتهم مع أهمية وطبيعة موضوع التعاقد، للبت فى طلبات التصرف فى العقارات للمستثمرين فى الأحوال المختلفة وفقا لأحكام هذا الفصل خلال مدة لا تجاوز ثلاثين يوما من تاريخ ورود الرأى الفنى فى طلب المستثمر من جهة الولاية والذى يجب أن تقدمه جهة الولاية خلال أسبوع من تاريخ ورود الطلب وتعتمد قراراتها منه، وتخطر الهيئة مقدم الطلب بهذا القرار.
وتبين اللائحة التنفيذية لهذا القانون إجراءات عمل اللجان المشار إليها، وكيفية الإخطار وطرق سداد الثمن أو القيمة الإيجارية أو مقابل الأنتفاع بحسب الاحوال، وأيلولة المستحقات إلى الجهات المختصة كاملة، كما تبين اللائحة التنفيذية إجراءات إعداد وتحرير العقود فى كل حالة وفق نماذج العقود المعتمدة من مجالس إدارة الهيئة بعد مراجعتها من مجلس الدولة.$m229$,'575ee7db1a0b2a2434edddc016d127b5'),
(66,0,$m229$المادة 66$m229$,$m229$فى جميع الأحوال التى يتم فيها التصرف فى العقارات المملوكة ملكية خاصة للدولة أو للأشخاص الاعتبارية العامة، يتعين على المشروع الاستثمارى الالتزام بالغرض الذى تم التصرف فى العقار على أساسه ولا يجوز تغيير هذا الغرض إلا بعد الموافقة الكتابية من الجهة الإدارية صاحبة الولاية فى الأحوال التى تسمح فيها طبيعة العقار وموقعه بهذا التغيير وبشرط سداد المبالغ التى تبين اللائحة التنفيذية معايير تحديد قيمتها.
وتلتزم هذه الجهة بالرد على طلب تغيير الغرض خلال ثلاثين يوما من تاريخ تقديمه وإلا اعتبر عدم الرد رفضا للطلب.
ويحق للمستثمر التظلم من هذا القرار أما اللجنة المنصوص عليها بالمادة (83) من هذا القانون.
وفى جميع الأحوال، لا يقبل طلب تغيير الغرض قبل إنقضاء عام من تاريخ بدء الأنتاج أو مزاولة النشاط.$m229$,'8a8188a2a10746bb6b2614e5578ac47e'),
(67,0,$m229$المادة 67$m229$,$m229$يكون للجهة الإدارية صاحبة الولاية بناء على ما يقدم إليها من تقارير المتابعة التى يعدها موظفو الجهات الإدارية صاحبة الولاية بشأن متابعة مراحل تنفيذ البرنامج الزمنى لإقامة منشآت المشروع الاستثمارى، وبعد موافقة مجلس إدارة الهيئة، فسخ عقد البيع أو الإيجار أو الإيجار المنتهى بالمتلك أو الترخيص بالأنتفاع وسحب العقارات فى أحد الأحوال الآتية:
1 - الامتناع عن استلام العقار مدة تسعين يوما من تاريخ إخطاره بالاستلام.
2 - عدم البدء فى تنفيذ المشروع خلال تسعين يوما من تاريخ استلامه العقار خاليا من الموانع والعوائق بغير عذر مقبول واستمرار تقاعسه بعد أنذاره كتابة مدة مماثلة.
3 - مخالفة شروط سداد المستحقات المالية ومواعيده.
4 - تغيير غرض استخدام العقار الذى خصص له أو القيام برهنه أو ترتيب أى حق عينى عليه بغير الموافقة الكتابية المسبقة من الجهة الإدراية صاحبة الولاية أو قبل أنتقال المكلية إليه وفقا لأحكام هذا القانون.
5 - مخالفة شروط العقد أو الترخيص بالأنتفاع مخالفة جوهرية، فى أى مرحلة من مراحل المشروع، وعدم إزالة أسباب المخالفة بعد أنذار المستثمر كتابة بذلك.
وتبين اللائحة التنفيذية المخالفات الجوهرية المشار إليها وإجراءات استرداد العقارات فى حالة ثبوت امتناع المستثمر أو تقاعسه عن إتمام تنفيذ المشروع ويجوز فى هذه الحالة إعادة التصرف فى العقار.$m229$,'31319ac91ccd2745923b59cdec38ffa6'),
(68,0,$m229$المادة 68$m229$,$m229$ينشأ مجلس أعلى للاستثمار برئاسة رئيس الجمهورية يختص فضلا عما هو مقرر له فى هذا القانون بالأتى:
1 - اتخاذ كل مايلزم لتهيئة مناخ أفضل للاستثمار والتوجيه بما يتطلبه ذلك.
2 - وضع الإطار العام للإصلاح التشريعى والإدارى لبيئة الاستثمار.
3 - إقرار السياسات والخطة الاستثمارية التى تحدد أولويات مشروعات الاستثمار المستهدفة، بما يتفق مع السياسة العامة للدولة وخطة التنمية الاقتصادية والاجتماعية ونظم الاستثمار المطبقة.
4 - متابعة تنفيذ أجهزة الدولة للخطط والبرامج المتعلقة بالاستثمار وتطور العمل بالمشروعات الاقتصادية الكبرى وموقف مشروعات المشاركة مع القطاع الخاص.
5 - متابعة تحديث الخريطة الاستثمارية وتنفيذها على مستوى القطاعات المتخصصة والمناطق الجغرافية المختلفة فى إطار خطة التنمية الاقتصادية للدولة.
6 - استعراض الفرص الاستثمارية المتاحة فى كل قطاع وبحث محاور المشاكل المتعلق بها.
7 - متابعة تطور تصنيف مصر وترتيبها فى التقارير والمؤشرات الدولية الخاصة بالاستثمار.
8 - متابعة آليات تسوية منازعات الاستثمار وموقف قضايا التحكيم الدولة.
9 - دراسة ووضع حلول لمعوقات الاستثمار وإزالة عقبات تنفيذ أحكام هذا القانون.
10 - تفعيل المسئولية التضامنية لجميع الوزارات والهيئات العامة والأجهزة الحكومية المختصة بالاستثمار وتحقيق التناغم فى ادائها.
11 - حل الخلافات والتشابكات التى قد تثور بين اجهزة الدولة فى مجال الاستثمار.
ويصدر بتشكيل هذا المجلس وبنظام العمل به قرار من رئيس الجمهورية.
وتلتزم جميع أجهزة الدولة بتنفيذ القرارات الصادرة عن المجلس.$m229$,'653f32a0267d323be3f215e8eca6dc5c'),
(69,0,$m229$المادة 69$m229$,$m229$الهيئة العامة للاستثمار والمناطق الحرة، هيئة عامة اقتصادية، لها شخصية اعتبارية عامة تتبع الوزير المختص، وتقوم على تنظيم الاستثمار فى البلاد وتشجيعه، وتنمية وإدارة شئونه والترويج له، على النحو الذى يحقق خطة التنمية الاقتصادية للدولة.
ويكون مقر الهيئة الرئيس محافظة القاهرة، ويجوز لها أنشاء فروع أو مكاتب لها داخل جمهورية مصر العربية أو خارجها بقرار من مجلس الإدارة ضمن بعثات التمثيل التجارى.$m229$,'903b4ec85e0b77bfe4f36d48edea8991'),
(70,0,$m229$المادة 70$m229$,$m229$مع عدم الإخلال بأحكام قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 والقانون رقم 95 لسنة 1995 فى شأن التأجير التمويلى وقانون التمويل العقارى الصادر بالقانون رقم 148 لسنة 2001، وقانون البنك المركزى والجهاز المصرفى والنقد الصادر بالقانون رقم 88 لسنة 2003، والقانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية، تكون الهيئة هى الجهة الإدارية المختصة دون غيرها بتطبيق أحكام هذا القانون وقانون شركات المساهمات وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981.
ولاتتقيد الهيئة فى المسائل المالية والإدارية بالنظم والقواعد الحكومية، وللهيئة فى سبيل أنجاز مهامها الاستعانة بأفضل الكفاءات والخبرات المحلية والعالمية، وذلك دون الإخلال بأحكام القانون رقم 63 لسنة 2014 بشأن الحد الأقصى لدخول العاملين بأجر لدى أجهزة الدولة ويصدر بتنظيم هذه المسائل قرار من مجلس إدارة الهيئة.
ويكون للهيئة فى سبيل تحقيق أغراضها التعاقد وإرجاء التصرفات والأعمال ويجوز تخصيص عقارات من أملاك الدولة الخاصة أو إعادة تخصيصها للهيئة بغرض استخدامها فى شئونها الإدارية.$m229$,'e1d3a74f81d072021779f9fe2026c994'),
(71,0,$m229$المادة 71$m229$,$m229$للهيئة فى سبيل تحقيق أغراضها فضلا عما هو منصوص عليه فى هذا القانون مباشرة الاختصاصات الأتية:
1 - إعداد مشروع الخطة الاستثمارية بالتنسيق والتعاون مع جميع أجهزة الدولة المختصة تتضمن نوعية الاستثمار ونظامه ومناطقه الجغرافية وقطاعاته والعقارات المملوكة للدولة أو للأشخاص الاعتبارية العامة الأخرى المعدة للاستثمار، ونظام التصرف فيها وطريقته بحسب نوع النظام الاستثمارى.
2 - وضع الخطط والدراسات والنظم الكفيلة بجذب وتشجيع رءوس الأموال الوطنية والأجنبية للاستثمار فى مختلف المجالات وفق الخطة الاستثمارية للدولة، واتخاذ الإجراءات اللازمة لذلك.
3 - إعداد قاعدة بيانات وخريطة للفرص الاستثمارية المتاحة والمشروعات والأنشطة الاستثمارية المستهدفة، ومتابعة تحديثها، وتوفير هذه المعلومات والبيانات للمستثمرين.
4 - إصدار الشهادة اللازمة لتمتع المستثمر بالحوافز والضمانات المنصوص عليها فى هذا القانون.
5 - وضع خطة للترويج للاستثمار واتخاذ جميع الإجراءات اللازمة لذلك بجميع الوسائل ونشرها فى الداخل والخارج.
6 - توحيد جميع النماذج الرسمية الخاصة بشئون الاستثمار التنسيق مع الجهات المختصة وتوفيرها للاستخدام من خلال الشبكة الدولية للمعلومات وغيرها من الوسائل.
7 - وضع نظام لإدارة المناطق الحرة والاستثمارية بما يخدم الاقتصاد القومى.
8 - دراسة التشريعات المتعلقة بالاستثمار واقتراح ما يلزم فى شأنها ومراجعتها بشكل دورى.
9 - إقامة المؤتمرات والندوات وورش التدريب والعمل والمعارض المتصلة بشئون الاستثمار وتنظيمها داخليا وخارجيا.
10 - التعاون مع المؤسسات والمنظمات الدولية والأجنبية العاملة فى مجال الاستثمار والترويج له.
11 - إجراء الرقابة والتفتيش على الشركات الخاضعة لأحكام هذا القانون وذلك وفقا للقواعد والإجراءات التى تبينها اللائحة التنفيذية لهذا القانون والقوانين الأخرى.$m229$,'859e7020700e61a3b48d750c4017d927'),
(72,0,$m229$المادة 72$m229$,$m229$يجوز للهيئة لأغراض تنفيذ خطتها فى مجال الترويج لفرص الاستثمار المتاحة داخليا وخارجيا، أن تعهد بهذه المهمة إلى شركات متخصصة يتم التعاقد معها لهذا الغرض، دون التقيد بأحكام قانون تنظيم المناقصات والمزايدات الصادر بالقانون رقم 89 لسنة 1998، وذلك وفقا للقواعد التى تبينها اللائحة التنفيذية لهذا القانون.$m229$,'7b7e2cbb82dc868e0eb9b98feca78c7b'),
(73,0,$m229$المادة 73$m229$,$m229$يكون للهيئة مجلس إدارة، يتولى وضع السياسة العامة لها والإشراف على تنفيذها، يشكل بقرار من رئيس مجلس الوزراء، على النحو الأتى:
1 - الوزير المختص رئيسا.
2 - الرئيس التنفيذى للهيئة.
3 - نواب الرئيس التنفيذى للهيئة.
4 - ثلاثة من ممثلى الجهات والأجهزة ذات الصلة.
5 - إثنان من ذوى الخبرة أحدهما فى مجال الاستثمار بالقطاع الخاص والثانى فى مجال القانون.
وتكون مدة العضوية ثلاث سنوات قابلة للتجديد.
ويجتمع المجلس مرة على الأقل شهريا، ولا يكون أنعقاده صحيحا إلا بحضور ثلثى الأعضاء على الأقل، وله أن يشكل من بين أعضائه لجنة أو أكثر يعهد إليها بمهمة محددة ولرئيسه دعوة من يراه من الخبراء لحضور الاجتماعات كلما دعت الحاجة إلى ذلك.
وتصدر قرارات المجلس بأغلبية الحاضرين من الأعضاء، وفى حالة تساوى الأصوات يرجح الجانب الذى منه الرئيس وتنظم اللائحة التنفيذية لهذا القانون نظام عمل المجلس.
ويقوم أعضاء مجلس الإدارة بالإفصاح عن جميع أموالهم، على أن يتم تقديم ومراجعة هذا الإفصاح سنويا من قبل جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلى أو محتمل للمصالح، على أن يرفع هذا التقرير إلى المجلس الأعلى عن طريق الوزير المختص.$m229$,'296afd560203a1156938cf07532bb0de'),
(74,0,$m229$المادة 74$m229$,$m229$مجلس إدارة الهيئة هو السلطة العليا المهيمنة على شئونها، وعليه أن يتخذ ما يراه لازما من قرارات لتحقيق الأغراض التى أنشئت الهيئة من أجلها طبقا لأحكام هذا القانون ولائحته التنفيذية ويتولى على الأخص ما يلى:
1 - وضع خطط نشاط الهيئة وبرامجها فى إطار السياسة الاستثمارية للدولة.
2 - وضع آليات تفعيل منظومة مركز خدمات المستثمرين، ومتابعة تنفيذها.
3 - تحديد مقابل الخدمات التى تقدمها الهيئة.
4 - إقرار اللوائح الداخلية والقرارات التنفيذية المتعلقة بالشئون المالية والإدارية والفنية للهيئة، ووضع هيكلها التنظيمى.
5 - إقرار مشروع الموازنة للهيئة وحساباتها الختامية.
6 - وضع ضوابط تشكيل واختصاصات ونظم عمل مجالس إدارات المناطق الحرة والاستثمارية، على أن يصدر بالتشكيل والاختصاصات قرار من الرئيس التنفيذى للهيئة.
7 - إقرار اللوائح والنظم واعتماد النماذج اللازمة لإقامة المناطق الحرة والاستثمارية وتنميتها وإدارتها، وتحديد ضوابط وآليات إلغاء المشروعات المقامة وفقا لأنظمة الاستثمار المختلفة، والمدد اللازمة لسقوط الموافقات الصادرة بشأنها.
8 - اعتماد شروط منح التراخيص وشغل العقارات واسترددها بما عليها من مبان وأنشاءات وما بداخلها وعلى الأخص ما يتعلق بالمناطق الاستثمارية وفقا لأحكام هذا القانون.
9 - اعتماد ضوابط قواعد دخول البضائع وخروجها وأحكام قيدها ومقابل شغل الأماكن التى تودع بها، وفحص المستندات والمراجعة والنظام الخاص برقابة المناطق الحرة وحراستها وتحصيل الرسوم المستحقة، وذلك بالتنسيق مع مصلحة الجمارك.
10 - الموافقة على أنشاء فروع ومكاتب للهيئة لتفعيل مركز خدمات المستثمرين المنصوص عليه فى هذا القانون وتقديم خدمات الاستثمار.
11 - وضع نظام لميكنة خدمات الاستثمار التى تقدم من خلال الهيئة.
12 - وضع النظم والقواعد التى تكفل تطبق مبادئ الحوكمة وأعمال قواعد التفتيش والرقابة اللاحقة على الشركات واتخاذ الإجراءات التى تكفل تطبيق مبادئ الحوكمة وأعمال قواعد التفتيش والرقابة اللاحقة على الشركات واتخاذ الإجراءات اللازمة لذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.
13 - وضع نظام يكفل توفير الإحصائات والبيانات والمعلومات اللازمة لمزاولة المشروع الاستثمارى لنشاطه، وذلك دون الإخلال باعتبارات الأمن القومى أو الحق فى الخصوصية وسرية المعلومات أو بحماية حقوق الغير، ويجب على جميع الجهات المختصة إمداد الهيئة بما يتطلبه وضع هذا النظام.
14 - طلب المعلومات والبيانات اللازمة لحساب أصول الاستثمار الأجنبى المباشر وغير المباشر من الجهات العامة والخاصة للأغراض الإحصائية، وفقا للممارسات الدولية المعمول بها، وذلك دون الإخلال باعتبارات الأمن القومى أو الحق فى الخصوصية وسرية المعلومات وحماية حقوق الغير، ويكون للهيئة فى سبيل ذلك إعداد نماذج واستبيانات لاستيفاء تلك المعلومات والبيانات وتطبيقها بجميع الوسائل بما فيها الوسائل الإلكترونية، على أن يصدر بها قرار من رئيس مجلس الوزراء، وتلتزم الجهات المشار إليها بموافاة الهيئة بهذه البيانات خلال الأجل الذى تحدده اللائحة التنفيذية لهذا القانون.
*البند (14) مضاف بموجب قانون رقم 141 لسنة 2019.$m229$,'ff524a456cb741671427cb1d0fe33915'),
(75,0,$m229$المادة 75$m229$,$m229$تتكون موارد الهيئة مما يأتى:
1 - الاعتمادات المالية التى تخصصها لها الدولة.
2 - الرسوم ومقابل الخدمات التى تحصلها الهيئة عدا تلك التى تحصلها لحساب الجهات الأخرى.
3 - الهبات والمنح والقروض المحلية والخارجية التى يوافق عليها مجلس إدارة الهيئة طبقا للقواعد المقررة فى هذا الشأن.
4 - مقابل شغل العقارات المملوكة أو المخصصة للهيئة.
5 - أى موارد أخرى يصدر بها قرار من مجلس إدارة الهيئة بعد موافقة مجلس الوزراء.$m229$,'c3a13ec930d02e2eb4e1e350d32e5cba'),
(76,0,$m229$المادة 76$m229$,$m229$يكون للهيئة موازنة مستقلة تعد على نمط موازنات الهيئات الاقتصادية، وتبدأ السنة المالية للهيئة مع السنة المالية للدولة وتنتهى بأنتهائها، وتخضع حساباتها وأرصدتها وأموالها لرقابة الجهاز المركزى للمحاسبات وتودع جميع موارد الهيئة فى حساب خاص تحت حساب الخزانة الموحد بالبنك المركزى المصرى، ويرحل فائض الموازنة من سنة إلى أخرى إلى الحساب الخاص، ويصرف من الحساب بقرار من مجلس إدارة الهيئة.$m229$,'ebc9064dac0695bae74ce89750d08f75'),
(77,0,$m229$المادة 77$m229$,$m229$يصدر بتعيين الرئيس التنفيذى للهيئة ونوابه وتحديد معاملتهم المالية قرار من رئيس مجلس الوزراء بناء على عرض الوزير المختص، وذلك لمدة ثلاث سنوات قابلة للتجديد لمدة واحدة، ولا يجوز أن يزيد عدد نواب رئيس الهيئة على خمسة نواب، وتحدد اختصاصات نواب الرئيس التنفيذى بقرار من الوزير المختص.
ويتولى الرئيس التنفيذى للهيئة تمثيلها أمام القضاء والغير، كما يتولى تصريف شئونها وتنفيذ قرارات مجلس إدارتها، وله فى سبيل ذلك اتخاذ ما يلزم لتيسير إجراءات الخدمات التى تقدمها الهيئة للمستثمرين، وكذا اتخاذ مايلزم لتفعيل نظام الرقابة والشفافية والحوكمة والإدارة الرشيدة.
ويجوز للرئيس التنفيذى تفويض أحد نوابه فى بعض اختصاصاته دون أن يتضمن التفويض تمثيل الهيئة أمام القضاء أو الغير.
وتبين اللائحة التنفيذية الاختصاصات والمهام الأخرى للرئيس التنفيذى.$m229$,'23398eb54f0783f5ecdef7cbf5501e82'),
(78,0,$m229$المادة 78$m229$,$m229$على الرئيس التنفيذى إعداد خطة سنوية، واستراتيجية مستدامة للهيئة كل خمس سنوات، وتقرير نصف سنوى يتضمن بيانا بنتائج أعمالها وما أنجزته فى سبيل تيسير إجراءات الاستثمار والترويج له، للعرض على مجلس إدارة الهيئة.
ويقدم الوزير المختص إلى كل من المجلس الأعلى ومجلس الوزراء الخطة السنوية للهيئة والتقرير المشار إليه، وما يتضمنه من نتائج، فى ضوء خطة الهيئة السنوية أو استراتيجيتها الخمسية وما أنجزته فى مجال تيسير إجراءات الاستثمار والترويج له وأبرز معوقات الاستثمار، وما تقترحه الوزارة المختصة من سياسات وإجراءات وتعديلات تشريعية لتحسين مناخ الاستثمار فى الدولة.
ويجوز للرئيس التنفيذى عند الضرورة وبعد موافقة مجلس إدارة الهيئة الموافقة على استكمال أو تطوير مقومات البنية الأساسية للمناطق الحرة العامة غير المملوكة للهيئة، على أن تئول إليها قيمة ما أنفقته خصما من مقابل الأنتفاع الذى يحصل من المشروعات المقامة بتلك المناطق لصالح الجهة مالكة الأرض.
وتبين اللائحة التنفيذية لهذا القانون ضوابط الاستكمال أو التطوير المشار إليهما، وأسس تحديد قيمة ما تم أنفاقه وطرق استرداده.$m229$,'b6ee37f4b3328ffdcc996623d68d30a9'),
(79,0,$m229$المادة 79$m229$,$m229$تقوم الهيئة سنويا بنشر قائمة الشركات التي تستفيد من الحوافز المنصوص عليها في هذا القانون في تقرير تنشره علي موقعها الإلكتروني يتضمن طبيعة النشاط وموقعه وطبيعة الحوافز وأسماء الشركات أو المساهمين أو مالكي الشركة.
كما تلتزم الهيئة سنويا بنشر قائمة الشركات المستفيدة من أراضي الدولة بموجب أحكام هذا القانون في تقرير يتضمن غرض استخدام الأرض وطبيعتها وأبعادها وموقعها بدقة وتقييم الخبراء وأسماء الشركاء والمساهمين أو أصحاب الشركة.
وتلتزم الشركات بتقديم بيان بحجم استثماراتها والقوائم المالية السنوية وبيان بعدد العاملين ووظائفهم وجنسياتهم ومجموع أجورهم وغير ذلك من بيانات تحددها اللائحة التنفيذية لهذا القانون.$m229$,'7b27a771a32349bcd32cd16849b6b2b2'),
(80,0,$m229$المادة 80$m229$,$m229$يكون لموظفي الهيئة ممن يصدر بتحديدهم قرار من وزير العدل بالإتفاق مع الوزير المختص صفة مأموري الضبط القضائي في إثبات الجرائم التي ترتكب بالمخالفة لأحكام هذا القانون وقانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981 والقرارات المنفذة لهما، ولهم في سبيل ذلك دخول بقرار من الرئيس التنفيذي علي أن يعرض عليه تقرير بنتائج أعمالهم وعلي المشروعات الإستثمارية المعنية تسهيل مهمتهم.$m229$,'a7448645dce610f6fb30dfde0ca3aa52'),
(81,0,$m229$المادة 81$m229$,$m229$في حالة مخالفة الشركات أو المنشأت لأحكام هذا القانون، تقوم الهيئة بأنذار الشركات أو المنشأت فورا لإزالة أسباب المخالفة في مدة لا تجاوز خمسة عشر يوم عمل من تاريخ الأنذار.
ويتضمن الأنذار المدة المحددة لإزالة أسباب المخالفة، فاذا أنقضت هذه المدة دون ذلك كان للرئيس التنفيذي للهيئة بعد موافقة مجلس الإدارة إصدار قرار بإيقاف نشاط الشركة أو المنشأة مدة لا تجاوز تسعين يوما، فإذا استمرت الشركة أو المنشأة في ارتكاب المخالفة أو الاستمرار فيها أو ارتكبت مخالفة أخري خلال سنة من المخالفة الأولي جاز اتخاذ أحد الإجراءات الأتية:
أ- إيقاف التمتع بالحوافز والإعفاءات المقررة.
ب- تقصير مدة التمتع بالحوافز والإعفاءات المقررة.
ج- أنهاء التمتع بالحوافز والإعفاءت المقررة، مع ما ترتب علي ذلك من أثار بالنسبة للقرارات والتراخيص الصادرة للشركات والمنشآت.
د- إلغاء ترخيص مزاولة النشاط.
وبالنسبة للمخالفات التي تهدد الصحة العامة أو أمن المواطنين أو الأمن القومي يكون للرئيس التنفيذي للهيئة بعد إخطار مجلس إدارة الهيئة إصدار قرار بإيقاف النشاط مدة تسعين يوما، فاذا استمرت الشركة أو المنشأة في ارتكاب المخالفة أو ارتكبت مخالفة أخري خلال سنة من المخالفة الأولى كان له إلغاء الترخيص.$m229$,'c1f4a4a711eea033dfd2cdcf3ff6e03d'),
(82,0,$m229$المادة 82$m229$,$m229$مع عدم الإخلال بالحق فى التقاضي، تجوز تسوية أي نزاع ينشأ بين المستثمر وأي جهة أو أكثر من الجهات الحكومية يتعلق برأسمال المستثمر أو بتفسير أحكام هذا القانون أو تطبيقه وديا دون تأخير من خلال المفاوضات بين الأطراف المتنازعة.$m229$,'2d0ce5028ddda7a4abf0d49be310840e'),
(83,0,$m229$المادة 83$m229$,$m229$تنشأ بالهيئة لجنة أو أكثر لنظر التظلمات من القرارات الصادرة وفقا لأحكام هذا القانون من الهيئة أو الجهات المختصة بمنح الموافقات والتصاريح والتراخيص.
وتشكل اللجنة برئاسة مستشار من إحدى الجهات القضائية تحدده المجالس الخاصة بتلك الجهات وعضوية ممثل عن الهيئة وأحد ذوى الخبرة.
ويصدر بتشكيل اللجنة ونظام عملها وأمانتها الفنية قرار من الوزير المختص.$m229$,'91476519febf340be7e63b3e3638e5cf'),
(84,0,$m229$المادة 84$m229$,$m229$تقدم التظلمات إلى اللجنة خلال خمسة عشر يوم عمل من تاريخ الإخطار أو العلم بالقرار المتظلم منه ويترتب على تقديم التظلم أنقطاع مواعيد الطعن، وللجنة الاتصال بذوى الشأن والجهات الإدارية المختصة لطلب تقديم الايضاحات والمستندات والإجابة على الاستفسارات التى تراها لازمة، ولها أن تستعين بالخبرات والتخصصات المختلفة بالهيئة وغيرها من الجهات الإدارية.
وتفصل اللجنة فيما يعرض عليها بقرار مسبب خلال ثلاثين يوما من تاريخ أنتهاء سماع الأطراف وتقديم وجهات نظرهم، ويكون قرارها فى هذا الشأن نهائيا وملزما لجميع الجهات المختصة، وذلك دون إخلال بحق المستثمر فى اللجوء إلى القضاء.
وتبين اللائحة التنفيذية مكان أنعقاد اللجنة وكيفية الإخطار بقراراتها.$m229$,'1a9136b9beccfd87503c471a1e47ba6f'),
(85,0,$m229$المادة 85$m229$,$m229$تنشأ لجنة وزارية تسمى (اللجنة الوزارية لفض منازعات الاستثمار) تختص بالنظر فيما يقدم أو يحال إليها من طلبات أو شكاوى أو منازعات قد تنشأ بين المستثمرين والدولة أو تكون إحدى الجهات أو الهيئات أو الشركات التابعة لها طرفا فيها ويصدر بتشكيل اللجنة قرار من رئيس مجلس الوزراء، ويشارك فى عضويتها أحد نواب رئيس مجلس الدولة يختاره المجلس الخاص للشئون الإدارية بمجلس الدولة، وتعتمد قراراتها من مجلس الوزراء، ويجوز للوزراء من أعضاء اللجنة فى حالة الضرورة إنابة من يمثلهم لحضور اجتماع اللجنة والتصويت على قراراتها فيه.
ويكون للجنة أمانة فنية، يصدر بتشكيلها ونظام عملها قرار من الوزير المختص.$m229$,'e752ffdfb04aad249e78aaf3b3ed2cd2'),
(86,0,$m229$المادة 86$m229$,$m229$يشترط لصحة أنعقاد اللجنة حضور رئيسها ونصف أعضائها الأصليين فى الأقل، وتصدر اللجنة قراراتها بأغلبية أصوات الحاضرين، وعند تساوى الأصوات يرجح الجانب الذى منه الرئيس.
وتلتزم الجهة الإدارية المختصة بتقديم المذكرات الشارحة والمستندات اللازمة بمجرد طلبها، وإذا كانت هذه الجهة من الجهات المشتركة فى عضوية اللجنة فلا يكون لها صوت معدود فى المداولات بالنسبة للموضوع المتعلق بها.
وتفصل اللجنة فيما يعرض عليها بقرار مسبب خلال ثلاثين يوما من تاريخ أنتهاء سماع الأطراف وتقديم وجهات نظرهم.$m229$,'3c16366500b64e4f6a843fcf1d5a54b3'),
(87,0,$m229$المادة 87$m229$,$m229$مع عدم الإخلال بحق المستثمر فى اللجوء إلى القضاء، تكون قرارات اللجنة بعد اعتمادها من مجلس الوزراء واجبة النفاذ وملزمة للجهات الإدارية المختصة ولها قوة السند التنفيذى، ويترتب على الامتناع عن تنفيذ قراراتها تطبيق أحكام المادة 123 من قانون العقوبات وتوقيع العقوبة بها. ولا يترتب على تقديم التظلم فى قرارات اللجنة وقف تنفيذها.$m229$,'546c9d9dc79f1ff4373df1db68acdccc'),
(88,0,$m229$المادة 88$m229$,$m229$تنشأ بمجلس الوزراء لجنة وزارية، تسمي (اللجنة الوزارية لتسوية منازعات عقود الاستثمار)، تختص بتسوية المنازعات الناشئة عن عقود الاستثمار التى تكون الدولة أو إحدى الجهات أو الهيئات أو الشركات التابعة لها طرفا فيها.
وتشكل هذه اللجنة بقرار من رئيس مجلس الوزراء، ويشارك فى عضويتها أحد نواب رئيس مجلس الدولة يختاره المجلس الخاص للشئون الإدارية بمجلس الدولة، وتعتمد قراراتها من مجلس الوزراء، ولا تجوز الإنابة فى حضور جلساتها.
ويشترط لصحة إنعقاد اللجنة حضور رئيسها ونصف عدد أعضائها، وتصدر اللجنة قراراتها بأغلبية الآراء وعندى تساوى الأصوات يرجح الجانب الذى منه الرئيس.
ويكون للجنة أمانة فنية يصدر بتشكيلها ونظام عملها قرار من رئيس مجلس الوزراء.$m229$,'c7ea2894fa67f8d0385eb00a1023dc11'),
(89,0,$m229$المادة 89$m229$,$m229$تتولى اللجنة بحث الخلافات الناشئة بين أطراف عقود الاستثمار ودراستها، ويكون لها فى سبيل ذلك وبرضاء أطراف التعاقد إجراء التسوية اللازمة لمعالجة اختلال توازن تلك العقود، ومد الآجال أو المدد أو المهل المنصوص عليها فيها.
كما تتولى متى لزم الأمر، إعادة جدولة المستحقات المالية أو تصحيح الإجراءات السابقة على إبرام العقود، وذلك كله على نحو يحقق قدر الإمكان التوازن العقدى ويضمن الوصول إلى أفضل وضع اقتصادى للحفاظ على المال العام وحقوق المستثمر فى ضوء ظروف كل حالة.
وتعرض اللجنة تقريرا بما تتوصل إلية بشأن حالة التسوية على مجلس الوزراء يبين جميع عناصرها، وتكون تلك التسوية بعد اعتمادها من مجلس الوزراء واجبة النفاذ وملزمة للجهات الإدارية المختصة ولها قوة السند التنفيذى.$m229$,'a8cbf6cfde062d55d979dbba6684e86b'),
(90,0,$m229$المادة 90$m229$,$m229$تجوز تسوية منازعات الاستثمار المتعلقة بتنفيذ أحكام هذا القانون بالطريقة التى يتفق عليها المستثمر أو وفقا لأحكام قانون التحكيم فى المواد المدنية والتجارية الصادر بالقانون رقم 27 لسنة 1994.
كما يجوز للطرفين، فى أى وقت من الأوقات خلال النزاع، الإتفاق على التماس سبل التسوية بمختلف أنواعها طبقا للقواعد المعمول بها لتسوية المنازعات، بما فى ذلك اللجوء إلى التحكيم غير المؤسسي(الحر)، أو التحكيم المؤسسى.$m229$,'f099294ae93b8f49126603f8ea2e1807'),
(91,0,$m229$المادة 91$m229$,$m229$ينشأ مركز مستقل للتحكيم والوساطة يسمي (المركز المصرى للتحكيم والوساطة) تكون له الشخصية الاعتبارية، ويتخذ من محافظة القاهرة مقرا له.
ويتولى المركز تسوية منازعات الاستثمار التى قد تنشأ بين المستثمرين، أو بينهم وبين الدولة أو إحدى الجهات التابعة لها عامة أو خاصة، إذا ما اتفقوا فى أى مرحلة على تسوية النزاع عن طريق التحكيم أو الوساطة أمام هذا المركز، وذلك كله مع مراعاة أحكام القوانين المصرية المنظمة للتحكيم وتسوية المنازعات.
ويتولى إدارة المركز مجلس إدارة، يتكون من خمسة أعضاء من ذوى الخبرة والتخصص والكفاءة والسمعة الطيبة يصدر بتعينهم قرار من رئيس مجلس الوزراء.
و تكون مدة مجلس الإدارة خمس سنوات يجوز تجديدها مرة واحدة، و لا يجوز عزل أحد أعضاء مجلس الإدارة طوال هذه المدة الإ اذا فقد الصلاحية الطبية لممارسة مهام عمله أو فقد الثقة و الاعتبار أو أخل إخلالا جسيما بواجبات عمله وفقا للنظام الأساسى للمركز.
و ينتخب اعضاء مجلس الإدارة من بينهم رئيسا للمجلس، و يكون للمركز مدير تنفيذى يصدر بتعيينه و تحديد معاملته المالية قرار من مجلس الإدارة.
و يصدر بالنظام الأساسى لهذا المركز و نظام العمل فيه و القواعد المهنية و الإجراءات المنظمة له و مقابل الخدمات التى يقدمها و قوائم المحكمين و الوسطاء و اتعباهم قرار من مجلس إدارة المركز و ينشر النظام الأساسى للمركز فى الوقائع المصرية.
و تتكون مواد المركز المالية من مقابل الخدمات التى يقدمها وفقا لما يحدده النظام الأساسى له و توفر فى الثلاث سنوات الأولى من تاريخ العمل بهذا القانون مواد مالية كافية للمركز من الخزانة العامة للدولة، و لا يجوز بخلاف ما تقدم الحصول على اى أموال من الدولة أو إحدى أجهزتها.$m229$,'ea9083617ec5346c6b4a986529b15fac'),
(91,1,$m229$المادة 91 مكرراً$m229$,$m229$يعاقب المسئول عن الإدارة الفعلية للشخص الاعتبارى على مخالفة حكم البند (14) من المادة (74) من هذا القانون بالغرامة التى لا تجاوز خمسين ألف جنيه، إذا ثبت علمه بالمخالفة وكان إخلاله بالواجبات التى تفرضها عليه تلك الإدارة قد أسهم ف وقوع الجريمة.
*مضافة بموجب قانون رقم 141 لسنة 2019.$m229$,'82fa35c1c7754b0ba854dec5e9d8f868'),
(92,0,$m229$المادة 92$m229$,$m229$فى الأحوال التى ترتكتب فيها الجريمة باسم الشخص الأعتبارى الخاص و لحسابه، لا يعاقب المسئول عن الإدارة الفعلية الإ اذا ثبت علمه بالجريمة و اتجهت إرادته لارتكابها تحقيقا لمصلحة نفسه أو غيره و ذلك دون الإخلال باحكام المسئولية المدنية.
و فى الحالة التى لا تثبت فيها مسئولية الشخص الطبيعى على النحو المحدد فيها من الفقرة السابقة يعاقب الشخص الاعتبارى بغرامة لا تقل عن اربعة امثال الغرامة المقررة قانونا للجريمة و لا تجاوز عشرة امثالها و فى حالة العود يحكم بالغاء الترخيص أو حل الشخص الاعتبارى بحسب الأحوال و ينشر الحكم فى جريدتين يوميتين واسعتى الأنتشار على نفقة الشخص الاعتبارى.$m229$,'4670f5d56ed01e11fece38c65b45f1c6'),
(93,0,$m229$المادة 93$m229$,$m229$فى غير حالة التلبس يكون طلب الدعوى الجنائية فى الجرائم المنصوص عليها فى قانون الجمارك الصادر بالقانون 66 لسنة 1963، و قانون الضريبى على الدخل الصادر بالقانون 91 لسنة 2005، و قانون الضريبة على القيمة المضافة الصادر بالقانون 67 لسنة 2016، بعد أخذ راى الوزير المختص اذا كان المتهم بارتكاب الجريمة تابعا لأحد المشروعات الاستثمارية الخاضعة لأحكام هذا القانون.
و يتعين على الوزير المختص ابداء الراى فى هذا الشأن خلال سبعة أيام من تاريخ ورود كتب استطلاع الراى اليه و الإ جاز رفع الدعوى طبقا للقواعد المقررة فى القوانين المشار اليها.$m229$,'1d50bbe0a20666336a36d449270a3ca6'),
(94,0,$m229$المادة 94$m229$,$m229$مع عدم الاخلال بالمادة 131 من قانون البنك المركزى و الجهاز المصرفى و النقد الصادر بالقانون 88 لسنة 2003، و المادة السادسة عشرة من القانون 10 لسنة 2009 بتنظيم الرقابة على الاسواق و الأدوات المالية غير المصرفية، لا يجوز رفع الدعوى الجنائية أو اتخاذ أى إجراء من إجراءات التحقيق قبل المستثمر فى الجرائم المنصوص عليها فى الباب الرابع من الكتاب الثانى من قانون العقوبات الا بعد أخذ راى الوزير المختص على النحو المنصوص عليه فى المادة (93) من هذا القانون بالقواعد ذاتها.$m229$,'87f880968ed33006c766651830afa6d9');

INSERT INTO m229_ver VALUES
(0,0,1,$m229$قانون رقم 72 لسنة 2017 بتاريخ 31/05/2017 بإصدار قانون الاستثمار$m229$,'77cc3a6d687e1d9027d67e1697e1511c',DATE '2017-05-31',NULL,'active',NULL,NULL,NULL),
(1,-1,1,$m229$يعمل فى شأن الاستثمار فى جمهورية مصر العربية بأحكام القانون المرافق.
وتسرى أحكامه على الاستثمار المحلى والأجنبى أيا كأن حجمه، ويكون الاستثمار وفقا لأحكام هذا القانون إما بنظام الاستثمار الداخلى أو بنظام المناطق الاستثمارية أو بنظام المناطق التكنولوجية، أو بنظام المناطق الحرة.$m229$,'76a5b102106927343e30d52028a9629f',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(1,0,1,$m229$فى تطبيق أحكام هذا القانون يقصد بالكلمات والعبارات التالية المعاني المبينة قرين كل منها:
الاستثمار: استخدام المال لأن شاء مشروع استثمارى أو توسيعه أو تطويره أو تمويله أو تملكه أو إدارته بما يسهم في تحقيق التنمية الشاملة والمستدامة للبلاد.
المستثمر: كل شخص طبيعي أو اعتباري مصريا كأن أو اجنبيا أيا كأن النظام القانوني الخاضع له يقوم بالإستثمار في جمهورية مصر العربية وفقا لأحكام هذا القانون.
المشروع الإستثمارى: مزاولة أحد الأنشطة الإستثمارية في قطاعات الصناعة والزراعة والتجارة والتعليم والصحة والنقل والسياحة والإسكان والتشييد والبناء والرياضة والكهرباء والطاقة والثروات الطبيعية والمياه والإتصالات والتكنولوجيا.
ويجوز للوزير المختص بشئون الإستثمار بالتنسيق مع الوزارة أو الوزارت المعنية إضافة قطاعات أخرى وفقا لخطة التنمية الأقتصادية للدولة، وتبين اللائحة التنفيذية لهذا القانون شروط ونطاق وضوابط مزاولة هذه الأنشطة.
الحوافز الخاصة: الحوافز المنصوص عليها فى المادتين (11 و 11 مكررا) من هذا القانون.
الأموال: جميع أنواع الأصول التي تدخل في المشروع الأستثمارى أيا كان نوعها وتكون لها قيمة مادية سواء كانت نقدية أو عينية أو معنوية، وتشمل علي الأخص:
1 - الأموال الثابتة والمنقولة، وكذلك أي حقوق عينية أصلية أو تبعية أخرى.
2 - الأسهم وحصص تأسيس الشركات، والسندات غير الحكومية.
3 - حقوق الملكية الفكرية والحقوق المعنوية التي تستخدم في إنشاء المشروعات أو التوسع فيها، كبراءات الاختراع والعلامات والأسماء التجارية المسجلة فى دولة من دول المنظمة العالمية للملكية الفكرية أو وفقا لقواعد التسجيل الدولية التي تضمنتها الاتفاقيات الدولية النافذة في هذا الشأن.
4 - الامتيازات أو العقود التي تمنح بمقتضي قوانين التزامات المرافق العامة والقوانين ذات الطبيعة المماثلة لها وكذلك جميع الحقوق المماثلة الأخري التي تعطي بناء علي القانون.
المجلس الأعلي: المجلس الأعلى للاستثمار.
الوزير المختص: الوزير المختص بشئون الاستثمار.
الوزارة المختصة: الوزراة المختصة بشئون الأستثمار.
الهيئة: الهيئة العامة للاستثمار والمناطق الحرة.
الأستثمار الداخلي: أحد نظم الاستثمار يتم خلاله إقامة أو أن شاء أو تشغيل مشروع استثماري وفقا لأحكام هذا القانون في غير المناطق الحرة.
المنطقة الحرة: جزء من إقليم يدخل ضمن حدودها ويخضع لسلطاتها الإدارية ويتم التعامل فيه وفقا لأحكام جمركية وضريبية خاصة.
المنطقة الإستثمارية: منطقة جغرافية محددة المساحة والحدود، تخصص لإقامة نشاط معين أو أكثر من الأنشطة الاستثمارية المتخصصة وغيرها من الأنشطة المكملة لها، يقوم علي تنميتها ووضع بنيتها الأساسية مطور لتلك المنطقة.
المطور: كل شخص اعتبارى يرخص له أن شاء منطقة استثمارية أو إدارتها أو تطويرها أو تنميتها وفقا لأحكام هذا القانون.
الجهات المختصة: الجهات الإدارية أو شركات المرافق العامة المختصة بإصدار الموافقات أو التصاريح أو التراخيص.
مركز خدمات المستثمرين: وحدة إدارية منشأة بالهيئة أو أحد فروعها تتولي تطبيق نظام لتيسير وتبسيط إجراءات حصول المستثمر علي جميع الموافقات والتصاريح والتراخيص اللازمة لمشروعه الاستثماري خلال المدد القانونية المنصوص عليها في هذا القانون، وإتاحة ما يلزم لذلك من بيانات ومعلومات.
ممثل الجهة المختصة: المسئول المنتدب من الجهات الإدارية المختصة أو المكلف من شركات المرافق العامة، للعمل في نظام مركز خدمات المستثمرين بالهيئة أو أحد فروعها، والذي تنتقل إليه بموجب أحكام هذه القانون سلطة إصدار الموافقات والتصاريح والتراخيص، بحسب الاشتراطات الفنية الواردة بالقوانين المنظمة لها و دليل إجراءات الاستثمار الذي تصدره الهيئة، وكذا جميع الصلاحيات المقررة للسلطة المختصة في مجال تخصيص العقارات و إعطاء الموافقات والتصاريح والتراخيص اللازمة لتبسيط عمل المستثمر وتيسيره وتشجيع الاستثمار و تنميته.
السلطة المختصة: الوزير أو المحافظ أو رئيس الهيئة أو المصلحة أو مجلس إدارتها أو رئيس مجلس إدارة شركة الموافق العامة أو مجلس إدارتها بحسب الأحوال.
مكاتب الإعتماد: المكاتب المرخص لها من الهيئة بمنح الموافقات والتصاريح والتراخيص، بالعمل في مجال فحص الإجراءات والمستندات الخاصة بالمشروعات الإستثمارية وتقديم شهادات الإعتماد.
*أستبدل بتعريف الحوافز الخاصة الوارد بالمادة (1) بوجب قانون رقم 160 لسنة 2023.$m229$,'cac352e97d44f8ee60bb2f96749837a1',DATE '2023-07-26',NULL,'active',160,2023,$m229$أستبدل بتعريف الحوافز الخاصة الوارد بالمادة (1) بوجب قانون رقم 160 لسنة 2023. نصه قبل التعديل كما ورد فى المصدر: «الحوافز الخاصة: الحوافز المنصوص عليها في المادة (11) من هذا القانون.» تاريخ النفاذ المسجل: تاريخ العمل بـالقانون 160 لسنة 2023 (إصدار 25/7/2023؛ العمل به 26/7/2023).$m229$),
(2,-1,1,$m229$لا تخل أحكام القانون المرافق بالمزايا والإعفاءات الضريبية وغيرها من الضمانات والحوافز المقررة للشركات والمنشآت القائمة وقت العمل به، وتظل هذه الشركات والمنشآت محتفظة بتلك المزايا والإعفاءات والضمانات والحوافز إلى أن تنتهي المدد الخاصة بها وذلك طبقا للتشريعات والاتفاقيات المستمدة منها.
ولا تخل أحكام القانون المرافق بأحكام القانون رقم 7 لسنة 1991 بشأن أملاك الدولة الخاصة وقانون المناطق الاقتصادية ذات الطبيعة الخاصة الصادر بالقانون رقم 83 لسنة 2002، والقانون رقم 14 لسنة 2012 في شأن التنمية المتكاملة في شبه جزيرة سيناء، و قانون تيسير إجراءات منح تراخيص المنشآت الصناعية الصادر بالقانون رقم 15 لسنة 2017.
كما لا تخل أحكام القانون المرافق بالشروط الموضوعية المقررة لمنح الموافقات والتصاريح والتراخيص المنصوص عليها فى أي قوانين أخرى.$m229$,'29572659e759c6841ac71f4a49192958',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(2,0,1,$m229$يهدف الاستثمار في جمهورية مصر العربية إلي رفع معدلات النمو الاقتصادي للبلاد، وزيادة معدلات الأنتاج المحلي، وتوفير فرص العمل، وتشجيع التصدير، وزيادة التنافسية، بما يسهم في تحقيق التنمية الشاملة والمستدامة.
وتعمل جميع أجهزة الدولة المختصة علي جذب وتحفيز الاستثمارات المحلية والأجنبية.
ويحكم الاستثمار المبادئ الأتية:
1 - المسأو اة فى الفرص الاستثمارية ومراعاة تكافؤ الفرص بغض النظر عن حجم المشروع ومكأنه ودون تمييز بسبب الجنس.
2 - دعم الدولة للشركات الناشئة وزيادة الأعمال والمشروعات متناهية الصغر والصغيرة والمتوسطة لتمكين الشباب وصغار المستثمرين.
3 - مراعاة جميع النواحي ذات البعد الاجتماعي وحماية البيئة والصحة العامة.
4 - حرية المنافسة ومنع الممارسات الاحتكارية وحماية المستهلك.
5 - اتباع مبادئ الحوكمة والشفافية والإدارة الرشيدة وعدم تضارب المصالح.
6 - العمل على استقرار السياسيات الإستثمارية وثابتها.
7 - سرعة أنجاز معاملات المستثمرين والتيسير عليهم بما يحقق مصالحهم المشروعة.
8 - حق الدولة فى الحفاظ على الأمن القومى والمصلحة العامة.
وتسرى مبادئ الاستثمار المشار إليها علي المستثمر والدولة كل فيما يخصه.$m229$,'fca4034985cd3b96fcd576fb2af7bb5b',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(3,-1,1,$m229$تستبدل عبارة (قانون الاستثمار) بعبارة (قانون ضمانات وحوافز الاستثمار)، أينما وردت فى القوانين والقرارات الأخرى.$m229$,'6c7cd829b4d4665587f55a9a79da3027',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(3,0,1,$m229$تتمتع جميع الاستثمارات المقامة فى جمهورية مصر العربية بالمعاملة العادلة والمنصفة.
وتكفل الدولة للمستثمر الأجنبي معاملة مماثلة لتلك التي تمنحها للمستثمر الوطني.
ويجوز استثناء بقرار من مجلس الوزراء تقرير معاملة تفضيلية للمستثمرين الأجانب تطبيقا لمبدأ المعاملة بالمثل.
ولا تخضع الأموال المستثمرة لأي إجراءات تعسفية أو قرارات تتسم بالتمييز.
وتمنح الدولة المستثمرين غير المصريين إقامة فى جمهورية مصر العربية طوال مدة المشروع، وذلك دون الإخلال بأحكام القوانين المنظمة لذلك وعلي النحو الذي تبينه اللائحة التنفيذية لهذا القانون.
وتلتزم الدولة باحترام وإنفاذ العقود التي تبرمها ولا يتمتع المشروع الاستثماري المقام بناء علي غش أو تدليس أو فساد بالحماية أو الضمانات أو المزايا أو الإعفاءات المقررة بموجب أحكام هذا القانون، ويكون اثبات ذلك كله بموجب حكم قضائي بات صادر من القضاء المختص أو بحكم تحكيم.
وفي مجال تطبيق أحكام هذا القانون، تكون جميع القرارات المتعلقة بشئون المشروع الإستثمارى مسببة، ويخطر ذوو الشأن بها، وذلك علي النحو الذي تنظمه اللائحة التنفيذية لهذا القانون.$m229$,'703dce7cbf0dcb3418492cd2b3ec03fc',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(4,-1,1,$m229$تستثنى شركات المساهمة الخاضعة لأحكام هذا القانون من تطبيق أحكام القانون رقم 113 لسنة 1958 في شأن التعيين في وظائف شركات المساهمة والمؤسسات العامة.
كما لا تخضع شركات المساهمة لأحكام القانون رقم 73 لسنة 1973 بشأن تحديد شروط وإجراءات أنتخاب ممثلي العمال في مجالس إدارة وحدات القطاع العام والشركات المساهمة والجمعيات والمؤسسات الخاصة، ويبين نظام الشركة طريقة اشتراك العاملين في إدارتها.$m229$,'cb54867fbcf82a04b562d28f2cfe8f14',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(4,0,1,$m229$لا يجوز تأميم المشروعات الاستثمارية.
ولا يجوز نزع ملكية أموال المشروعات الاستثمارية إلا للمنفعة العامة، وبمقابل تعويض عادل يدفع مقدما دون تأخير، وتكون قيمته معادلة للقيمة الإقتصادية العادلة للمال المنزوع ملكيته في اليوم السابق علي صدور قرار نزع الملكية، وتكون التعويضات قابلة للتحويل دون قيد.
ولا يجوز بالطريق الإدارى فرض الحراسة علي تلك المشروعات، ولا تفرض الحراسة عليها إلا بموجب حكم قضائي نهائى، كما لا يجوز التحفظ عليها إلا بموجب أمر أو حكم قضائي، ولا يكون ذلك كله إلا في الأحوال المبينة في القانون.
ولا يجوز الحجز علي أموال المشروعات الاستثمارية أو مصاردتها أو تجميدها إلا بناء علي أمر قضائي أو حكم نهائي، وذلك عدا الديون الضريبية، واشتراكات التأمينات الاجتماعية المستحقة للدولة التي يجوز تحصيلها عن طريق الحجز بجميع أنواعه، مع عدم الاخلال بما يتفق عليه في العقود التي تبرمها الدولة أو الأشخاص الاعتبارية العامة مع المستثمر.
ولا يجوز لأي جهة إدارية إصدار قرارات تنظيمة عامة تضيف أعباء مالية أو إجرائية، تتعلق بإنشاء أو تشغيل مشروعات تخضع لأحكام هذا القانون أو فرض رسوم أو مقابل خدمات عليها أو تعديلها، إلا بعد أخذ رأي مجلس إدارة الهيئة وموافقة كل من مجلس الوزراء والمجلس الأعلى.$m229$,'46bc6327bce98a8ea76f393afd4501f9',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(5,-1,1,$m229$تستثنى المنازعات الناشئة عن تطبيق أحكام هذا القانون والقانون المرافق له، من الخضوع لأحكام القانون رقم 7 لسنة 2000 بأنشاء لجان التوفيق فى بعض المنازعات التى تكون الوزارات والاشخاص الاعتبارية العامة طرفا فيها.$m229$,'489fc0f24cb248746beeed71f7ca36e0',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(5,0,1,$m229$لا يجوز للجهات الإدارية إلغاء التراخيص الصادرة للمشروع الاستثماري أو وقفها أو سحب العقارات التي تم تخصيصها للمشروع إلا بعد أن ذار المستثمر بالمخالفات المنسوبة إليه، وسماع وجهة نظره، وإعطائه مهلة مناسبة لإزالة أسباب المخالفة.
وفي جميع الأحوال، يجب أخذ رأي الهيئة قبل إصدار القرارات المشار إليها في الفقرة الأو لي، وتبدي الهيئة رأيها خلال سبعة أيام من تاريخ ورود الطلب إليها مستوفيا جميع الإجراءات القانونية المقررة.
ويحق للمستثمر التظلم من هذا القرار أمام اللجنة المنصوص عليها بالمادة (83) من هذا القانون.
وتنظم اللائحة التنفيذية لهذا القانون قواعد تطبيق أحكام هذه المادة وضوابطها.$m229$,'910227c2c64c7c44248c92c443921e8f',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(6,-1,1,$m229$تحال التظلمات والطلبات المنظورة أمام لجنتي فض منازعات الاستثمار و تسوية منازعات عقود الاستثمار القائمتين، إلى اللجنتين المنصوص عليهما فى المادتين 85، 88 من القانون المرافق فور تشكيلها دون الحاجة إلى أى إجراء آخر.$m229$,'3b99a303988f9ffb5404e47e789a3702',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(6,0,1,$m229$للمستثمر الحق فى أنشاء وإقامة المشروع الاستثماري وتوسيعه، وتمويله من الخارج دون قيود وبالعملة الأجنبية، كما يكون من حقه تملكه، وإدارته، واستخدامه، والتصرف فيه، وجنى أرباحه وتحويلها إلى الخارج، وتصفية المشروع، وتحويل ناتج هذه التصفية كله أو بعضه إلى الخارج، وذلك دون الإخلال بحقوق الغير.
وتسمح الدولة باتاحة جميع عمليات التحويل النقدي المتصل بالاستثمار الاجنبي بحرية وبدون إبطاء إلي أراضيها وإلى خارجها، بعملة قابلة للتحويل الحر كما تسمح الدولة بتحويل العملة المحلية إلي عملة قابلة للاستخدام بحرية دون تأخير.
وفى حالة التصفية تلتزم الجهات الإدارية المختصة بإخطار الهيئة والشركة تحت التصفية ببيأن ما عليها من التزامات خلال مدة اقصاها مائة وعشرون يوما تبدأ من تاريخ تقديم المصفى طلبا بذلك مرفقا به المستندات اللازمة ويعتبر إنقضاء هذه المدة دون بيأن تلك الالتزامات إبراء لذمة الشركات تحت التصفية وذلك دون الاخلال بالمسئولية الجنائية والتأديبية للمسئول عن اصدار بيان على خلاف الواقع أو من تسبب فى فوات الميعاد المشار إلية دون الرد على الطلب.
وذلك كله وفقا لما تحدده اللائحة التنفيذية لهذا القانون.$m229$,'f7a12218d21035529eaaba10342ba811',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(7,-1,1,$m229$يستمر العاملون المخاطبون بحكم الفقرة الثالثة من المادة (20) من قانون الاستثمار الصادر بالقانون رقم 230 لسنة 1989 فى التمتع بذات الأو ضاع المقررة لهم ولا تخل هذه الأحكام بنظام توزيع الأرباح المطبق على الشركات القائمة وقت نفاذ هذا القانون إذا كأن ذلك أفضل لهم$m229$,'e78b0cf382df4dbf2ad4bf2190b5a9bc',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(7,0,1,$m229$مع عدم الإخلال بأحكام القوانيين واللوائح والقرارات المنظمة للإستيراد، يحق للمشروعات الاستثمارية الخاضعة لأحكام هذا القانون أن تستورد بذاتها أو عن طريق الغير، ما تحتاج إلية فى إنشائها أو التوسع فيها أو تشغيلها من المواد الخام ومستلزمات الأنتاج والآلات وقطع الغيار ووسائل النقل المناسبة لطبيعة نشاطها، دون حاجه لقيدها فى سجل المستوردين.
كما يحق لهذه المشروعات أن تصدر منتجاتها بالذات أو بالوساطة دون ترخيص وبغير حاجة لقيدها فى سجل المصدرين.
وتلتزم المشروعات الاستثمارية التى تقوم بالاستيراد أو التصدير وفقا لأحكام هذه المادة سواء بنفسها أو عن طريق الغير بإخطار الهيئة بتقرير ربع سنوى عن الكميات والأنواع المستوردة أو المصدرة بحسب الاحوال.$m229$,'03b51fdca78147334071da59021765c7',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(8,-1,1,$m229$يلغى قانون ضمانات وحوافز الاستثمار الصادر بالقانون رقم 8 لسنة 1997، كما يلغى كل حكم يخالف أحكام هذا القانون والقانون المرافق له.$m229$,'c74e28f7c75c8ae4f52491aa9b2c7ad1',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(8,0,1,$m229$للمشروع الاستثمارى الحق فى استخدام عاملين أجانب فى حدود نسبة (10%) من إجمالى عدد العاملين بالمشروع، وتجوز زيادة هذه النسبة إلى مالا يزيد على (20%) من إجمالى عدد العاملين بالمشروع، وذلك فى حالة عدم إمكانية استخدام عمالة وطنية تملك المؤهلات اللازمة، وذلك وفقا للضوابط والقواعد التى تبينها اللائحة التنفيذية لهذا القانون.
ويجوز فى بعض المشروعات الاستراتيجية ذات الأهمية الخاصة التى يصدر بتحديدها قرار من المجلس الاعلى الاستثناء من النسب المشار إليها بشرط مراعاة تدريب العمالة الوطنية.
وللعاملين الأجانب فى المشروع الاستثمارى الحق فى تحويل مستحقاتهم المالية كلها أو بعضها إلى الخارج.$m229$,'0f0b1d9d39e2a2001f4366e2faf3efa9',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(9,-1,1,$m229$يصدر رئيس مجلس الوزراء اللائحة التنفيذية للقانون المرافق، بناء على عرض الوزير المختص وبعد موافقة مجلس الوزراء خلال تسعين يوما من تاريخ العمل بهذا القانون، وإلى أن تصدر هذه اللائحة يستمر العمل باللوائح والقرارات السارية القائمة في تاريخ العمل به فيما لا يتعارض مع أحكامه.$m229$,'64298ee7d204b0365e833ee9c02eb15f',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(9,0,1,$m229$تتمتع جميع المشروعات الاستثمارية الخاضعة لأحكام هذا القانون بالحوافز العامة الواردة فى هذا الفصل، وذلك فيما عدا المشروعات المقامة بنظام المناطق الحرة.$m229$,'dcb455c42c6927832bfe11b443569d13',DATE '2017-06-01',DATE '2023-07-25','amended',160,2023,$m229$النص قبل التعديل بالقانون رقم 160 لسنة 2023 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»). تاريخ بدء نفاذ النص الأصلى مسجل تقريباً (اليوم التالى لتاريخ إصدار القانون 31/5/2017 على افتراض نشره فى يوم إصداره).$m229$),
(9,0,2,$m229$تتمتع جميع المشروعات الاستثمارية الخاضعة لأحكام هذا القانون، سواء المقامة قبل العمل بأحكامه أو بعده، أيا كان النظام القانونى الخاضعة له، بالحوافز العامة الواردة فى هذا الفصل، وذلك فيما عدا المشروعات المقامة بنظام المناطق الحرة.
*معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'fbed6db4e3885ef0ff3c9251c781a5a6',DATE '2023-07-26',NULL,'active',160,2023,$m229$عدلت بالقانون رقم 160 لسنة 2023 (إصدار 25/7/2023؛ العمل به 26/7/2023).$m229$),
(10,-1,1,$m229$ينشر هذا القانون في الجريدة الرسمية، ويعمل به من اليوم التالي لتاريخ نشره.
يبصم هذا القانون بخاتم الدولة، وينفذ كقانون من قوأن ينها.
صدر برئاسة الجمهورية فى 5 رمضأن سنة 1438 هـ (الموافق 31 مايو سنة 2017).
عبد الفتاح السيسى$m229$,'68420e2166406914ddb2d63a26902b4a',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(10,0,1,$m229$تعفى من ضريبة الدمغة ومن رسوم التوثيق والشهر عقود تأسيس الشركات والمنشآت وعقود التسهيلات الإئتمانية والرهن المرتبطة بأعمالها، وذلك لمدة خمس سنوات من تاريخ قيدها فى السجل التجارى.
كما تعفى من الضريبة والرسوم المشار إليها عقود تسجيل الأراضى اللازمة لإقامة الشركات والمنشآت.
وتسرى على الشركات والمنشآت الخاضعة لأحكام هذا القانون أحكام المادة (4) من قانون تنظيم الإعفاءات الجمركية الصادرة بالقانون رقم 186 لسنة 1986 الخاصة بتحصيل ضريبة جمركية بفئة موحدة مقدارها (2%) اثنان بالمائة من القيمة، وذلك على جميع ما تستورده من آلات ومعدات وأجهزة لازمة لإنشائها.
كما تسرى هذه الفئة الموحدة على جميع ما تستورده الشركات والمنشآت التى تعمل فى مشروعات المرافق العامة، من آلات ومعدات وأجهزة لازمة لإنشائها أو إستكمالها.
ومع عدم الإخلال بأحكام الافراج المؤقت المنصوص عليها فى قانون الجمارك الصادر بالقانون رقم 66 لسنة 1963، يكون للمشروعات الاستثمارية ذات الطبيعة الصناعية الخاضعة لأحكام هذا القانون استيراد القوالب والأسطمبات وغيرها من مستلزمات الإنتاج ذات الطبيعة المماثلة دون رسوم جمركية وذلك لاستخدامها فترة مؤقتة فى تصنيع منتجاتها، وإعادة تصديرها إلى الخارج.
ويكون الإفراج والإعادة إلى الخارج بموجب مستندات الوصول، على أن تسجل مستندات الدخول وإعادة الشحن فى سجلات تعد لهذا الغرض بالهيئة وذلك بالتنسيق مع وزارة المالية.$m229$,'029ea63612fa097e8a54fc22ac9a90f5',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(11,0,1,$m229$تمنح المشروعات الاستثمارية التى تقام بعد العمل بهذا القانون وفقا للخريطة الاستثمارية، حافزا استثماريا خصما من صافى الأرباح الخاضعة للضريبة، على النحو الآتى:
1 - نسبة (50%) خصما من التكاليف الاستثمارية للقطاع (أ):
ويشمل المناطق الجغرافية الأكثر احتياجا للتنمية طبقا للخريطة الاستثمارية وبناء على البيانات والإحصاءات الصادرة من الجهاز المركزى للتعبئة العامة والإحصاء، المعتمدة بالخطة العامة للتنمية الاقتصادية والاجتماعية ووفقا لتوزيع أنشطة الاستثمار بها على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.
2 - نسبة (30%) خصما من التكاليف الاستثمارية للقطاع (ب):
ويشمل باقى أنحاء الجمهورية وفقا لتوزيع أنشطة الاستثمار، وذلك للمشروعات الاستثمارية الآتية:
المشروعات كثيفة الاستخدام للعمالة وفقا للضوابط المنصوص عليها فى اللائحة التنفيذية لهذا القانون.
المشروعات المتوسطة والصغيرة.
المشروعات التى تعتمد على الطاقة المتجددة أو تنتجها.
المشروعات القومية والاستراتيجية التى يصدر بتحديدها قرار من المجلس الأعلى.
المشروعات السياحية التى يصدر بتحديدها قرار من المجلس الأعلى.
مشروعات إنتاج الكهرباء، وتوزيعها التى يصدر بتحديدها قرار من رئيس مجلس الوزراء بناء على عرض مشترك من الوزير المختص والوزير المعنى بشئون الكهرباء ووزير المالية.
المشروعات التى يصدر إنتاجها إلى خارج الإقليم الجغرافى لجمهورية مصر العربية.
صناعة السيارات والصناعات المغذية لها.
الصناعات الخشبية والأثاث والطباعة والتغليف والصناعات الكيماوية.
صناعات المضادات الحيوية وأدوية الأورام ومستحضرات التجميل.
الصناعات الغذائية والحاصلات الزراعية وتدوير المخلفات الزراعية.
الصناعات الهندسية والمعدنية والنسيجية والجلود.
وفى جميع الاحوال يجب ألا يجاوز الحافز الاستثمارى (80%) من رأس المال المدفوع حتى تاريخ بدء مزاولة النشاط وذلك وفقا لأحكام قانون الضريبة على الدخل الصادر بالقانون رقم 91 لسنة 2005.
كما يجب الاتزيد مدة الخصم على سبع سنوات من تاريخ بدء مزاولة النشاط.
ويصدر رئيس مجلس الوزراء قرارا بناء على عرض مشترك من الوزير المختص ووزير المالية والوزير المعنى، بتحديد توزيع القطاعات الفرعية لأنشطة الاستثمار بالقطاعين (أ)، و (ب) المشار إليهما.
وتبين اللائحة التنفيذية لهذا القانون مفهوم التكلفة الاستثمارية، والنطاق الجغرافى للقطاعين (أ) و (ب)، وشروط منح الحوافز الخاصة وضوابطه، وتدرج بها أنشطة الاستثمار الفرعية التى يتضمنها قرار رئيس مجلس الوزراء المشا إلية فور صدوره.
وتجوز إضافة أنشطة جديدة للتمتع بالحوافز الخاصة بقرار من المجلس الأعلى.
*البند (1) معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'94de46e68bcd70f64f2238bb6887604f',DATE '2023-07-26',NULL,'active',160,2023,$m229$البند (1) معدلة بوجب قانون رقم 160 لسنة 2023. نصه قبل التعديل كما ورد فى المصدر: «1 - نسبة (50%) خصما من التكاليف الاستثمارية للقطاع (أ):
ويشمل المناطق الجغرافية الأكثر احتياجا للتنمية طبقا للخريطة الاستثمارية وبناء على البيانات والإحصاءات الصادرة من الجهاز المركزى للتعبئة العامة والاحصاء، ووفقا لتوزيع أنشطة الاستثمار بها على النحو الذى تبنية اللائحة التنفيذية لهذا القانون.» تاريخ النفاذ المسجل: تاريخ العمل بـالقانون 160 لسنة 2023 (إصدار 25/7/2023؛ العمل به 26/7/2023).$m229$),
(11,1,1,$m229$مع عدم الإخلال بالحوافز والمزايا والإعفاءات المنصوص عليها فى هذا الفصل، تمنح المشروعات الاستثمارية التي تزاول أحد الأنشطة الصناعية التي يتم تحديدها وفقا لهذه المادة، وتوسعاتها وفقا لحكم الفقرة الأخيرة من المادة (12) من هذا القانون، حافزا استثماريا نقديا لا يقل عن نسبة (35%) ولا يجاوز نسبة (55%) من قيمة الضريبة المسددة مع الإقرار الضريبي على الدخل المتحقق من مباشرة النشاط فى المشروع الاستثمارى، أو توسعاته بحسب الأحوال، وتلتزم وزارة المالية بصرف الحافز خلال خمسة وأربعين يوما من نهاية الأجل المحدد لتقديم الإقرار الضريبى، وإلا استحق عليها مقابل تأخير يحسب على أساس سعر الائتمان والخصم المعلن من البنك المركزي فى الأول من يناير السابق على تاريخ استحقاق الحافز مع استبعاد كسور الشهر والجنيه، ولا يعد هذا الحافز دخلا خاضعا للضريبة.
ويشترط لمنح الحافز المنصوص عليه فى هذه المادة أن يعتمد المشروع، أو توسعاته، بحسب الأحوال، فى تمويله حتى تاريخ بدء مزاولة النشاط، على النقد الأجنبي من الخارج بنسبة (50%) على الأقل من أمواله، وأن يبدأ مزاولة النشاط خلال ست سنوات من تاريخ العمل بهذه المادة، ويجوز مد هذه المدة بحد أقصى ست سنوات بقرار من مجلس الوزراء، بناء على عرض مشترك من الوزير المختص والوزير المعنى بشئون الصناعة ووزير المالية.
ويصدر مجلس الوزراء، بناء على عرض مشترك من الوزير المختص والوزير المعنى بشئون الصناعة ووزير المالية، قرارا يتضمن الصناعات والمناطق التى تتمتع بالحافز المنصوص عليه فى هذه المادة، ومدد منح الحافز لكل منها بما لا يجاوز عشر سنوات، وكذا شروط وقواعد وفئات منح الحافز وآليات صرفه.
*مضافة بوجب قانون رقم 160 لسنة 2023.$m229$,'c06e5468f6de3b8182c83c1fd4673d4e',DATE '2023-07-26',NULL,'active',160,2023,$m229$مضافة بوجب قانون رقم 160 لسنة 2023. تاريخ النفاذ المسجل: تاريخ العمل بـالقانون 160 لسنة 2023 (إصدار 25/7/2023؛ العمل به 26/7/2023).$m229$),
(12,0,1,$m229$يشترط لتمتع المشروعات الاستثمارية بالحوافز الخاصة المنصوص عليها فى المادة (11) من هذا القانون، توافر الشروط الآتية:
1 - أن يتم تأسيس شركة أو منشأة جديدة لإقامة المشروع الاستثمارى.
2 - أن تؤسس الشركة أو المنشأة خلال مدة أقصاها ثلاث سنوات من تاريخ العمل باللائحة التنفيذية لهذا القانون، ويجوز بقرار من مجلس الوزراء، بناء على عرض الوزير المختص، مد هذه المدة لمدد أخرى لا يجاوز مجموعها تسع سنوات.
3 - أن تمسك الشركة أو المنشأة حسابات منتظمة، وإذا كانت الشركة أو المنشأة تعمل فى أكثر من منطقة فلها أن تستفيد بالنسبة المقررة لكل منطقة بشرط أن يكون لكل منطقة حسابات مستقلة.
4 - ألا يكون أى من المساهمين أو الشركاء أو أصحاب المنشآت قد قدم أو ساهم أو استخدم فى إنشاء أو تأسيس أو إقامة المشروع الاستثمارى المتمتع بالحافز أيا من الأصول المادية لشركة أو منشأة قائمة وقت العمل بأحكام هذا القانون أو قام بتصفية تلك الشركة أو المنشأة خلال المدة المبينة بالبند (2) من هذه المادة بغرض إنشاء مشروع استثمارى جديد يتمتع بالحوافز الخاصة المشار إليها، ويترتب على مخالفة ذلك سقوط التمتع بالحافز المشار إليه والتزام الشركة أو المنشأة بسداد جميع المستحقات الضريبية.
ويجوز أن تتمتع توسعات المشروعات الاستثمارية القائمة بالفعل بالحوافز المنصوص عليها فى المادتين (11)، (13) من هذا القانون، ويقصد بالتوسعات فى حكم هذه المادة زيادة رأس المال المستخدم بإضافة أصول جديدة تؤدى إلى زيادة الطاقة الإنتاجية للمشروع، وذلك كله طبقا للقواعد والشروط التى يصدر بتحديدها قرار من مجلس الوزراء.
*البند (2) معدلة بوجب قانون رقم 160 لسنة 2023.
*الفقرة الأخيرة مضافة بموجب قانون رقم 141 لسنة 2019.$m229$,'eaaf9123b1455f35344adcfd5cd680fd',DATE '2023-07-26',NULL,'active',160,2023,$m229$البند (2) معدلة بوجب قانون رقم 160 لسنة 2023. نصه قبل التعديل كما ورد فى المصدر: «2 - أن تؤسس الشركة أو المنشأة خلال مدة اقصاها ثلاث سنوات من تاريخ العمل باللائحة التنفيذية لهذا القانون، ويجوز بقرار من مجلس الوزراء وبناء على عرض الوزير المختص مد هذه المدة لمرة واحدة.» | الفقرة الأخيرة مضافة بموجب قانون رقم 141 لسنة 2019. تاريخ النفاذ المسجل: تاريخ العمل بـالقانون 160 لسنة 2023 (إصدار 25/7/2023؛ العمل به 26/7/2023).$m229$),
(13,0,1,$m229$مع عدم الإخلال بالحوافز والمزايا والإعفاءات المنصوص عليها فى هذا الفصل، يجوز بقرار من مجلس الوزراء منح حوافز إضافية للمشروعات المنصوص عليها فى المادة (11) من هذا القانون وذلك على النحو التالى:
1 - السماح بإنشاء منافذ جمركية خاصة لصادرات المشروع الاستثمارى أو وارداته بالاتفاق مع وزير المالية.
2 - تحمل الدولة قيمة ما يتكلفه المستثمر لتوصيل المرافق إلى العقار المخصص للمشروع الاستثمارى أو جزء منها، وذلك بعد تشغيل المشروع.
3 - تحمل الدولة لجزء من تكلفة التدريب الفنى للعاملين.
4 - رد نصف قيمة الأرض المخصصة للمشروعات الصناعية فى حالة بدء الإنتاج خلال عامين من تاريخ تسليم الأرض.
5 - تخصيص أراض بالمجان لبعض الأنشطة الاستراتيجية وفقا للضوابط المقررة قانونا فى هذا الشأن.
كما يجوز بقرار من مجلس الوزراء بناء على عرض الوزير المختص استحداث حوافز أخرى غير ضريبية كلما دعت الحاجة إلى ذلك.
وتبين اللائحة التنفيذية قواعد منح الحوافز الإضافية المقررة فى هذه المادة وضوابطه وشروطه.$m229$,'46ded1071c32ed8ec0f33b26cd5d1ef3',DATE '2017-06-01',DATE '2023-07-25','amended',160,2023,$m229$النص قبل التعديل بالقانون رقم 160 لسنة 2023 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»). تاريخ بدء نفاذ النص الأصلى مسجل تقريباً (اليوم التالى لتاريخ إصدار القانون 31/5/2017 على افتراض نشره فى يوم إصداره).$m229$),
(13,0,2,$m229$مع عدم الإخلال بالحوافز والمزايا والإعفاءات المنصوص عليها فى هذا الفصل، يجوز بقرار من مجلس الوزراء منح حوافز إضافية للمشروعات المنصوص عليها فى المادتين (11 و 11 مكررا) من هذا القانون، وذلك على النحو الآتى:
1 - السماح بإنشاء منافذ جمركية خاصة لصادرات المشروع الاستثماري أو وارداته بالاتفاق مع وزير المالية.
2 - تحمل الدولة قيمة ما يتكلفه المستثمر لتوصيل المرافق إلى العقار المخصص للمشروع الاستثماري أو جزءا منها، وذلك بعد تشغيل المشروع.
3 - تحمل الدولة جزءا من تكلفة التدريب الفني للعاملين.
4 - رد نصف قيمة الأرض المخصصة للمشروعات الصناعية فى حالة بدء الإنتاج خلال عامين من تاريخ تسليم الأرض.
5 - تخصيص أراض بالمجان لبعض الأنشطة الاستراتيجية وفقا للضوابط المقررة قانونا فى هذا الشأن.
6 - الإعفاء من مقابل الانتفاع بالأراضى المخصصة لإقامة المشروع لمدة عشر سنوات كحد أقصى تبدأ من بداية التشغيل، وذلك بناء على عرض الوزير المختص.
ويجوز بقرار من رئيس مجلس الوزراء بناء على عرض الوزير المختص، إعفاء المشروعات المشار إليها فى المادتين (11 و 11 مكررا) من المساهمة فى تكاليف إنشاء البنية الأساسية والخدمات والمرافق العامة بنسبة لا تجاوز (50%) منها، وفقا للضوابط التي يصدر بتحديدها قرار من المجلس الأعلى.
ويجوز أن تتحمل الخزانة العامة نسبة لا تزيد على (50%) من مقابل استهلاك المشروع للمرافق الأساسية لمدة عشر سنوات كحد أقصى، وذلك وفقا للضوابط التي يصدر بتحديدها قرار من المجلس الأعلى.
كما يجوز بقرار من مجلس الوزراء بناء على عرض الوزير المختص استحداث حوافز أخرى غير ضريبية كلما دعت الحاجة إلى ذلك.
وتبين اللائحة التنفيذية لهذا القانون قواعد منح الحوافز الإضافية المقررة فى هذه المادة وضوابطه وشروطه.
*معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'96d426dc6405255096af7ddace4f5258',DATE '2023-07-26',NULL,'active',160,2023,$m229$عدلت بالقانون رقم 160 لسنة 2023 (إصدار 25/7/2023؛ العمل به 26/7/2023).$m229$),
(14,0,1,$m229$يختص الرئيس التنفيذى للهيئة أو من يفوضه بإصدار الشهادة اللازمة للتمتع بالحوافز المنصوص فى المواد (10، 11، 13) للشركات والمنشآت الخاصة لأحكام هذا القانون.
وتعتبر هذه الشهادة نهائية ونافذة بذاتها دون حاجة إلى موافقة جهات أخرى ويتعين على جميع الجهات العمل بموجبها والالتزام بما ورد بها من بيانات.$m229$,'9ad326f2fb6c1d2168383bcb94746c7e',DATE '2017-06-01',DATE '2023-07-25','amended',160,2023,$m229$النص قبل التعديل بالقانون رقم 160 لسنة 2023 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»). تاريخ بدء نفاذ النص الأصلى مسجل تقريباً (اليوم التالى لتاريخ إصدار القانون 31/5/2017 على افتراض نشره فى يوم إصداره).$m229$),
(14,0,2,$m229$يختص الرئيس التنفيذى للهيئة أو من يفوضه بإصدار الشهادة اللازمة للتمتع بالحوافز المنصوص عليها فى المواد (10، 11، 11 مكررا، 13) من هذا القانون للشركات والمنشآت الخاضعة لأحكامه.
وتعتبر هذه الشهادة نهائية ونافذة بذاتها دون حاجة إلى موافقة جهات أخرى ويتعين على جميع الجهات العمل بموجبها والالتزام بما ورد بها من بيانات.
*الفقرة الأولى معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'414e8d8ee888223de96342b1c1b581ac',DATE '2023-07-26',NULL,'active',160,2023,$m229$عدلت بالقانون رقم 160 لسنة 2023 (إصدار 25/7/2023؛ العمل به 26/7/2023).$m229$),
(15,0,1,$m229$يحوز للمستثمر تحقيقا لأهداف التنمية الشاملة والمستدامة تخصيص نسبة من أرباحه السنوية لاستخدامها فى إنشاء نظام للتنمية المجتمعية، خارج مشروعه الاستثمارى، من خلال مشاركته فى كل المجالات الآتية أو بعضها:
1 - اتخاذ التدابير اللازمة لحماية البيئة وتحسينها.
2 - تقديم خدمات أو برامج فى مجالات الرعاية الصحية أو الاجتماعية أو الثقافية أو فى إحدى مجالات التنمية الأخرى.
3 - دعم التعليم الفنى أو تمويل البحوث والدراسات وحملات التوعية التى تستهدف تطوير الإنتاج وتحسينه بالاتفاق مع إحدى الجامعات أو مؤسسات البحث العلمى.
4 - التدريب والبحث العلمى.
ويعد ما ينفقه المستثمر من مبالغ فى إحدى المجالات المنصوص عليها فى الفقرة السابقة بما لا يجاوز نسبة (10%) من أرباحه السنوية الصافية من التكاليف والمصروفات واجبة الخصم وفقا لنص المادة (23) (بند 8) من قانون الضريبة على الدخل الصادر بالقانون رقم 91 لسنة 2005.
ويجوز للوزير المختص بالتنسيق مع الوزارات المعنية إنشاء قائمة لأفضل المشروعات الاستثمارية التى تقوم بأنشطة تنمية مجتمعية سواء من الناحية الجغرافية أو القطاعية أو غيرها ويعلن عنه للرأى العام.
وفى جميع الأحوال يحظر استخدام المشروعات أو البرامج أو الخدمات المقدمة بنظام المسئولية المجتمعية لتحقيق أغراض سياسية أو حزبية أو دينية أو تنطوى على تمييز بين المواطنين.
وتبين اللائحة التنفيذية للقانون ما يلزم من ضوابط وقواعد أخرى لتطبيق نظام المسئولية المجتمعية.$m229$,'5b259aa84f0c495e8f7695bdbc88a527',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(16,0,1,$m229$تقترح الوزارة المختصة الخطة الاستثمارية، وتتضمن هذه الخطة وضع السياسات الاستثمارية موضع التطبيق، وأولويات مشروعات الاستثمار المستهدفة بما يتفق مع السياسة العامة للدولة وخطة التنمية الاقتصادية والاجتماعية، ونظم الاستثمار المطبقة، ويتم إقرارها من المجلس الأعلى.$m229$,'0f42c6a2a2a6a5a014c3a5d2a846336d',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(17,0,1,$m229$تتضمن الخطة الاستثمارية وضع خريطة استثمارية تحدد نوعية ونظام الاستثمار، ومناطقه الجغرافية وقطاعاته، كما تحدد العقارات المملوكة للدولة أو للأشخاص الاعتبارية العامة الأخرى المعدة للاستثمار، ونظام التصرف فيها وطريقته بحسب نوع النظام الاستثمارى.
وتعد الهيئة مشروع الخريطة الاستثمارية بالتنسيق والتعاون الكامل مع جميع أجهزة الدولة المعنية.
ويجب مراجعة كل من الخطة والخريطة الاستثمارية مرة على الأقل كل ثلاث سنوات، وكلما دعت الحاجة لذلك بناء على اقتراح الهيئة.$m229$,'2f874ee0ffc9f301ef4cd7ab02650d92',DATE '2017-06-01',DATE '2023-07-25','amended',160,2023,$m229$النص قبل التعديل بالقانون رقم 160 لسنة 2023 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»). تاريخ بدء نفاذ النص الأصلى مسجل تقريباً (اليوم التالى لتاريخ إصدار القانون 31/5/2017 على افتراض نشره فى يوم إصداره).$m229$),
(17,0,2,$m229$تتضمن الخطة الاستثمارية وضع خريطة استثمارية تحدد نوعية، ونظام الاستثمار، وتعد الهيئة مشروع هذه الخريطة بالتنسيق والتعاون الكامل مع جميع أجهزة الدولة المعنية.
ويجب أن تشتمل الخريطة الاستثمارية على جميع البيانات والمعلومات اللازمة، وعلى الأخص طبيعة العقار وموقعه الجغرافي، النشاط، القطاع، التسعير، نظام التصرف، المرافق، المزايا والحوافز الممنوحة للنشاط، الضمانات، حجم السوق المستهدف، حوافز التصدير، الموافقات والتصاريح والتراخيص المطلوبة لمزاولة النشاط، الجهات المختصة بنشاط المشروع، المدد المقررة لاستخراجها، الرسوم ومقابل الخدمات المستحقة لحساب الجهات المختصة نظير هذه الموافقات أو التصاريح أو التراخيص وتقديم الخدمات، وتلتزم جميع جهات الولاية والجهات المعنية بنشاط المشروع، كل فى نطاق اختصاصه، بتزويد الهيئة بجميع البيانات اللازمة لإعداد هذه الخريطة.
ويجب مراجعة كل من الخطة والخريطة الاستثمارية مرة على الأقل كل ثلاث سنوات، وكلما دعت الحاجة لذلك بناء على اقتراح الهيئة.
*معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'b17786e6d83aaadb2961f8dd19d3124f',DATE '2023-07-26',NULL,'active',160,2023,$m229$عدلت بالقانون رقم 160 لسنة 2023 (إصدار 25/7/2023؛ العمل به 26/7/2023).$m229$),
(18,0,1,$m229$تكون الإجراءات والمدد المنصوص عليها فى هذا القانون واجبة التطبيق عند الحصول على خدمات الاستثمار، دون أن يخل ذلك بتطبيق أى قوانين أو إجراءات تتيح للمستثمر الحصول على الموافقات أو التصاريح أو التراخيص بإجراءات أيسر أو خلال مدد زمنية أقل من المنصوص عليها فى هذا القانون ولائحته التنفيذية.$m229$,'fd239826aa9383160af7a6535e6fad33',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(19,0,1,$m229$تصدر الهيئة خلال تسعين يوما من تاريخ العمل بهذا القانون وبعد التنسيق مع الجهات المختصة، دليلا يتضمن الشروط والإجراءات والمواعيد المقررة لتخصيص العقارات وإصدار الموافقات والتصاريح والتراخيص المتعلقة بالأنشطة الاستثمارية الخاضعة لأحكام هذا القانون، ويتاح هذا الدليل من خلال الموقع الإليكترونى للهيئة ومطبوعاتها المختلفة وغيرها من الجهات.
وتلتزم الهيئة بمراجعة هذا الدليل وتحديثه دوريا، وكلما دعت الحاجة إلى ذلك، فى ضوء التعديلات التى تطرأ على التشريعات السارية فى الدولة.
كما تلتزم الجهات المختلفة بموافاة الهيئة خلال ستين يوما علي الاكثر من تاريخ العمل بهذا القانون بجميع البيانات والمستندات والنماذج اللازمة لاعداد هذا الدليل.
وتحدد اللائحة التنفيذية لهذا القانون الضوابط الازمة في هذا الشأن.$m229$,'785a647ffd3e852a02489db41d3f3b5b',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(20,0,1,$m229$يجوز بقرار من مجلس الوزراء منح الشركات التي تؤسس لإقامة مشروعات استراتيجية أو قومية تسهم في تحقيق التنمية أو مشروعات المشاركة بين القطاع الخاص والدولة أو القطاع العام أو قطاع الأعمال العام في أنشطة المرافق العامة والبنية التحتية أو الطاقة الجديدة والمتجددة أو الطرق والمواصلات أو المواني، موافقة واحدة علي اقامة المشروع وتشغيله وادارته بما في ذلك تراخيص البناء، وتخصيص العقارات اللازمة له، وتكون هذه الموافقة نافذة بذاتها دون حاجة الي اتخاذ أي اجراء اخر.
كما يجوز أن تتضمن هذه الموافقة سريان أحد الحوافز الواردة بهذا القانون علي المشروع أو اكثر، وتبين اللائحة التنفيذية لهذا القانون شروط و إجراءات استخراج هذه الموافقة.$m229$,'7b1b276ced892947f7f19d5f75fe8ceb',DATE '2017-06-01',DATE '2023-07-25','amended',160,2023,$m229$النص قبل التعديل بالقانون رقم 160 لسنة 2023 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»). تاريخ بدء نفاذ النص الأصلى مسجل تقريباً (اليوم التالى لتاريخ إصدار القانون 31/5/2017 على افتراض نشره فى يوم إصداره).$m229$),
(20,0,2,$m229$مع عدم الإخلال بأحكام المادة (23) من هذا القانون، يجوز بقرار من مجلس الوزراء منح الشركات، أيا كان شكلها القانونى، القائمة أو التى تؤسس لإقامة مشروعات استثمارية جديدة، أو مشروعات استراتيجية أو قومية تسهم فى تحقيق التنمية فى المجالات وبالمعايير التى يصدر بتحديدها قرار من مجلس الوزراء، أو مشروعات المشاركة بين القطاع الخاص والدولة أو القطاع العام أو قطاع الأعمال العام فى أنشطة المرافق العامة والبنية التحتية أو الطاقة الجديدة والمتجددة أو الطرق والمواصلات أو الموانئ، موافقة واحدة على إقامة المشروع وتشغيله وإدارته بما فى ذلك تراخيص البناء، وتخصيص العقارات اللازمة له، وتكون هذه الموافقة نافذة بذاتها دون حاجة إلى اتخاذ أي إجراء آخر.
ويجوز أن تتضمن هذه الموافقة سريان حافز أو أكثر من الحوافز الواردة بهذا القانون على المشروع.
وتتولى الهيئة بمشاركة الجهات المختصة متابعة التزام الشركات المشار إليها فى الفقرة الأولى من هذه المادة باشتراطات وضوابط إقامة المشروع وتشغيله وإدارته وفقا للقوانين واللوائح المنظمة بمعرفة لجنة تشكل لهذا الغرض، وفى حالة مخالفة الشركة للاشتراطات والضوابط المشار إليها، وجب إنذارها بموجب خطاب مسجل مصحوب بعلم الوصول بالمخالفات المنسوبة إليها، وسماع أوجه دفاعها، وإعطاؤها مهلة مناسبة لإزالة أسباب المخالفة أو تصحيحها، فإذا انقضت هذه المهلة دون قيام الشركة بإزالتها أو تصحيحها، يجوز وقف تنفيذ أعمال المشروع أو نشاطه، أو وقف تمتعه بحافز أو أكثر من الحوافز المقررة له، وذلك بحسب جسامة المخالفة لمدة محددة لا تجاوز سنة، فإن استمرت ذات المخالفة، يجوز بقرار من مجلس الوزراء بناء على عرض مشترك من الوزير المختص والوزير المعنى إلغاء الموافقة الواحدة الصادرة للشركة.
وتبين اللائحة التنفيذية لهذا القانون شروط وضوابط وإجراءات تطبيق أحكام هذه المادة.
*معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'385376c717805a84abb6a77b98746921',DATE '2023-07-26',NULL,'active',160,2023,$m229$عدلت بالقانون رقم 160 لسنة 2023 (إصدار 25/7/2023؛ العمل به 26/7/2023).$m229$),
(21,0,1,$m229$تنشأ بالهيئة وفروعها، لتبسيط إجراءات الأستثمار وتيسيرها، وحدة إدارية تسمى (مركز خدمات المستثمرين).
ويتولى المركز تقديم خدمات تأسيس الشركات وإنشاء فروعها واعتماد محاضر مجالس الإدارة والجمعيات العامة وزيادة رأس المال وتغيير النشاط وأعمال التصفية وغيرها من المسائل المتصلة بالشركات.
كما يتولى المركز تلقى طلبات المستثمرين لإصدار الموافقات والتصاريح وتخصيص العقارات والتراخيص اللازمة بأنواعها لإنشاء المشروعات الإستثمارية أو إدارتها، والبت فيها طبقا للقوانين واللوائح خلال المواعيد المنصوص عليها فى هذا القانون.
وتقدم تدريجيا وفى أسرع وقت ممكن خدمات المركز بطريقة مميكنة وآلية وفقا لما تحدده اللائحة التنفيذية من خلال شبكات الربط الإلكترونى وغيرها من الوسائل الفنية اللازمة.
ويضم المركز ممثلين عن الجهات المختصة بحسب القوانين المنظمة، ويخضع ممثلو تلك الجهات لإشراف الهيئة خلال فترة وجودهم بمركز خدمات المستثمرين ويلتزمون بالقواعد والضوابط التى يضعها مجلس إدارة الهيئة لتنظيم عمل المركز.
واستثناء من أحكام أى قانون آخر، تنتقل الى ممثلى الجهات المختصة بموجب أحكام هذا القانون سلطة إصدار الموافقات والتصاريح والتراخيص، بحسب الاشتراطات الفنية الواردة بالقوانين المنظمة لها ودليل إجراءات الاستثمار الذى تصدره الهيئة، وكذا جميع الصلاحيات المقررة للسلطة المختصة فى مجال تخصيص العقارات وإعطاء الموافقات والتصاريح والتراخيص اللازمة لعمل المستثمر والاستثمار وفقا لاحكام هذا القانون.
ويحدد مجلس ادارة الهيئة الجهات الحكومية وشركات المرافق العامة التى يتكون منها مركز خدمات المستثمرين، ويقوم الرئيس التنفيذى للهيئة بالتنسيق مع تلك الجهات لتحديد العدد اللازم من العاملين الأصليين والاحتياطيين لتمثيلها فى المركز ودرجاتهم الوظيفية التى تسمح لهم باداء واجباتهم فى مركز خدمات المستثمرين، كما تحدد اللائحة التنفيذية ضوابط اختيار هؤلاء العاملين وطريقة إلحاقهم بالمركز.
وفى غير حالات تقديم شهادات الإعتماد المنصوص عليها فى المواد التالية يجب على ممثلى الجهات بمركز خدمات المستثمرين والموظفين المسئولين بالجهات الإدارية طلب استيفاء المستندات اللازمة لاستخراج الموافقات أو التصاريح أو التراخيص خلال يومى عمل من تاريخ تقديمهما إليهم، وإلا اعتبرت مستوفاة، ولا يجوز طلب أى مستندات إضافية من المستثمر بعد مرور تلك المدة.
وفى جميع الأحوال يكون من حق المستثمر أن يقوم باستيفاء الإشتراطات الفنية وغيرها من الاشتراطات والإجراءات اللازمة للاستثمار عن طريق مكاتب الاعتماد، أو باللجوء مباشرة الى الجهات المختصة أو من خلال ممثليها بمركز خدمات المستثمرين.$m229$,'65cbfda0f66be7c9018f3e871b5ecf6f',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(22,0,1,$m229$يجوز لطالب الاستثمار أو من ينوب عنه، أن يعهد الى مكاتب الاعتماد المرخص لها من الهيئة بفحص المستندات الخاصة بالحصول على الموافقات والتصاريح والتراخيص اللازمة لإنشاء المشروع الاستثمارى وتشغيله والتوسع فيه، لتحديد مدى استيفائه الاشتراطات الفنية والمالية اللازمة وغيرها من الاجراءات المنصوص عليها فى أحكام هذا القانون والقوانين المنظمة لمنح الموافقات والتصاريح والتراخيص.
وتلتزم مكاتب الاعتماد فى ممارسة عملها بقواعد المسئولية المهنية التى تحددها اللائحة التنفيذية، وعلى الأخص القواعد الآتية:
الالتزام بأحكام القوانين والقرارات ذات الصلة.
بذل العناية الواجبة فى الفحص والاستيفاء والاعتماد.
تجنب تعارض المصالح.
الحفاظ على سرية وخصوصية المعلومات المتعلقة بطالبى الاعتماد.
ويجوز أن تعمل مكاتب الاعتماد منفردة أو بالإشتراك مع مجموعة من مكاتب الاعتماد المتخصصة.
وتحدد اللائحة التنفيذية لهذا القانون الشكل القانونى لمكاتب الاعتماد.
ويصدر الترخيص لمكاتب الاعتماد التى يتوافر لديها الخبرة اللازمة لممارسة هذا النشاط وفقا للشروط والقواعد والاجراءات التى تحددها اللائحة التنفيذية لهذا القانون بما فى ذلك الالتزام بابرام وثيقة تأمين سنوية لتغطية المخاطر والأضرار الناتجة عما تقوم به هذه المكاتب من أنشطة وأسس تحدد مقابل الخدمات التى تقوم بتقديمها.
وينشأ بالهيئة سجل خاص تقيد فيه مكاتب الاعتماد المرخص لها توافى به الجهات الإدارية المختصة.
ويكون الترخيص لمكاتب الاعتماد مقابل رسم لا يجاوز عشرين ألف جنيه تحدد فئاته اللائحة التنفيذية، ويجدد الترخيص سنويا، ويسرى على تجديد الترخيص ذات الرسوم المقررة لمنح التراخيص.
وتصدر مكاتب الاعتماد للمستثمر وعلى مسئوليتها شهادة اعتماد صالحة لمدة عام، تتضمن بيان مدى استيفاء المشروع الاستثمارى كل شروطه أو بعضها طبقا للقوانين واللوائح المنظمة لإصدار الموافقات والتصاريح والتراخيص، على أن تقوم بارسال نسخة الى الجهة المختصة بالطريقة التى تبينها اللائحة التنفيذية لهذا القانون.
ولا يعتد بالشهادات التى تقدم بعد مضى عام من تاريخ صدورها.
وتكون هذه الشهادة مقبولة لدى الجهة المختصة وممثلها بمركز خدمات المستثمرين وغيرها من الجهات الإدارية، ولا يحول ذلك دون إبداء الجهة المختصة أو ممثلها اعتراضا مسببا على الشهادة المشار إليها، فى موعد غايته عشرة أيام عمل من تاريخ تقديمها، وفى حالة إنقضاء هذه المدة دون رد، اعتبر ذلك قبولا لطلب المستثمر يصدر به موافقة من الرئيس التنفيذى للهيئة، وذلك على النحو المنصوص عليه فى المادة (25) من هذا القانون.
وتعتبر هذه الشهادة محررا رسميا فى تطبيق أحكام قانون العقوبات.
ومع عدم الإخلال بالمسئولية المدنية أو الجنائية بحسب الأحوال، يترتب على إصدار هذه الشهادة على خلاف الحقيقة أو بالمخالفة للقواعد المنصوص عليها فى المادة (25) من هذا القانون، استحقاق قيمة التأمين وصرفها للمستفيدين منها وشطب المكتب الصادرة عنه من سجل القيد لدى الهيئة مدة لا تجاوز ثلاث سنوات بقرار من مجلس إدارة الهيئة وفى حالة تكرار ارتكاب المخالفة يكون الشطب نهائيا من السجل.
وذلك كله على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.$m229$,'a0e18cd7726f0aa7687006ac2ea1c0a8',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(23,0,1,$m229$يؤدى المستثمر للهيئة جميع الرسوم وغيرها من المبالغ التى تفرضها القوانين، لحساب الجهات التى تقدم خدمات الإستثمار.
وتستحق الهيئة مقابلا لما تؤديه للمستثمرين من خدمات فعلية، ويصدر مجلس إدارة الهيئة قرارا بتحديد فئات هذا المقابل والقواعد والشروط والإجراءات المنظمة لتحصيله.$m229$,'3c65e7f88e9230f9e4593caed270e67d',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(24,0,1,$m229$مع عدم الإخلال بالمدد المقررة للبت فى الطلب المرفق به شهادة من أحد مكاتب الاعتماد، تتولى الجهات المختصة فحص طلبات الاستثمار التى تقدم اليها من خلال مركز خدمات المستثمرين، والتأكد من مدى توافر الشروط اللازمة لقبولها على النحو المبين فى هذا القانون، ويجب البت فيها مدة لا تتجاوز ستين يوما من تاريخ تقديم الطلب مستوفيا جميع مستنداته، وفى حالة إنقضاء هذه المدة دون قرار منها، اعتبر ذلك قبولا لطلب المستثمر يصدر به موافقة من الرئيس التنفيذى للهئية وذلك على النحو المنصوص عليه فى المادة (25) من هذا القانون.
وفى جميع الأحوال، يجب إخطار مقدم الطلب بالقرار الصادر فى طلبه سواء بالموافقة أو الرفض، بموجب خطاب مسجل بعلم الوصول، خلال سبعة أيام من تاريخ إنقضاء المدة المنصوص عليها فى الفقرة الأولى من هذة المادة.
ولذوى الشأن التظلم من قرار الرفض أمام اللجنة المنصوص عليها فى المادة (83) من هذا القانون.$m229$,'21672cf832129b66c5f0aa127cecb5fd',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(25,0,1,$m229$يتولى الرئيس التنفيذى للهيئة إصدار الموافقات المنصوص عليها فى المادتين (22، 24) من هذا القانون على النموذجين المعدين لهذا الغرض، وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.$m229$,'bd0ad38b7e410109ed6eab3e5e5c4a2d',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(26,0,1,$m229$فى إطار خطة التنمية الاقتصادية للدولة أو لأغراض استكمال الخريطة الاستثمارية، يجور للهيئة استخراج الموافقات أو التصاريح أو التراخيص اللازمة لإقامة النشاط على قطع الأراضى المخصصة للاستثمار قبل تخصيصها للمستثمرين، وفى هذة الحالة تحصل قيمة الرسوم وغيرها من الاعباء المالية المستحقة لحساب الجهات المختصة نظير هذة الموافقات أو التصاريح أو التراخيص من المستثمر عند اتمام اجراءات تخصيص الأرض، ويتعين على هذه الجهات الالتزام بتيسير إجراءات منح تلك الموافقات أو التصاريح أو التراخيص وفقا للإجراءات والمواعيد التى تحددها اللائحة التنفيذية لهذا القانون.$m229$,'51c4ce22ad7f4096eb88ae18a4dc8486',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(27,0,1,$m229$يلتزم العاملون القائمون على تنفيذ أحكام هذا القانون، فى جميع الجهات المختصة ذات الصلة بمراعاة الأهداف والمبادئ والإجراءات والمواعيد الواردة به وبلائحته التنفيذية.
ويكون تيسير الاجراءات على المستثمرين وسرعة و إنجاز مصالحهم المشروعة، من المؤشرات الأساسية لقياس أداء هؤلاء العاملين وأحد سبل تحديد مسئوليتهم الوظيفية.$m229$,'c99ff47f4547cb4ed75e5081696bf9b3',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(28,0,1,$m229$يجوز بقرار من رئيس مجلس الوزراء بناء على اقتراح مجلس ادارة الهيئة وعرض الوزير المختص والوزير المعنى إنشاء مناطق استثمارية متخصصة فى مختلف مجالات الاستثمار بما فيها المناطق اللوجيستية والزراعية والصناعية، على أن يتضمن قرار إنشاء المنطقة موقعها وإحداثياتها وطبيعة الأنشطة التى تزوال فيها، والمدة التى يجب اتخاذ الإجراءات اللازمة لإنشاء المنطقة خلالها، بالإضافة الى أى شروط عامة ترتبط بمزاولة تلك الأنشطة.
وعلى المطور الذى يتولى أمر المنطقة الاستثمارية اتخاذ الاجراءات اللازمة نحو إنشائها وفقا للبرنامج الزمنى للتنفيذ المحدد بالترخيص وإلا اعتبر الترخيص كأن لم يكن.
ويجوز بقرار من رئيس مجلس الوزراء أو من يفوضه منح المرخص له مهلة إضافية فى ضوء المبررات المقدمة منه بعد موافقة مجلس إدارة الهيئة.
وتسرى على المشروعات العاملة داخل المناطق الاستثمارية، أحكام البابين الأول والثانى من هذا القانون، وذلك فيما لا يتعارض مع طبيعة العمل بأحكام هذا النظام.
كما تسرى عليها القواعد الخاصة بالسماح الجمركى المؤقت والدورباك الواردة بالقوانين واللوائح والقرارات المنظمة لذلك.
وتجوز إضافة أنشطة أخرى بقرار من رئيس مجلس الوزراء بناء على عرض الوزير المختص.$m229$,'35df450042e67ec1dded5094a4a14509',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(29,0,1,$m229$يكون لكل منطقة استثمارية مجلس إدارة يصدر بتشكيله قرار من الوزير المختص بالاتفاق مع الوزير المعنى بحسب نوع وتخصص المنطقة.
ويختص مجلس لإدارة المنطقة بوضع خطة عمل المنطقة والضوابط والمعايير اللازمة لممارسة النشاط، واعتمادها من مجلس إدارة الهيئة، كما يختص بالموافقة على إقامة المشروعات الاستثمارية داخل حدود المنطقة، كما يلتزم مجلس الادارة بتقديم تقارير ربع سنوية الى الهيئة وفقا لما تحدده اللائحة التنفيذية، ويرسل محاضر اجتماعات مجلس الإدارة لاعتمادها من الهيئة.
ولمجلس إدارة المنطقة أن يرخص لشركات من القطاع الخاص بتنمية تلك المناطق وإدارتها أو الترويج للاستثمار بها.
ويلتزم أعضاء مجلس الإدارة بالإفصاح عن جميع اموالهم، على أن يتم تقديم هذا الإفصاح ومراجعته سنويا من جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلى أو محتمل للمصالح، على أن يرفع بذلك تقرير الى المجلس الأعلى عن طريق الوزير المختص.$m229$,'ce93ae89f73df4b069458757866a5a3f',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(30,0,1,$m229$يكون للمنظمة الاستثمارية مكتب تنفيذى من العاملين بالهيئة يصدر بهم قرار من الرئيس التنفيذى للهيئة باعتماد من الوزير المختص، ويتولى المكتب تنفيذ قرارات مجلس إدارة المنطقة فيما يخص الموافقات والتصاريح والتراخيص اللازمة ومتابعة تنفيذها وإصدار تراخيص البناء للمشروعات داخل حدود المنطقة.
ويؤدى المستثمر للهئية مقابلا عن كل خدمة فعلية يقدمها المكتب التنفيذى بما لا يجاوز واحدا فى الألف من التكاليف الاستثمارية عن جميع الخدمات المقدمة، وذلك على النحو الذى تحدده اللائحة التنفيذية لهذا القانون.$m229$,'37fe2cb6df457c70c333ca5b391b4aae',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(31,0,1,$m229$يختص رئيس مجلس إدارة المنطقة، فضلا عما هو منوط به، بالترخيص للمشروعات داخل حدود المنطقة الاستثمارية بمزاولة نشاطها.
ويجب أن يتضمن الترخيص بيانا بالأغراض التى منح من اجلها ومدة سريانه ولا يجوز النزول عن الترخيص كليا أو جزئيا إلا بموافقة مجلس إدارة المنطقة الاستثمارية ويكون رفض منح الترخيص أو عدم الموافقة على النزول عنه بقرار مسبب، ولصاحب الشأن أن يتظلم منه الى اللجنة المنصوص عليها بالمادة (83) من هذا القانون.
ويكتفى بهذا الترخيص عند التعامل مع أجهزة الدولة المختلفة للحصول على الخدمات والتيسيرات والمزايا والإعفاءات للمشروع دون حاجة للقيد بالسجل الصناعى، ما لم يطلب المستثمر غير ذلك، مع إخطار الجهة المختصة بصورة من الترخيص لأغراض الحصر، ولا يجوز لأى جهة إدارية أخرى اتخاذ أى اجراءات داخل المناطق الاستثمارية أو المشروعات العاملة داخلها إلا بعد موافقة الهيئة.
ولا يتمتع المرخص له بالضمانات والحوافز والمزايا المنصوص عليها فى هذا القانون الا فى حدود الأغراض المبينة فى الترخيص.$m229$,'bfcdf55d050148add5c14a48c2f1c7f7',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(32,0,1,$m229$لرئيس مجلس الوزراء بناء على اقتراح مجلس إدارة الهيئة وبطلب من الوزير المعني بشئون الاتصالات وتكنولوجيات المعلومات الترخيص بإنشاء مناطق تكنولوجية في مجال صناعة تكنولوجيا المعلومات والاتصالات بما تشمله من أنشطة صناعية وتصميم وتطوير الإلكترونيات ومراكز البيانات وأنشطة التعهيد وتطوير البرمجيات والتعليم التكنولوجي وغيرها من الأنشطة المرتبطة بها أو المكملة لها وذلك كله وفقا لما تبينه اللائحة التنفيذية لهذا القانون.
وتجوز إضافة أنشطة أخرى بقرار من رئيس مجلس الوزراء بناء على عرض مشترك من الوزير المختص والوزير المعنى بشئون الاتصالات وتكنولوجيا المعلومات.
ولا تخضع جميع الأدوات والمهمات والآلات اللازمة لمزاوالة النشاط المرخص به للمشروعات المتواجدة داخل المناطق التكنولوجية بجميع أن واعها للضرائب والرسوم الجمركية، وفقا للشروط والإجراءات التي تبينها اللائحة التنفيذية.
وتتمتع المشروعات المقامة في المناطق التكنولوجية بالحوافز الخاصة المنصوص عليها في المادة (11) من هذا القانون بحسب القطاع المقامة به.
ويكون لكل منطقة مجلس إدارة يصدر بتشكيله قرار من الوزير المختص بشؤون الاتصالات وتكنولوجيا المعلومات بالاتفاق مع الوزير المختص، ويختص مجلس إدارة المنطقة بوضع الضوابط والمعايير اللازمة لممارسة النشاط، كما يختص بالموافقة على إقامة المشروعات داخل حدود المنطقة.
ويلتزم أعضاء مجلس الإدارة بالإفصاح عن جميع أموالهم، على أن يتم تقديم هذا الإفصاح ومراجعته سنويا من جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلي أو محتمل للمصالح، على أن يرفع بذلك تقرير إلى المجلس الأعلى عن طريق الوزير المختص.
وتسري على الاستثمار بنظام المناطق التكنولوجية أحكام البابين الأول والثاني من هذا القانون فيما لا يتعارض مع طبيعة العمل بهذا النظام.
وتبين اللائحة التنفيذية لهذا القانون اشتراطات وضوابط العمل فيها وأسلوب إدارتها.$m229$,'26f12cb6c668ed91f6fae1e907af87f7',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(33,0,1,$m229$يكون إنشاء المنطقة الحرة التي تشمل مدينة بأكملها بقانون.
ولمجلس الوزراء بناء على عرض الوزير المختص بعد موافقة مجلس إدارة الهيئة إنشاء مناطق حرة عامة لإقامة المشروعات التى يرخص بها، أيا كان شكلها القانوني، تهدف بالأساس إلى التصدير خارج البلاد، ويجب أن يتضمن القرار الصادر بإنشاء المنطقة الحرة بيانا بموقعها وحدودها.
ويتولى إدارة المنطقة الحرة العامة مجلس إدارة يصدر بتشكيله وتعيين رئيسه قرار من الرئيس التنفيذي للهيئة باعتماد من الوزير المختص، ويقوم أعضاء مجلس الإدارة بالإفصاح عن أموالهم، على أن يقدم ويراجع هذا الإفصاح سنويا من قبل جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلي أو محتمل للمصالح، على أن يرفع بذلك تقرير إلى المجلس الأعلى عن طريق الوزير المختص.
ويختص مجلس إدارة المنطقة الحرة العامة على الاخص باقتراح اللوائح والنظم اللازمة لإدارة المنطقة الحرة، واعتمادها من مجلس إدارة الهيئة، وتنفيذ أحكام هذا القانون ولائحته التنفيذية التي تصدرها الهيئة.
كما يجوز لمجلس الوزراء بناء على عرض الوزير المختص الموافقة على إنشاء مناطق حرة خاصة تقتصر كل منها على مشروع أو أكثر في أنشطة مماثلة متى اقتضت طبيعتها ذلك، وتنظم اللائحة التنفيذية سائر أوضاع العمل بالمناطق الحرة الخاصة بما يضمن حسن قيامها بأعمالها وحوكمتها.$m229$,'eb643f0504cfe176ac474b72c94abc9e',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(34,0,1,$m229$مع عدم الإخلال بأحكام القانون رقم 133 لسنة 2010 بالترخيص لمشروعات تكرير البترول بالعمل بنظام المناطق الحرة، ومع مراعاة المراكز القانونية للشركات المرخص لها بإقامة مشروعات بنظام المناطق الحرة القائمة وقت العمل بهذا القانون، لا يجوز الترخيص بإقامة مشروعات بنظام المناطق الحرة فى مجال تصنيع البترول، وصناعة الأسمدة، والحديد والصلب، وتصنيع وتسييل ونقل الغاز الطبيعي والصناعات كثيفة استخدام الطاقة التي يصدر بتحديدها قرار من المجلس الأعلى للطاقة، وصناعة الخمور والمواد الكحولية، وصناعات الأسلحة والذخائر والمتفجرات وغيرها مما يرتبط بالأمن القومي.$m229$,'ca0e6286c7f9c286dfad9b1ef1bac868',DATE '2017-06-01',DATE '2023-07-25','amended',160,2023,$m229$النص قبل التعديل بالقانون رقم 160 لسنة 2023 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»). تاريخ بدء نفاذ النص الأصلى مسجل تقريباً (اليوم التالى لتاريخ إصدار القانون 31/5/2017 على افتراض نشره فى يوم إصداره).$m229$),
(34,0,2,$m229$مع عدم الإخلال بأحكام القانون رقم 133 لسنة 2010 بالترخيص لمشروعات تكرير البترول بالعمل بنظام المناطق الحرة، ومع مراعاة المراكز القانونية للشركات المرخص لها بإقامة مشروعات بنظام المناطق الحرة القائمة وقت العمل بهذا القانون، يجوز بعد موافقة المجلس الأعلى للطاقة الترخيص بإقامة مشروعات بنظام المناطق الحرة فى مجال تصنيع البترول، وصناعات الأسمدة، والحديد والصلب، وتصنيع وتسييل ونقل الغاز الطبيعي والصناعات كثيفة استخدام الطاقة.
ولا يجوز الترخيص بإقامة مشروعات بنظام المناطق الحرة فى مجال صناعات الخمور والمواد الكحولية، وصناعات الأسلحة والذخائر والمتفجرات وغيرها مما يرتبط بالأمن القومى.
*معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'84f1a4eb9121d975ef9a10805ea686e4',DATE '2023-07-26',NULL,'active',160,2023,$m229$عدلت بالقانون رقم 160 لسنة 2023 (إصدار 25/7/2023؛ العمل به 26/7/2023).$m229$),
(35,0,1,$m229$مع عدم الإخلال بنص الفقرة الأولى من المادة (10) من هذا القانون، تخضع جميع المشروعات التي تستثمر بنظام المناطق الحرة للرقابة الجمركية والضريبية وفقا للقواعد التي يصدر بها قرار من مجلس إدارة الهيئة بالتنسيق مع مصلحتي الجمارك والضرائب المصرية.
ويلتزم مجلس إدارة المنطقة الحرة بإخطار الجهات التي يحددها الوزير المعنى بشئون الصناعة بجميع البيانات المتعلقة بالمشروعات الإنتاجية الصناعية التى تقام بالمناطق الحرة، ويكون للوزير المختص بالتفاق مع الوزير المعنى بشئون الصناعة وضع ضوابط مباشرة المشروعات الإنتاجية الصناعية لأنشطتها، وعلى الأخص ما تلتزم به هذه المشروعات من نسب تصديرية.$m229$,'acdc17fb11e4f57f55a7322684e8916f',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(36,0,1,$m229$مع مراعاة أحكام قانون سوق رأس المال الصادر بقانون رقم 95 لسنة 1992، وقانون البنك المركزى والجهاز المصرفي والنقد الصادر بالقانون رقم 88 لسنة 2003، والقانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية، يختص مجلس إدارة المنطقة الحرة العامة بالموافقة النهائية على إقامة المشروعات داخل المنطقة، أو في المنطقة الحرة الخاصة التي تقع في نطاقها الجغرافى، ويختص رئيس مجلس إدارة المنطقة بالترخيص لها بمزاولة نشاطها.
ويجب أن يتضمن الترخيص بيانا بالأغراض التي منح من اجلها و مدة سريانه ومقدار ونوع الضمان المالى الذي يؤديه المرخص له بما لا يجاوز اثنان بالمائة (2%) من التكاليف الاستثمارية وفقا للنسب التي تبينها اللائحة التنفيذية لهذا القانون، ولا يجوز النزول عن الترخيص كليا أو جزئيا، إلا بموافقة مجلس إدارة المنطقة.
ولا يتمتع المشروع المرخص له بالإعفاءات أو المزايا المنصوص عليها في القانون إلا في حدود الأغراض المبينة في الترخيص، ويكتفي بهذا الترخيص عند التعامل مع أجهزة الدولة المختلفة، للحصول على الخدمات والتيسيرات والمزايا للمشروع، دون حاجة للقيد بالسجل الصناعي، ما لم يتطلب المشروع ذلك، مع إخطار الجهة المختصة بصورة من هذا الترخيص لأغراض الحصر والإحصاء.$m229$,'0c50b0d89b880b2dc1fe7f16991e5993',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(37,0,1,$m229$يكون تخصيص العقارات اللازمة لإقامة المشروعات للعمل بنظام المناطق الحرة العامة بنظام الترخيص بالأنتفاع وفقا للقواعد والأحكام التي تبينها اللائحة التنفيذية لهذا القانون.
وعلى المستثمر التقدم لإدارة المنطقة خلال ثلاثين يوما من تاريخ إبلاغه بالموافقة على إقامة مشروعه لاستلام الأرض لتنفيذ المشروع و التوقيع على عقد الأنتفاع وسداد القيمة المقررة.
وتسقط الموافقة على المشروع إذا لم يقم المستثمر باتخاذ إجراءات جدية في تنفيذ المشروع خلال تسعين يوما من تاريخ إخطاره باستلام الأرض وفقا للشروط المتفق عليها في عقد الأنتفاع، ويجوز مد هذه الفترة لمدة اخرى في ضوء المبررات التي يقدمها المستثمر أو من يمثله ويقدرها مجلس إدارة المنطقة الحرة.
وتبين اللائحة التنفيذية لهذا القانون الضوابط والإجراءات اللازمة لتنفيذ هذه الأحكام.$m229$,'a64e4a2d0851ea1497f7cd9caf4486fe',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(38,0,1,$m229$يلتزم المستثمر بتسليم الأرض المخصصة له إلى إدارة المنطقة عند إلغاء المشروع أو سقوط الموافقة الصادرة له خالية من الإشغالات، وفي حالة وجود مبان أو منشآت أو موجودات بالموقع يلتزم بإخلائها على نفقته الخاصة خلال المدة التى يحددها مجلس إدارة المنطقة بما لا يجاوز ستة أشهر من تاريخ إخطاره بذلك بخطاب مسجل بعلم الوصول.
فإذا لم يقم بالإخلاء خلال هذه المدة، يصدر مجلس إدارة المنطقة قرارا باسترداد الأرض بالطريق الإدارى بما عليها من مبان وإنشاءات وتقوم إدارة المنطقة والجمارك فى حالة وجود موجودات بالموقع بجردها وحصرها وتسليمها إلى إدارة الجمارك للاحتفاظ بها مؤقتا أو بيعها وفقا لأحكام قانون الجمارك بشأن المهمل أو المتروك وإيداع ثمنها فى حساب لدى الهيئة لصالح المستثمر، بعد خصم مستحقات الهيئة ثم الديون الحكومية وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون، وتعتبر مستحقات الهيئة فى تطبيق أحكام هذه المادة من الديون الممتازة التالية للمصروفات القضائية ومستحقات الخزانة العامة.$m229$,'47da210900f7e8345681001b71a60d9e',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(39,0,1,$m229$مع مراعاة الأحكام التى تقررها القوانين واللوائح بشأن منع تداول بعض البضائع والمواد، لا تخضع البضائع التى تصدرها مشروعات المنطقة الحرة إلى خارج البلاد أو تستوردها من خارج البلاد لمزاولة نشاطها لقواعد الخاصة بالاستيراد والتصدير و للإجراءات الجمركية الخاصة بالصادرات والواردات، كما لا تخضع للضرائب الجمركية والضريبة على القيمة المضافة وغيرها من الضرائب والرسوم.
ويكون تصدير مستلزمات الإنتاج من السوق المحلى إلى المشروعات الإنتاجية بالمناطق الحرة وفقا للقواعد التى يصدر بها قرار من الوزير المعنى بشئون التجارة الخارجية بالاتفاق مع الوزير المختص ووزير المالية.
وفيما عدا سيارات الركوب تعفى الضرائب الجمركية والضريبة على القيمة المضافة وغيرها من الضرائب والرسوم، جميع الأدوات والمهمات والآلات ووسائل النقل الضرورية بجميع أنواعها واللازمة لمزاولة النشاط المرخص به للمشروعات الموجودة داخل المناطق الحرة بجميع أنواعها و لو اقتضت طبيعة مزاولة هذا النشاط وضروراتها خروجها مؤقتا من المنطقة الحرة إلى داخل البلاد وإعادتها إليها وذلك بالنسبة إلى الأدوات والمهمات والآلات وفى الحالات وبالضمانات والشروط والإجراءات التى يصدر بها قرار من مجلس الوزراء بناء على عرض الوزير المختص ووزير المالية.
وتبين اللائحة التنفيذية لهذا القانون إجراءات نقل البضائع وتأمينها من بدء تفريغها حتى وصولها إلى المناطق الحرة وبالعكس.
وللهيئة السماح بإدخال البضائع والمواد والأجزاء والخامات المحلية والأجنبية، المملوكة للمشروع أو للغير من داخل البلاد إلى المنطقة الحرة مؤقتا لإصلاحها أو لإجراء عمليات صناعية عليها وإعادته للداخل دون خضوعها لقواعد الاستيراد المطبقة وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.
وتحصل الضريبة الجمركية على قيمة الإصلاح وفقا لأحكام القوانين الجمركية.$m229$,'3c40c12f4cb5d0681a7a766866d966db',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(40,0,1,$m229$يكون الاستيراد من المناطق الحرة إلى داخل البلاد طبقا للقواعد العامة للاستيراد من الخارج.
واستثناء منذ ذلك يسمح بدخول المواد والنفايات والمخلفات الناتجة عن أنشطة المشروعات العاملة بالمناطق الحرة إلى داخل البلاد متى كان دخولها إلى البلاد بغرض التخلص منها أو إعادة تدويرها، وذلك بالطرق والوسائل الآمنة المقررة وفقا لقانون البيئة الصادر بالقانون رقم 4 لسنة 1994، على نفقة صاحب الشأن.
وتطبق أحكام قانون البيئة المشار إليه فى شأن حظر استيراد النفايات الخطرة من الخارج.
وتؤدى الضرائب الجمركية على البضائع التى تستورد من المنطقة الحرة الى السوق المحلى كما لو كانت مستوردة من خارج البلاد.
اما المنتجات المستوردة من مشروعات المناطق الحرة والتى تشمل على مكونات محلية وأخرى أجنبية، فيكون وعاء الضريبة الجمركية بالنسبة لها هو قيمة المكونات الأجنبية بالسعر السائد وقت خروجها من المنطقة الحرة إلى داخل البلاد، بشرط ألا تزيد الضريبة الجمركية المستحقة على المكونات الأجنبية على الضريبة المستحقة على المنتج النهائى المستورد من الخارج.
وتتمثل المكونات الاجنبية فى الاجزاء والمواد الأجنبية المستوردة حسب حالتها عند الدخول الى المناطق الحرة دون حساب تكاليف التشغيل بتلك المنطقة وتعتبر المنطقة الحرة فيما يتعلق بحساب النولون بلد المنشأ بالنسبة للمنتجات المصنعة فيها.$m229$,'a4c075d09bddce70823b9c5ae9c2955b',DATE '2017-06-01',DATE '2023-07-25','amended',160,2023,$m229$النص قبل التعديل بالقانون رقم 160 لسنة 2023 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»). تاريخ بدء نفاذ النص الأصلى مسجل تقريباً (اليوم التالى لتاريخ إصدار القانون 31/5/2017 على افتراض نشره فى يوم إصداره).$m229$),
(40,0,2,$m229$يكون الاستيراد من المناطق الحرة إلى داخل البلاد طبقا للقواعد العامة للاستيراد من الخارج.
واستثناء من ذلك، يسمح بدخول المواد والنفايات والمخلفات الناتجة عن أنشطة المشروعات العاملة بالمناطق الحرة إلى داخل البلاد متى كان دخولها إلى البلاد بغرض التخلص منها أو إعادة تدويرها على نفقة صاحب الشأن، وذلك بالطرق والوسائل الآمنة المقررة وفقا لقانونى البيئة الصادر بالقانون رقم 4 لسنة 1994، وتنظيم إدارة المخلفات الصادر بالقانون رقم 202 لسنة 2020
وتطبق أحكام قانون تنظيم إدارة المخلفات المشار إليه فى شأن حظر استيراد المخلفات الخطرة من الخارج، ولا يعد دخول المواد والنفايات والمخلفات الخطرة الناتجة عن أنشطة المشروعات العاملة بالمناطق الحرة إلى داخل البلاد بمثابة استيراد من الخارج فى حكم تطبيق هذه الفقرة.
وتؤدى الضرائب الجمركية على البضائع التى تستورد من المنطقة الحرة الى السوق المحلى كما لو كانت مستوردة من خارج البلاد.
اما المنتجات المستوردة من مشروعات المناطق الحرة والتى تشمل على مكونات محلية وأخرى أجنبية، فيكون وعاء الضريبة الجمركية بالنسبة لها هو قيمة المكونات الأجنبية بالسعر السائد وقت خروجها من المنطقة الحرة إلى داخل البلاد، بشرط ألا تزيد الضريبة الجمركية المستحقة على المكونات الأجنبية على الضريبة المستحقة على المنتج النهائى المستورد من الخارج.
وتتمثل المكونات الاجنبية فى الاجزاء والمواد الأجنبية المستوردة حسب حالتها عند الدخول الى المناطق الحرة دون حساب تكاليف التشغيل بتلك المنطقة وتعتبر المنطقة الحرة فيما يتعلق بحساب النولون بلد المنشأ بالنسبة للمنتجات المصنعة فيها.
*الفقرتان الثانية والثالثة معدلة بوجب قانون رقم 160 لسنة 2023.$m229$,'c3da9829ff7d9a2530523277a9ca3247',DATE '2023-07-26',NULL,'active',160,2023,$m229$عدلت بالقانون رقم 160 لسنة 2023 (إصدار 25/7/2023؛ العمل به 26/7/2023).$m229$),
(41,0,1,$m229$لا تخضع المشروعات داخل المناطق الحرة والأرباح التى توزعها لإحكام قوانين الضرائب والرسوم السارية فى مصر.
ومع ذلك تخضع هذه المشروعات للمعاملة الآتية:
أولا - تخضع المشروعات فى المناطق الحرة العامة:
1 - لرسم مقداره اثنان بالمائة (2%) من قيمة السلع عند الدخول (سيف) بالنسبة لمشروعات التخزين ولرسم مقداره واحد بالمائة (1%) من قمية السلع عند الخروج (فوب) بالنسبة لمشروعات التصنيع والتجميع، وتعفى من الرسم تجارة البضائع العابرة (ترانزيت) المحددة الوجهة.
2 - لرسم مقداره واحد بالمائة (1%) من إجمالى الإيرادات التى تحققها بالنسبة للمشروعات التى لا تقتضى نشاطها الرئيسى إدخال سلع أو إخراجها وذلك من واقع القوائم المالية المعتمدة من أحد المحاسبين القانونيين.
ثانيا - تخضع المشروعات فى المناطق الحرة الخاصة:
1 - لرسم مقداره واحد بالمائة (1%) من إجمالى الإيرادات التى تحققها بالنسبة لمشروعات التصنيع و التجميع عند تصدير السلع الى خارج البلاد، واثنان بالمائة (2%) من إجمالى ايرادات هذه المشروعات عند دخولها البلاد، وتعفى من الرسوم تجارة البضائع العابرة (ترانزيت) المحددة الوجهة.
2 - لرسم مقداره اثنان بالمائة %2 من إجمالى الإيرادات التى تحققها وذلك فيما بتعلق بغير ذلك من المشروعات الواردة بالبند السابق.
3 - وتئول حصيلة الرسوم الواردة بالبند أولا من هذه المادة الى الهيئة وتوزع حصيلة الرسوم الواردة بالبند (ثانيا) من هذه المادة مناصفة بين وزارة المالية والهيئة.
وفى جميع الأحوال تلتزم المشرعات المقامة فى المناطق الحرة العامة والخاصة بأداء مقابل سنوىا للخدمات للهيئة لا يجاوز مقداره (واحدا في الألف) (%.001) من رأس المال بحد أقصى مائة الف جنيه وفقا للنسب التى تبينها اللائحة التنفيذية لهذا القانون ويجوز أداء ما يعادل قيمتها بالعملة التى يحددها الوزير المختص.
كما تلتزم هذه المشروعات بتقديم القوائم المالية معتمدة من أحد المحاسبين القانونيين إلى كل من وزارتى المالية والاستثمار.$m229$,'7cafa7a303e530664a52361f25440e02',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(42,0,1,$m229$تعفى مشروعات النقل البحرى التى تنشأ فى المناطق الحرة من الشروط الخاصة بجنسية مالك السفينة والعاملين عليها المنصوص عليها فى القانون رقم 84 لسنة 1949، بشأن تسجيل السفن التجارية، وقانون التجارة البحرية الصادرة بالقانون رقم 8 لسنة 1990.
كما تستثنى السفن المملوكة لهذه المشروعات من أحكام القانون رقم 12 لسنة 1964 بإنشاء المؤسسة المصرية العامة للنقل البحرى.$m229$,'78c846356cc1e6c9d711202cc971a966',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(43,0,1,$m229$يلتزم المستثمر بالتأمين الشامل على المبانى والآلات والمعدات ضد جميع الحوادث، والمخاطر التى تنشأ من مزاولة النشاط المرخص به.
ولمجلس إدارة المنطقة إصدار قرار بإزالة منشآت المشروع فى حالة وقوع الحادث أو الخطر المؤمن ضده، ويجب أن يكون القرار مسببا ويعلن به المستثمر أو من يمثله خلال أسبوع من تاريخ صدوره بموجب خطاب مسجل مصحوبا بعلم الوصول ويجوز لإدارة المنطقة تقصير هذا الميعاد للضرورة.
وعلى المستثمر تنفيذ قرار الإزالة على نفقته وخلال الموعد الذى تحدده إدارة المنطقة ويكون لمجلس إدارة المنطقة فى حالة امتناع المستثمر عن التنفيذ وقف نشاط المشروع أو إلغاؤه، بحسب جسامة المخالفة.$m229$,'9ff88a8a552fb90a474642315af00ae3',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(44,0,1,$m229$فى جميع الأحوال التى ترد فيها الرسائل من الخارج و يفرج عنها من الجمارك برسم المناطق الحرة، يتم معاينتها بواسطة لجنة ثلاثية من المنطقة و الجمرك المختص وصاحب الشأن أو من ينيبه داخل مقر المشروع، ويحرر بيان بتوقيعهم موضحا به نتيجة المعاينة بعد المطابقة على الفواتير أو بيان العبوة، وتسلم الرسالة إلى صاحب الشأن وتصبح فى عهدته وتحت مسئوليته الكاملة، وتلتزم مصلحة الجمارك بتقدير قيمة هذه الرسالة وإبلاغ إدارة المنطقة بها.
وعلى مدير جمرك المنطقة إخطار رئيس المنطقة بحالات النقص أو الزيادة غير المبررة عما أدرج قائمة الشحن سواء فى عدد الطرود أو محتوياتها أو البضائع المحفوظة أو المنفرطة (الصب).
ويصدر بتنظيم المسئولية عن الحالات المنصوص عليها فى الفقرة السابقة وينسب التسامح فيها، قرار من مجلس إدارة الهيئة.$m229$,'cd0400525f3bbca74b83ac9df17fd8cb',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(45,0,1,$m229$لا تخضع المشروعات فى المناطق الحرة لأحكام القانون رقم 113 لسنة 1958 بشأن التعيين فى وظائف شركات المساهمة والمؤسسات العامة.
وتطبق احكام قانون العمل على علاقات العمل والسلامة والصحة المهنية بهذه المناطق، وتعد هذه الأحكام فيما تضمنته من حقوق للعمال حدا أدنى لما يجوز الاتفاق عليه فى عقود العمل الفردية أو الجماعية، التى تبرم مع العاملين فى المشروعات المرخص لها بالعمل فى هذه المناطق.
وتضع المشروعات فى المناطق الحرة لائحة داخلية بنظام العمل بها تكون ملزمة لها، وتقدمها للرئيس التنفيذى للهيئة أو من يفوضه للتصديق عليها، وتكون هذه اللائحة مكملة لعقود العمل الفردية أو الجماعية.
وللرئيس التنفيذى للهيئة الاعتراض على ما تضمنته اللائحة الداخلية من أحكام تخالف النظام العام أو إذا تضمنت مزايا أقل من المقررة فى قانون العمل.
وتسرى أحكام قانون التأمين الاجتماعى الصادر بالقانون رقم 79 لسنة 1975 على العاملين بالمشروعات التى تمارس نشاطها فى المناطق الحرة، وكذا قانون التأمين على أصحاب الأعمال ومن فى حكمهم الصادر بالقانون رقم 108 لسنة 1976.$m229$,'bd2f181074c5b9b32e5540c1018adbcf',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(46,0,1,$m229$لا يجوز لأى شخص أن يزاول مهنة أو حرفة فى المنطقة الحرة العامة لحسابه بصفة دائمة إلا بعد الحصول على تصريح بذلك من رئيس مجلس إدارة المنطقة طبقا للشروط والأوضاع التى تبينها اللائحة التنفيذية لهذا القانون وبعد سداد رسم سنوى لا يجاوز خمسة آلاف جنيه.
ويعاقب بغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرين ألف جنيه كل من يخالف حكم الفقرة الأولى من هذه المادة، ولا ترفع الدعوى الجنائية فى هذه الحالة إلا بإذن الوزير المختص، وفى جميع الأحوال تحظر إقامة المشروعات تزاول المهن الحرة والاستشارات فى المناطق الحرة، ويكون دخول المناطق الحرة وفقا للشروط التى يصدر بها قرار من مجلس إدارة الهيئة.$m229$,'4e2e9204376fec43b120af6bee47e063',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(47,0,1,$m229$تسرى على الاستثمار بنظام المناطق الحرة الأهداف، والمبادئ والضمانات، والمادة (11) من هذا القانون فيما لا يتعارض مع طبيعة العمل بهذا النظام.
ويجوز للمشروعات العاملة بهذا النظام التحول للعمل بنظام الاستثمار الداخلى، وتحدد اللائحة التنفيذية لهذا القانون شروط التحول وضوابطه والمعاملة الجمركية للمعدات والآلات وأجهزة الأنتاج وخطوطه وقطاع الغيار التى يقتضيها النشاط المرخص لها به.$m229$,'07ba6a94ceeaa8888a7ce7489dd01e51',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(48,0,1,$m229$مع مراعاة حكم المادة (71) من هذا القانون، تلتزم الهيئة بتقديم خدمات التأسيس وما بعد التأسيس ومركز خدمات المستثمرين للشركات الخاضعة لأحكام هذا القانون، وقانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981، وميكنتها وتوحيد إجراءاتها، وتسرى إجراءات التأسيس الإلكترونى دون غيرها فور تفعيلها بالهيئة، ولا تتقيد الهيئة فى ذلك بأى إجراءات منصوص عليها فى القوانين الأخرى.
وتحدد اللائحة التنفيذية لهذا القانون الأحكام المنظمة لنشر النظام الأساسى للشركة وإجراءات تعديله وضوابط العمل بنظام التأسيس الإلكترونى، والخدمات للشركات والمنشآت الخاضعة لأحكام هذا القانون، وقانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة المشار إليه.
وفى جميع الأحوال، يتعين التصديق على توقيعات الشركاء أو من ينوب عنهم، على عقود الشركات أيا كان نظام الاستثمار الخاضعة له مقابل رسم تصديق مقداره ربع فى المائة من قيمة رأس المال المدفوع بحد أقصى مقداره عشرة آلاف جنيه أو ما يعادله من النقد الأجنبى، بحسب الأحوال، سواء تم التصديق فى مصر أو لدى السلطات المصرية فى الخارج، وتسرى هذه الأحكام على كل تعديل فى نظام الشركة.
*الفقرة الأخيرة مضافة بموجب قانون رقم 141 لسنة 2019.$m229$,'e9ef9cb57cdfa21a40784b8b5bab6f3c',DATE '2019-08-01',NULL,'active',141,2019,$m229$الفقرة الأخيرة مضافة بموجب قانون رقم 141 لسنة 2019. تاريخ النفاذ المسجل: تاريخ العمل بـالقانون 141 لسنة 2019 (إصدار 31/7/2019؛ العمل به 1/8/2019).$m229$),
(49,0,1,$m229$يصدر بقرار من الوزير المختص نموذج عقد لكل نوع من أنواع الشركات ونظامها الأساسى بحسب الأحوال.
ويسدد طالب التأسيس، دفعة واحدة، للهيئة جميع ما تفرضه التشريعات من الرسوم المقررة وغيرها من المبالغ للجهات التى تقدم الخدمات المتصلة بالتأسيس، وما بعد التأسيس، وتحصل الهيئة هذه الرسوم لحساب تلك الجهات.
وتستحق الهيئة مقابلا لما تؤديه للمستثمرين من خدمات فعلية، ويصدر مجلس إدارة الهيئة قرارا بتحديد فئات هذا المقابل والقواعد والشروط والإجراءات المنظمة لتحصيله.$m229$,'99a7a1b73889699100014c285c5a91e9',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(50,0,1,$m229$تلتزم الجهات المختصة بتوفيق أوضاعها لتفعيل نظام الخدمات الإلكترونية لدى الهيئة، وذلك بموافاتها بجميع المستندات والنماذج والبيانات و ربط أنظمة العمل وقواعد البيانات لدى تلك الجهات بنظام الخدمات الإلكترونية بالهيئة وقاعدة بياناتها، وذلك خلال تسعين يوما من تاريخ العمل بأحكام هذا القانون.
كما تلتزم الجهات المختصة بالاعتداد بالتوقيعات الإلكترونية والمستندات والنماذج المعدة بإحدى الوسائل التكنولوجية، وقبول السداد الإلكترونى لجميع مدفوعاتها، وذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.$m229$,'903218ad11263402b9ddcde5c98035d9',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(51,0,1,$m229$تلتزم الهيئة بالبت فى طلب التأسيس خلال يوم عمل كامل على الأكثر بعد تقديمه مستوفيا، وتكتسب الشركة الشخصية الاعتبارية بمجرد قيدها فى السجل التجارى، ويصدر لها شهادة بالتأسيس، يحدد بياناتها قرار من الرئيس التنفيذى.
وعلى جميع الجهات المختصة والبنوك والجهات ذات الصلة كافة الاعتداد بهذه الشهادة كمستند رسمى فى تعاملاتها فور إصدارها.
وتلتزم الشركات التى يتم تأسيسها وفقا لأحكام هذا القانون بتقديم شهادة تفيد إيداع الأوراق المالية للشركة لدى شركة إيداع مركزى.
وتقوم الهيئة بوضع نظام يتيح إصدار شهادة للمشروع الاستثمارى، يصدر بتنظيمها قرار من الرئيس التنفيذى للهيئة.
كما يكون لكل منشأة أو شركة، أيا كان شكلها القانونى، رقم قومى موحد معتمد لجميع معاملات المستثمر مع أجهزة وجهات الدولة المختلفة كافة فور تفعيله.
وذلك كله وفقا لما تبنيه اللائحة التنفيذية لهذا القانون.$m229$,'d0054f1f69bfc95f46ff960aeff1ba9d',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(52,0,1,$m229$يجوز تحديد رأسمال الشركات الخاضعة لأحكام هذا القانون بأى عملة قابلة للتحويل وإعداد قوائمها المالية ونشرها بهذه العملة بشرط أن يكون الاكتتاب فى رأسمالها بذات العملة، وبالنسبة لشركات الأموال يتم سداد النسبة المحددة من رأس المال المدفوع وفقا لأحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشراكات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981.
كما يجوز تحويل مسمى رأسمال الشركات الخاضعة لأحكام هذا القانون من الجنيه المصرى إلى أى عملة قابلة للتحويل، وفقا لسعر الصرف المعلن من البنك المركزى فى تاريخ التحويل. وتحدد اللائحة التنفيذية لهذا القانون الضوابط المنظمة فى هذا الشأن.$m229$,'60c442370bf8c7f4b15299b479e4291a',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(53,0,1,$m229$استثناء من أحكام المادة (45) من قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981، يجوز تداول حصص التأسيس والأسهم لشركات الأموال الخاضعة لأحكام هذا القانون، خلال السنتين الماليتين الأوليين للشركة بموافقة الوزير المختص.$m229$,'8c2d7a3161682fa63271fa48ad373281',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(54,0,1,$m229$تلتزم الهيئة بإصدار القرارات التى تيسر على المستثمرين وتحقق سرعة تقديم الخدمات لهم فى كل ما تختص به من إجراءات، ويكون لها فى سبيل تحقيق ذلك، ودون التقيد بأى إجراءات منصوص عليها فى القوانين الأخرى، وضع الضوابط التى تكفل فصل تنظيم إجراءات الاستثمار عن الرقابة اللاحقة على الشركات، بما لا يخل بمبادئ الشفافية والحوكمة والإدارة الرشيدة والمسئولية، وذلك من خلال الآتى:
1 - تيسير جميع الإجراءات المتعلقة بالجمعيات العامة ومجالس إدارات الشركات والتصديق على محاضرها، بما فى ذلك استخدام سبل التكنولوجيا الحديثة، بما لا يجاوز خمسة عشر يوما من تاريخ تقديمها مستوفاة.
2 - الاستعاضة عن الدفاتر والمستندات بوسائل إلكترونية تتماشى مع التطور التكنولوجى.
3 - تطوير وتوحيد وتبسيط إجراءات زيادة أو تخفيض رأس المال ونظم التقييم المالى، وإجراءات التحقق مما إذا كانت القيم المحددة لها قد قدرت تقديرا صحيحا، وذلك دون الإخلال بالاختصاص المقرر قانونا للهيئة العامة للرقابة المالية.
وذلك كله وفقا لما تحدده اللائحة التنفيذية لهذا القانون.$m229$,'1f8e4acbb3dd295a8cec4a59bb598cfd',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(55,0,1,$m229$للمستثمر الحق فى الحصول على العقارات اللازمة لمباشرة نشاطه أو التوسع فيه، أيا كانت نسبة مشاركته أو مساهمته فى رأس المال، وذلك مع مراعاة القواعد الخاصة ببعض العقارات الواقعة فى المناطق الجغرافية التى تنظمها قوانين خاصة، وذلك إما من خلال الجهة صاحبة الولاية على العقارات وفقا للقواعد المنصوص عليها فى قوانينها و لوائحها بعد الإعلان عنها، أو من خلال الهيئة وفقا لأحكام التصرف المنصوص عليها فى هذا القانون.$m229$,'11961290829bffabb97f0af5a304a0ce',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(56,0,1,$m229$تلتزم الجهات الإدارية صاحبة الولاية بعد التنسيق مع جميع الجهات المختصة والمركز الوطنى لتخطيط استخدامات أراضى الدولة من خلال تسعين يوما من تاريخ العمل بهذا القانون، بموافاة الهيئة بخرائط تفصيلية محددا عليها جميع العقارات الخاضعة لولايتها والمتاحة للاستثمار، بالإضافة إلى قاعدة بيانات كاملة تتضمن الموقع والمساحة والارتفاعات المقررة والسعر التقديرى والأنشطة الاستثمارية الملائمة لطبيعتها وأسلوب التصرف فيها، كما تلتزم هذه الجهات بتحديث تلك البيانات دوريا كل ستة أشهر أو كلما طلبت الهيئة ذلك.
ويصدر رئيس الجمهورية بعد موافقة مجلس الوزراء قرارا بنقل الملكية أو الولاية أو الإشراف على بعض العقارات، من الجهات الإدارية صاحبة الولاية إلى الهيئة متى استلزم تنفيذ الخطة الاستثمارية ذلك، على أن تتولى الهيئة التصرف فيها وفقا لأحكام هذا القانون.$m229$,'690703c811962f950e82f1d7a4c0f7cc',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(57,0,1,$m229$يكون التصرف للمستثمرين فى العقارات المملوكة ملكية خاصة للدولة أو غيرها من الأشخاص الاعتبارية العامة بغرض الاستثمار طبقا للأحكام والضوابط والإجراءات المنصوص عليها فى هذا القانون بمراعاة الخطة الاستثمارية للدولة، وحجم المشروع الاستثمارى وطبيعة نشاطه، وقيمة الأموال المستثمرة فيه.
ولا تسرى على هذا التصرف أحكام قانون تنظيم المناقصات والمزايدات الصادر بالقانون رقم 89 لسنة 1998، إلا فيما لم يرد فى شأنه نص خاص فى هذا القانون وبما لا يتعارض مع أحكامه.
وعلى المستثمر الالتزام بالجدول الزمنى المقدم منه لتنفيذ المشروع الاستثمارى المعتمد من الجهة المختصة، ما دامت تلك الجهة قد أوفت بالتزاماتها تجاه المستثمر.
ولا يجوز للمستثمر ادخال تعديلات على المشروع الاستثمارى بتعديل غرضه أو توسعته أو زيادة حجمه أو غير ذلك من تعديلات إلا بعد موافقة الجهة المختصة كتابة على ذلك سواء كان ذلك مباشرة أو من خلال ممثلها بمركز خدمات المستثمرين.$m229$,'1fefd1b9fe5855fcef23a2d36a6b7e30',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(58,0,1,$m229$مع مراعاة حكم المادة (37) من هذا القانون، يجوز التصرف فى العقارات اللازمة للمشروعات الاستثمارية وفقا لأحكام هذا القانون بإحدى الصور الآتية: البيع، الإيجار، الإيجار المنتهى بالتملك، الترخيص بالأنتفاع.
ويكون ذلك إما على طلب المستثمر، أو دعوة أو إعلان من الهيئة وفقا لأحكام هذا القانون.
ويجوز للجهات الإدارية صاحبة الولاية على العقارات أن تشترك فى المشروعات الاستثمارية بتلك العقارات كحصة عينية أو بالمشاركة فى الأحوال التى يصدر بها قرار من مجلس الوزراء، وتبين اللائحة التنفيذية لهذا القانون أوضاع و إجراءات وكيفية اشتراك تلك الجهات بالعقارات فى المشروع الاستثمارى.$m229$,'f58529ec4ed4ae717d248d567b7f2045',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(59,0,1,$m229$فى الأحوال التى يطلب فى المستثمر توفير عقارات من أملاك الدولة الخاصة لإقامة مشروع استثمارى، يتعين أن يبين فى طلبه الغرض والمساحة والمكان الذى يرغب في إقامة المشروع عليه. وتتولى الهيئة عرض العقارات المتوفرة لديها أو لدى الجهات الإدارية صاحبة الولاية التى تلائم النشاط الاستثمارى لطالب الاستثمار وبيان طبيعة العقار، والاشتراطات المتعلقة بها، وبيان ما إذا كانت مزودة بالمرافق وصور التصرف فيها، ومقابل ذلك، وغيرها من الاشتراطات والبيانات اللازمة.$m229$,'78f4539705090ecec7207c5710e14ae6',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(60,0,1,$m229$يجوز لأغراض التنمية دون غيرها وطبقا للخريطة الاستثمارية، فى المناطق التى يصدر بتحديدها رئيس الجمهورية بعد موافقة مجلس الوزراء، التصرف دون مقابل فى العقارات المملوكة للدولة ملكية خاصة للمستثمرين الذين تتوافر فيهم الشروط الفنية والمالية التى يتم تحديدها بقرار من مجلس الوزراء، ويسرى ذلك على صور التصرف المنصوص عليها فى المادة (58) من هذا القانون.
وفى جميع أحوال التصرف فى العقارات دون مقابل، يجب على المستثمر تقديم ضمان نقدى أو ما يقوم مقامه إلى جهة التصرف بما لا يزيد على خمسة بالمئة (5%) من قيمة التكاليف الاستثمارية للمشروع، وذلك وفقا للمعايير والضوابط التى تبينها اللائحة التنفيذية لهذا القانون، على أن يسترد ذلك الضمان بعد مرور ثلاث سنوات على بدء الأنتاج الفعلى للمشروعات ذات الطبيعة الأنتاجية، أو بدء مزاولة النشاط لغير ذلك من المشروعات، شريطة التزام المستثمر بشروط التصرف.$m229$,'a027bc2f584f61f82f3a2981abb8c7a6',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(61,0,1,$m229$فى الحالات التى يكون فيها التصرف فى العقارات بنظام الترخيص بالأنتفاع بمقابل، يكون الترخيص مدة لا تزيد على 50 عاما قابلة للتجديد، بالشروط المتفق عليها مادام المشروع مستمرا فى نشاطه، ودون أن يخل ذلك بحق الجهة صاحبة الولاية فى تعديل قيمة مقابل الأنتفاع عند التجديد.
ويكون الترخيص للمستثمرين الذين تتوفر فيهم الشروط الفنية والمالية التى تحددها الهيئة بالتنسيق مع الجهة الإدارية صاحبة الولاية.
وتسرى ذات الأحكام السابقة على أحوال التصرف بالتأجير.$m229$,'69488753b9b42bb1cce9807e902b6e47',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(62,0,1,$m229$فى الحالات التى يكون التصرف فى العقارات بالبيع، يجوز لكل مستثمر لأغراض إقامة المشروعات الاستثمارية أو توسيعها أن يقدم طلبا بالتعاقد عليها، بشرط أن تتوفر فيه الشروط الفنية والمالية التى تحددها الهيئة بالتنسيق مع الجهة الإدارية صاحبة الولاية.
ولا تنتقل ملكية العقارات إلى المستثمر فى هذه الحالات إلا بعد سداد كامل الثمن وبدء الأنتاج الفعلى للمشروعات ذات الطبيعة الأنتاجية أو الأنتهاء من تنفيذ المشروعات العقارية أو السياحية، أو بدء مزاولة النشاط لغير ذلك، ويجب أن يتضمن العقد المبرم مع المستثمر نصا بذلك.
ويجوز للهيئة بناء على طلب المستثمر بعد موافقة الجهة الإدارية صاحبة الولاية، الاتفاق على تأجيل سداد كامل الثمن أو بعضه أو غير ذلك من التيسيرات إلى ما بعد التشغيل الفعلى للمشروع، ويحدد العقد ما يلزم لذلك من ضمانات وإجراءات.
وتسرى ذات الأحكام السابقة على نظام الإيجار المنتهى بالتملك.$m229$,'c38841b7d2d7fcd37c8cfd4a8cc13244',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(63,0,1,$m229$عند تزاحم طلبات المستثمرين فى التعامل على العقارات اللازمة لإقامة مشروعات استثمارية سواء بنظام البيع أو التأجير أو التأجير المنتهى بالتملك أو الترخيص بالأنتفاع، تكون المفاضلة بين من استوفى منهم الشروط الفنية والمالية اللازمة للاستثمار بنظام النقاط وفقا لأسس مفاضلة من بينها قيمة العرض المقدم من المستثمر أو المواصفات الفنية أو المالية الأخرى.
وإذا تعذرت المفاضلة بين المتزاحمين بنظام النقاط جاز إجراؤها وفقا لأعلى سعر يقدم منهم.
وتبين اللائحة التنفيذية لهذا القانون أحوال التزاحم، وضوابط إجراء تلك المفاضلة والأسس التى تتم بناء عليها.$m229$,'092d24204ec8b291898a548d038bc2f8',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(64,0,1,$m229$فى تطبيق أحكام هذا الفصل، يكون تقدير ثمن البيع أو القيمة الإيجارية أو مقابل الأنتفاع عن طريق إحدى الجهات الآتية: الهيئة العامة للخدمات الحكومية، اللجنة العليا لتثمين أراضى الدولة بوزارة الزراعة، هيئة المجتمعات العمرانية الجديدة، الهيئة العامة للتنمية الصناعية، وذلك وفقا لطبيعة النشاط المستهدف إقامته.
وتلتزم جهة التقدير بضم ممثلين من ذوى الخبرة فى عضوية لجان التقدير، وأنهاء عملية التقدير خلال مدة لا تجاوز ثلاثين يوما من تاريخ تقديم طلب التقدير إليها.
وتبين اللائحة التنفيذية لهذا القانون المعايير والضوابط والإجراءات اللازمة لمباشرة عملية التقدير، ومدة صلاحيته، والأتعاب التى يتم سدادها لجهة التسعير من الجهة صاحبة الولاية عند إتمام التخصيص.$m229$,'17c7afb0b6156cf035094ede773e89f3',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(65,0,1,$m229$تشكل بقرار من الرئيس التنفيذى للهيئة وباعتماد من الوزير المختص لجنة أو أكثر تضم عناصر فنية ومالية وقانونية تتناسب وظائفهم وخبراتهم مع أهمية وطبيعة موضوع التعاقد، للبت فى طلبات التصرف فى العقارات للمستثمرين فى الأحوال المختلفة وفقا لأحكام هذا الفصل خلال مدة لا تجاوز ثلاثين يوما من تاريخ ورود الرأى الفنى فى طلب المستثمر من جهة الولاية والذى يجب أن تقدمه جهة الولاية خلال أسبوع من تاريخ ورود الطلب وتعتمد قراراتها منه، وتخطر الهيئة مقدم الطلب بهذا القرار.
وتبين اللائحة التنفيذية لهذا القانون إجراءات عمل اللجان المشار إليها، وكيفية الإخطار وطرق سداد الثمن أو القيمة الإيجارية أو مقابل الأنتفاع بحسب الاحوال، وأيلولة المستحقات إلى الجهات المختصة كاملة، كما تبين اللائحة التنفيذية إجراءات إعداد وتحرير العقود فى كل حالة وفق نماذج العقود المعتمدة من مجالس إدارة الهيئة بعد مراجعتها من مجلس الدولة.$m229$,'575ee7db1a0b2a2434edddc016d127b5',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(66,0,1,$m229$فى جميع الأحوال التى يتم فيها التصرف فى العقارات المملوكة ملكية خاصة للدولة أو للأشخاص الاعتبارية العامة، يتعين على المشروع الاستثمارى الالتزام بالغرض الذى تم التصرف فى العقار على أساسه ولا يجوز تغيير هذا الغرض إلا بعد الموافقة الكتابية من الجهة الإدارية صاحبة الولاية فى الأحوال التى تسمح فيها طبيعة العقار وموقعه بهذا التغيير وبشرط سداد المبالغ التى تبين اللائحة التنفيذية معايير تحديد قيمتها.
وتلتزم هذه الجهة بالرد على طلب تغيير الغرض خلال ثلاثين يوما من تاريخ تقديمه وإلا اعتبر عدم الرد رفضا للطلب.
ويحق للمستثمر التظلم من هذا القرار أما اللجنة المنصوص عليها بالمادة (83) من هذا القانون.
وفى جميع الأحوال، لا يقبل طلب تغيير الغرض قبل إنقضاء عام من تاريخ بدء الأنتاج أو مزاولة النشاط.$m229$,'8a8188a2a10746bb6b2614e5578ac47e',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(67,0,1,$m229$يكون للجهة الإدارية صاحبة الولاية بناء على ما يقدم إليها من تقارير المتابعة التى يعدها موظفو الجهات الإدارية صاحبة الولاية بشأن متابعة مراحل تنفيذ البرنامج الزمنى لإقامة منشآت المشروع الاستثمارى، وبعد موافقة مجلس إدارة الهيئة، فسخ عقد البيع أو الإيجار أو الإيجار المنتهى بالمتلك أو الترخيص بالأنتفاع وسحب العقارات فى أحد الأحوال الآتية:
1 - الامتناع عن استلام العقار مدة تسعين يوما من تاريخ إخطاره بالاستلام.
2 - عدم البدء فى تنفيذ المشروع خلال تسعين يوما من تاريخ استلامه العقار خاليا من الموانع والعوائق بغير عذر مقبول واستمرار تقاعسه بعد أنذاره كتابة مدة مماثلة.
3 - مخالفة شروط سداد المستحقات المالية ومواعيده.
4 - تغيير غرض استخدام العقار الذى خصص له أو القيام برهنه أو ترتيب أى حق عينى عليه بغير الموافقة الكتابية المسبقة من الجهة الإدراية صاحبة الولاية أو قبل أنتقال المكلية إليه وفقا لأحكام هذا القانون.
5 - مخالفة شروط العقد أو الترخيص بالأنتفاع مخالفة جوهرية، فى أى مرحلة من مراحل المشروع، وعدم إزالة أسباب المخالفة بعد أنذار المستثمر كتابة بذلك.
وتبين اللائحة التنفيذية المخالفات الجوهرية المشار إليها وإجراءات استرداد العقارات فى حالة ثبوت امتناع المستثمر أو تقاعسه عن إتمام تنفيذ المشروع ويجوز فى هذه الحالة إعادة التصرف فى العقار.$m229$,'31319ac91ccd2745923b59cdec38ffa6',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(68,0,1,$m229$ينشأ مجلس أعلى للاستثمار برئاسة رئيس الجمهورية يختص فضلا عما هو مقرر له فى هذا القانون بالأتى:
1 - اتخاذ كل مايلزم لتهيئة مناخ أفضل للاستثمار والتوجيه بما يتطلبه ذلك.
2 - وضع الإطار العام للإصلاح التشريعى والإدارى لبيئة الاستثمار.
3 - إقرار السياسات والخطة الاستثمارية التى تحدد أولويات مشروعات الاستثمار المستهدفة، بما يتفق مع السياسة العامة للدولة وخطة التنمية الاقتصادية والاجتماعية ونظم الاستثمار المطبقة.
4 - متابعة تنفيذ أجهزة الدولة للخطط والبرامج المتعلقة بالاستثمار وتطور العمل بالمشروعات الاقتصادية الكبرى وموقف مشروعات المشاركة مع القطاع الخاص.
5 - متابعة تحديث الخريطة الاستثمارية وتنفيذها على مستوى القطاعات المتخصصة والمناطق الجغرافية المختلفة فى إطار خطة التنمية الاقتصادية للدولة.
6 - استعراض الفرص الاستثمارية المتاحة فى كل قطاع وبحث محاور المشاكل المتعلق بها.
7 - متابعة تطور تصنيف مصر وترتيبها فى التقارير والمؤشرات الدولية الخاصة بالاستثمار.
8 - متابعة آليات تسوية منازعات الاستثمار وموقف قضايا التحكيم الدولة.
9 - دراسة ووضع حلول لمعوقات الاستثمار وإزالة عقبات تنفيذ أحكام هذا القانون.
10 - تفعيل المسئولية التضامنية لجميع الوزارات والهيئات العامة والأجهزة الحكومية المختصة بالاستثمار وتحقيق التناغم فى ادائها.
11 - حل الخلافات والتشابكات التى قد تثور بين اجهزة الدولة فى مجال الاستثمار.
ويصدر بتشكيل هذا المجلس وبنظام العمل به قرار من رئيس الجمهورية.
وتلتزم جميع أجهزة الدولة بتنفيذ القرارات الصادرة عن المجلس.$m229$,'653f32a0267d323be3f215e8eca6dc5c',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(69,0,1,$m229$الهيئة العامة للاستثمار والمناطق الحرة، هيئة عامة اقتصادية، لها شخصية اعتبارية عامة تتبع الوزير المختص، وتقوم على تنظيم الاستثمار فى البلاد وتشجيعه، وتنمية وإدارة شئونه والترويج له، على النحو الذى يحقق خطة التنمية الاقتصادية للدولة.
ويكون مقر الهيئة الرئيس محافظة القاهرة، ويجوز لها أنشاء فروع أو مكاتب لها داخل جمهورية مصر العربية أو خارجها بقرار من مجلس الإدارة ضمن بعثات التمثيل التجارى.$m229$,'903b4ec85e0b77bfe4f36d48edea8991',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(70,0,1,$m229$مع عدم الإخلال بأحكام قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 والقانون رقم 95 لسنة 1995 فى شأن التأجير التمويلى وقانون التمويل العقارى الصادر بالقانون رقم 148 لسنة 2001، وقانون البنك المركزى والجهاز المصرفى والنقد الصادر بالقانون رقم 88 لسنة 2003، والقانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية، تكون الهيئة هى الجهة الإدارية المختصة دون غيرها بتطبيق أحكام هذا القانون وقانون شركات المساهمات وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981.
ولاتتقيد الهيئة فى المسائل المالية والإدارية بالنظم والقواعد الحكومية، وللهيئة فى سبيل أنجاز مهامها الاستعانة بأفضل الكفاءات والخبرات المحلية والعالمية، وذلك دون الإخلال بأحكام القانون رقم 63 لسنة 2014 بشأن الحد الأقصى لدخول العاملين بأجر لدى أجهزة الدولة ويصدر بتنظيم هذه المسائل قرار من مجلس إدارة الهيئة.
ويكون للهيئة فى سبيل تحقيق أغراضها التعاقد وإرجاء التصرفات والأعمال ويجوز تخصيص عقارات من أملاك الدولة الخاصة أو إعادة تخصيصها للهيئة بغرض استخدامها فى شئونها الإدارية.$m229$,'e1d3a74f81d072021779f9fe2026c994',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(71,0,1,$m229$للهيئة فى سبيل تحقيق أغراضها فضلا عما هو منصوص عليه فى هذا القانون مباشرة الاختصاصات الأتية:
1 - إعداد مشروع الخطة الاستثمارية بالتنسيق والتعاون مع جميع أجهزة الدولة المختصة تتضمن نوعية الاستثمار ونظامه ومناطقه الجغرافية وقطاعاته والعقارات المملوكة للدولة أو للأشخاص الاعتبارية العامة الأخرى المعدة للاستثمار، ونظام التصرف فيها وطريقته بحسب نوع النظام الاستثمارى.
2 - وضع الخطط والدراسات والنظم الكفيلة بجذب وتشجيع رءوس الأموال الوطنية والأجنبية للاستثمار فى مختلف المجالات وفق الخطة الاستثمارية للدولة، واتخاذ الإجراءات اللازمة لذلك.
3 - إعداد قاعدة بيانات وخريطة للفرص الاستثمارية المتاحة والمشروعات والأنشطة الاستثمارية المستهدفة، ومتابعة تحديثها، وتوفير هذه المعلومات والبيانات للمستثمرين.
4 - إصدار الشهادة اللازمة لتمتع المستثمر بالحوافز والضمانات المنصوص عليها فى هذا القانون.
5 - وضع خطة للترويج للاستثمار واتخاذ جميع الإجراءات اللازمة لذلك بجميع الوسائل ونشرها فى الداخل والخارج.
6 - توحيد جميع النماذج الرسمية الخاصة بشئون الاستثمار التنسيق مع الجهات المختصة وتوفيرها للاستخدام من خلال الشبكة الدولية للمعلومات وغيرها من الوسائل.
7 - وضع نظام لإدارة المناطق الحرة والاستثمارية بما يخدم الاقتصاد القومى.
8 - دراسة التشريعات المتعلقة بالاستثمار واقتراح ما يلزم فى شأنها ومراجعتها بشكل دورى.
9 - إقامة المؤتمرات والندوات وورش التدريب والعمل والمعارض المتصلة بشئون الاستثمار وتنظيمها داخليا وخارجيا.
10 - التعاون مع المؤسسات والمنظمات الدولية والأجنبية العاملة فى مجال الاستثمار والترويج له.
11 - إجراء الرقابة والتفتيش على الشركات الخاضعة لأحكام هذا القانون وذلك وفقا للقواعد والإجراءات التى تبينها اللائحة التنفيذية لهذا القانون والقوانين الأخرى.$m229$,'859e7020700e61a3b48d750c4017d927',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(72,0,1,$m229$يجوز للهيئة لأغراض تنفيذ خطتها فى مجال الترويج لفرص الاستثمار المتاحة داخليا وخارجيا، أن تعهد بهذه المهمة إلى شركات متخصصة يتم التعاقد معها لهذا الغرض، دون التقيد بأحكام قانون تنظيم المناقصات والمزايدات الصادر بالقانون رقم 89 لسنة 1998، وذلك وفقا للقواعد التى تبينها اللائحة التنفيذية لهذا القانون.$m229$,'7b7e2cbb82dc868e0eb9b98feca78c7b',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(73,0,1,$m229$يكون للهيئة مجلس إدارة، يتولى وضع السياسة العامة لها والإشراف على تنفيذها، يشكل بقرار من رئيس مجلس الوزراء، على النحو الأتى:
1 - الوزير المختص رئيسا.
2 - الرئيس التنفيذى للهيئة.
3 - نواب الرئيس التنفيذى للهيئة.
4 - ثلاثة من ممثلى الجهات والأجهزة ذات الصلة.
5 - إثنان من ذوى الخبرة أحدهما فى مجال الاستثمار بالقطاع الخاص والثانى فى مجال القانون.
وتكون مدة العضوية ثلاث سنوات قابلة للتجديد.
ويجتمع المجلس مرة على الأقل شهريا، ولا يكون أنعقاده صحيحا إلا بحضور ثلثى الأعضاء على الأقل، وله أن يشكل من بين أعضائه لجنة أو أكثر يعهد إليها بمهمة محددة ولرئيسه دعوة من يراه من الخبراء لحضور الاجتماعات كلما دعت الحاجة إلى ذلك.
وتصدر قرارات المجلس بأغلبية الحاضرين من الأعضاء، وفى حالة تساوى الأصوات يرجح الجانب الذى منه الرئيس وتنظم اللائحة التنفيذية لهذا القانون نظام عمل المجلس.
ويقوم أعضاء مجلس الإدارة بالإفصاح عن جميع أموالهم، على أن يتم تقديم ومراجعة هذا الإفصاح سنويا من قبل جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلى أو محتمل للمصالح، على أن يرفع هذا التقرير إلى المجلس الأعلى عن طريق الوزير المختص.$m229$,'296afd560203a1156938cf07532bb0de',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(74,0,1,$m229$مجلس إدارة الهيئة هو السلطة العليا المهيمنة على شئونها، وعليه أن يتخذ ما يراه لازما من قرارات لتحقيق الأغراض التى أنشئت الهيئة من أجلها طبقا لأحكام هذا القانون ولائحته التنفيذية ويتولى على الأخص ما يلى:
1 - وضع خطط نشاط الهيئة وبرامجها فى إطار السياسة الاستثمارية للدولة.
2 - وضع آليات تفعيل منظومة مركز خدمات المستثمرين، ومتابعة تنفيذها.
3 - تحديد مقابل الخدمات التى تقدمها الهيئة.
4 - إقرار اللوائح الداخلية والقرارات التنفيذية المتعلقة بالشئون المالية والإدارية والفنية للهيئة، ووضع هيكلها التنظيمى.
5 - إقرار مشروع الموازنة للهيئة وحساباتها الختامية.
6 - وضع ضوابط تشكيل واختصاصات ونظم عمل مجالس إدارات المناطق الحرة والاستثمارية، على أن يصدر بالتشكيل والاختصاصات قرار من الرئيس التنفيذى للهيئة.
7 - إقرار اللوائح والنظم واعتماد النماذج اللازمة لإقامة المناطق الحرة والاستثمارية وتنميتها وإدارتها، وتحديد ضوابط وآليات إلغاء المشروعات المقامة وفقا لأنظمة الاستثمار المختلفة، والمدد اللازمة لسقوط الموافقات الصادرة بشأنها.
8 - اعتماد شروط منح التراخيص وشغل العقارات واسترددها بما عليها من مبان وأنشاءات وما بداخلها وعلى الأخص ما يتعلق بالمناطق الاستثمارية وفقا لأحكام هذا القانون.
9 - اعتماد ضوابط قواعد دخول البضائع وخروجها وأحكام قيدها ومقابل شغل الأماكن التى تودع بها، وفحص المستندات والمراجعة والنظام الخاص برقابة المناطق الحرة وحراستها وتحصيل الرسوم المستحقة، وذلك بالتنسيق مع مصلحة الجمارك.
10 - الموافقة على أنشاء فروع ومكاتب للهيئة لتفعيل مركز خدمات المستثمرين المنصوص عليه فى هذا القانون وتقديم خدمات الاستثمار.
11 - وضع نظام لميكنة خدمات الاستثمار التى تقدم من خلال الهيئة.
12 - وضع النظم والقواعد التى تكفل تطبق مبادئ الحوكمة وأعمال قواعد التفتيش والرقابة اللاحقة على الشركات واتخاذ الإجراءات التى تكفل تطبيق مبادئ الحوكمة وأعمال قواعد التفتيش والرقابة اللاحقة على الشركات واتخاذ الإجراءات اللازمة لذلك على النحو الذى تبينه اللائحة التنفيذية لهذا القانون.
13 - وضع نظام يكفل توفير الإحصائات والبيانات والمعلومات اللازمة لمزاولة المشروع الاستثمارى لنشاطه، وذلك دون الإخلال باعتبارات الأمن القومى أو الحق فى الخصوصية وسرية المعلومات أو بحماية حقوق الغير، ويجب على جميع الجهات المختصة إمداد الهيئة بما يتطلبه وضع هذا النظام.
14 - طلب المعلومات والبيانات اللازمة لحساب أصول الاستثمار الأجنبى المباشر وغير المباشر من الجهات العامة والخاصة للأغراض الإحصائية، وفقا للممارسات الدولية المعمول بها، وذلك دون الإخلال باعتبارات الأمن القومى أو الحق فى الخصوصية وسرية المعلومات وحماية حقوق الغير، ويكون للهيئة فى سبيل ذلك إعداد نماذج واستبيانات لاستيفاء تلك المعلومات والبيانات وتطبيقها بجميع الوسائل بما فيها الوسائل الإلكترونية، على أن يصدر بها قرار من رئيس مجلس الوزراء، وتلتزم الجهات المشار إليها بموافاة الهيئة بهذه البيانات خلال الأجل الذى تحدده اللائحة التنفيذية لهذا القانون.
*البند (14) مضاف بموجب قانون رقم 141 لسنة 2019.$m229$,'ff524a456cb741671427cb1d0fe33915',DATE '2019-08-01',NULL,'active',141,2019,$m229$البند (14) مضاف بموجب قانون رقم 141 لسنة 2019. تاريخ النفاذ المسجل: تاريخ العمل بـالقانون 141 لسنة 2019 (إصدار 31/7/2019؛ العمل به 1/8/2019).$m229$),
(75,0,1,$m229$تتكون موارد الهيئة مما يأتى:
1 - الاعتمادات المالية التى تخصصها لها الدولة.
2 - الرسوم ومقابل الخدمات التى تحصلها الهيئة عدا تلك التى تحصلها لحساب الجهات الأخرى.
3 - الهبات والمنح والقروض المحلية والخارجية التى يوافق عليها مجلس إدارة الهيئة طبقا للقواعد المقررة فى هذا الشأن.
4 - مقابل شغل العقارات المملوكة أو المخصصة للهيئة.
5 - أى موارد أخرى يصدر بها قرار من مجلس إدارة الهيئة بعد موافقة مجلس الوزراء.$m229$,'c3a13ec930d02e2eb4e1e350d32e5cba',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(76,0,1,$m229$يكون للهيئة موازنة مستقلة تعد على نمط موازنات الهيئات الاقتصادية، وتبدأ السنة المالية للهيئة مع السنة المالية للدولة وتنتهى بأنتهائها، وتخضع حساباتها وأرصدتها وأموالها لرقابة الجهاز المركزى للمحاسبات وتودع جميع موارد الهيئة فى حساب خاص تحت حساب الخزانة الموحد بالبنك المركزى المصرى، ويرحل فائض الموازنة من سنة إلى أخرى إلى الحساب الخاص، ويصرف من الحساب بقرار من مجلس إدارة الهيئة.$m229$,'ebc9064dac0695bae74ce89750d08f75',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(77,0,1,$m229$يصدر بتعيين الرئيس التنفيذى للهيئة ونوابه وتحديد معاملتهم المالية قرار من رئيس مجلس الوزراء بناء على عرض الوزير المختص، وذلك لمدة ثلاث سنوات قابلة للتجديد لمدة واحدة، ولا يجوز أن يزيد عدد نواب رئيس الهيئة على خمسة نواب، وتحدد اختصاصات نواب الرئيس التنفيذى بقرار من الوزير المختص.
ويتولى الرئيس التنفيذى للهيئة تمثيلها أمام القضاء والغير، كما يتولى تصريف شئونها وتنفيذ قرارات مجلس إدارتها، وله فى سبيل ذلك اتخاذ ما يلزم لتيسير إجراءات الخدمات التى تقدمها الهيئة للمستثمرين، وكذا اتخاذ مايلزم لتفعيل نظام الرقابة والشفافية والحوكمة والإدارة الرشيدة.
ويجوز للرئيس التنفيذى تفويض أحد نوابه فى بعض اختصاصاته دون أن يتضمن التفويض تمثيل الهيئة أمام القضاء أو الغير.
وتبين اللائحة التنفيذية الاختصاصات والمهام الأخرى للرئيس التنفيذى.$m229$,'23398eb54f0783f5ecdef7cbf5501e82',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(78,0,1,$m229$على الرئيس التنفيذى إعداد خطة سنوية، واستراتيجية مستدامة للهيئة كل خمس سنوات، وتقرير نصف سنوى يتضمن بيانا بنتائج أعمالها وما أنجزته فى سبيل تيسير إجراءات الاستثمار والترويج له، للعرض على مجلس إدارة الهيئة.
ويقدم الوزير المختص إلى كل من المجلس الأعلى ومجلس الوزراء الخطة السنوية للهيئة والتقرير المشار إليه، وما يتضمنه من نتائج، فى ضوء خطة الهيئة السنوية أو استراتيجيتها الخمسية وما أنجزته فى مجال تيسير إجراءات الاستثمار والترويج له وأبرز معوقات الاستثمار، وما تقترحه الوزارة المختصة من سياسات وإجراءات وتعديلات تشريعية لتحسين مناخ الاستثمار فى الدولة.
ويجوز للرئيس التنفيذى عند الضرورة وبعد موافقة مجلس إدارة الهيئة الموافقة على استكمال أو تطوير مقومات البنية الأساسية للمناطق الحرة العامة غير المملوكة للهيئة، على أن تئول إليها قيمة ما أنفقته خصما من مقابل الأنتفاع الذى يحصل من المشروعات المقامة بتلك المناطق لصالح الجهة مالكة الأرض.
وتبين اللائحة التنفيذية لهذا القانون ضوابط الاستكمال أو التطوير المشار إليهما، وأسس تحديد قيمة ما تم أنفاقه وطرق استرداده.$m229$,'b6ee37f4b3328ffdcc996623d68d30a9',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(79,0,1,$m229$تقوم الهيئة سنويا بنشر قائمة الشركات التي تستفيد من الحوافز المنصوص عليها في هذا القانون في تقرير تنشره علي موقعها الإلكتروني يتضمن طبيعة النشاط وموقعه وطبيعة الحوافز وأسماء الشركات أو المساهمين أو مالكي الشركة.
كما تلتزم الهيئة سنويا بنشر قائمة الشركات المستفيدة من أراضي الدولة بموجب أحكام هذا القانون في تقرير يتضمن غرض استخدام الأرض وطبيعتها وأبعادها وموقعها بدقة وتقييم الخبراء وأسماء الشركاء والمساهمين أو أصحاب الشركة.
وتلتزم الشركات بتقديم بيان بحجم استثماراتها والقوائم المالية السنوية وبيان بعدد العاملين ووظائفهم وجنسياتهم ومجموع أجورهم وغير ذلك من بيانات تحددها اللائحة التنفيذية لهذا القانون.$m229$,'7b27a771a32349bcd32cd16849b6b2b2',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(80,0,1,$m229$يكون لموظفي الهيئة ممن يصدر بتحديدهم قرار من وزير العدل بالإتفاق مع الوزير المختص صفة مأموري الضبط القضائي في إثبات الجرائم التي ترتكب بالمخالفة لأحكام هذا القانون وقانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981 والقرارات المنفذة لهما، ولهم في سبيل ذلك دخول بقرار من الرئيس التنفيذي علي أن يعرض عليه تقرير بنتائج أعمالهم وعلي المشروعات الإستثمارية المعنية تسهيل مهمتهم.$m229$,'a7448645dce610f6fb30dfde0ca3aa52',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(81,0,1,$m229$في حالة مخالفة الشركات أو المنشأت لأحكام هذا القانون، تقوم الهيئة بأنذار الشركات أو المنشأت فورا لإزالة أسباب المخالفة في مدة لا تجاوز خمسة عشر يوم عمل من تاريخ الأنذار.
ويتضمن الأنذار المدة المحددة لإزالة أسباب المخالفة، فاذا أنقضت هذه المدة دون ذلك كان للرئيس التنفيذي للهيئة بعد موافقة مجلس الإدارة إصدار قرار بإيقاف نشاط الشركة أو المنشأة مدة لا تجاوز تسعين يوما، فإذا استمرت الشركة أو المنشأة في ارتكاب المخالفة أو الاستمرار فيها أو ارتكبت مخالفة أخري خلال سنة من المخالفة الأولي جاز اتخاذ أحد الإجراءات الأتية:
أ- إيقاف التمتع بالحوافز والإعفاءات المقررة.
ب- تقصير مدة التمتع بالحوافز والإعفاءات المقررة.
ج- أنهاء التمتع بالحوافز والإعفاءت المقررة، مع ما ترتب علي ذلك من أثار بالنسبة للقرارات والتراخيص الصادرة للشركات والمنشآت.
د- إلغاء ترخيص مزاولة النشاط.
وبالنسبة للمخالفات التي تهدد الصحة العامة أو أمن المواطنين أو الأمن القومي يكون للرئيس التنفيذي للهيئة بعد إخطار مجلس إدارة الهيئة إصدار قرار بإيقاف النشاط مدة تسعين يوما، فاذا استمرت الشركة أو المنشأة في ارتكاب المخالفة أو ارتكبت مخالفة أخري خلال سنة من المخالفة الأولى كان له إلغاء الترخيص.$m229$,'c1f4a4a711eea033dfd2cdcf3ff6e03d',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(82,0,1,$m229$مع عدم الإخلال بالحق فى التقاضي، تجوز تسوية أي نزاع ينشأ بين المستثمر وأي جهة أو أكثر من الجهات الحكومية يتعلق برأسمال المستثمر أو بتفسير أحكام هذا القانون أو تطبيقه وديا دون تأخير من خلال المفاوضات بين الأطراف المتنازعة.$m229$,'2d0ce5028ddda7a4abf0d49be310840e',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(83,0,1,$m229$تنشأ بالهيئة لجنة أو أكثر لنظر التظلمات من القرارات الصادرة وفقا لأحكام هذا القانون من الهيئة أو الجهات المختصة بمنح الموافقات والتصاريح والتراخيص.
وتشكل اللجنة برئاسة مستشار من إحدى الجهات القضائية تحدده المجالس الخاصة بتلك الجهات وعضوية ممثل عن الهيئة وأحد ذوى الخبرة.
ويصدر بتشكيل اللجنة ونظام عملها وأمانتها الفنية قرار من الوزير المختص.$m229$,'91476519febf340be7e63b3e3638e5cf',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(84,0,1,$m229$تقدم التظلمات إلى اللجنة خلال خمسة عشر يوم عمل من تاريخ الإخطار أو العلم بالقرار المتظلم منه ويترتب على تقديم التظلم أنقطاع مواعيد الطعن، وللجنة الاتصال بذوى الشأن والجهات الإدارية المختصة لطلب تقديم الايضاحات والمستندات والإجابة على الاستفسارات التى تراها لازمة، ولها أن تستعين بالخبرات والتخصصات المختلفة بالهيئة وغيرها من الجهات الإدارية.
وتفصل اللجنة فيما يعرض عليها بقرار مسبب خلال ثلاثين يوما من تاريخ أنتهاء سماع الأطراف وتقديم وجهات نظرهم، ويكون قرارها فى هذا الشأن نهائيا وملزما لجميع الجهات المختصة، وذلك دون إخلال بحق المستثمر فى اللجوء إلى القضاء.
وتبين اللائحة التنفيذية مكان أنعقاد اللجنة وكيفية الإخطار بقراراتها.$m229$,'1a9136b9beccfd87503c471a1e47ba6f',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(85,0,1,$m229$تنشأ لجنة وزارية تسمى (اللجنة الوزارية لفض منازعات الاستثمار) تختص بالنظر فيما يقدم أو يحال إليها من طلبات أو شكاوى أو منازعات قد تنشأ بين المستثمرين والدولة أو تكون إحدى الجهات أو الهيئات أو الشركات التابعة لها طرفا فيها ويصدر بتشكيل اللجنة قرار من رئيس مجلس الوزراء، ويشارك فى عضويتها أحد نواب رئيس مجلس الدولة يختاره المجلس الخاص للشئون الإدارية بمجلس الدولة، وتعتمد قراراتها من مجلس الوزراء، ويجوز للوزراء من أعضاء اللجنة فى حالة الضرورة إنابة من يمثلهم لحضور اجتماع اللجنة والتصويت على قراراتها فيه.
ويكون للجنة أمانة فنية، يصدر بتشكيلها ونظام عملها قرار من الوزير المختص.$m229$,'e752ffdfb04aad249e78aaf3b3ed2cd2',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(86,0,1,$m229$يشترط لصحة أنعقاد اللجنة حضور رئيسها ونصف أعضائها الأصليين فى الأقل، وتصدر اللجنة قراراتها بأغلبية أصوات الحاضرين، وعند تساوى الأصوات يرجح الجانب الذى منه الرئيس.
وتلتزم الجهة الإدارية المختصة بتقديم المذكرات الشارحة والمستندات اللازمة بمجرد طلبها، وإذا كانت هذه الجهة من الجهات المشتركة فى عضوية اللجنة فلا يكون لها صوت معدود فى المداولات بالنسبة للموضوع المتعلق بها.
وتفصل اللجنة فيما يعرض عليها بقرار مسبب خلال ثلاثين يوما من تاريخ أنتهاء سماع الأطراف وتقديم وجهات نظرهم.$m229$,'3c16366500b64e4f6a843fcf1d5a54b3',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(87,0,1,$m229$مع عدم الإخلال بحق المستثمر فى اللجوء إلى القضاء، تكون قرارات اللجنة بعد اعتمادها من مجلس الوزراء واجبة النفاذ وملزمة للجهات الإدارية المختصة ولها قوة السند التنفيذى، ويترتب على الامتناع عن تنفيذ قراراتها تطبيق أحكام المادة 123 من قانون العقوبات وتوقيع العقوبة بها. ولا يترتب على تقديم التظلم فى قرارات اللجنة وقف تنفيذها.$m229$,'546c9d9dc79f1ff4373df1db68acdccc',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(88,0,1,$m229$تنشأ بمجلس الوزراء لجنة وزارية، تسمي (اللجنة الوزارية لتسوية منازعات عقود الاستثمار)، تختص بتسوية المنازعات الناشئة عن عقود الاستثمار التى تكون الدولة أو إحدى الجهات أو الهيئات أو الشركات التابعة لها طرفا فيها.
وتشكل هذه اللجنة بقرار من رئيس مجلس الوزراء، ويشارك فى عضويتها أحد نواب رئيس مجلس الدولة يختاره المجلس الخاص للشئون الإدارية بمجلس الدولة، وتعتمد قراراتها من مجلس الوزراء، ولا تجوز الإنابة فى حضور جلساتها.
ويشترط لصحة إنعقاد اللجنة حضور رئيسها ونصف عدد أعضائها، وتصدر اللجنة قراراتها بأغلبية الآراء وعندى تساوى الأصوات يرجح الجانب الذى منه الرئيس.
ويكون للجنة أمانة فنية يصدر بتشكيلها ونظام عملها قرار من رئيس مجلس الوزراء.$m229$,'c7ea2894fa67f8d0385eb00a1023dc11',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(89,0,1,$m229$تتولى اللجنة بحث الخلافات الناشئة بين أطراف عقود الاستثمار ودراستها، ويكون لها فى سبيل ذلك وبرضاء أطراف التعاقد إجراء التسوية اللازمة لمعالجة اختلال توازن تلك العقود، ومد الآجال أو المدد أو المهل المنصوص عليها فيها.
كما تتولى متى لزم الأمر، إعادة جدولة المستحقات المالية أو تصحيح الإجراءات السابقة على إبرام العقود، وذلك كله على نحو يحقق قدر الإمكان التوازن العقدى ويضمن الوصول إلى أفضل وضع اقتصادى للحفاظ على المال العام وحقوق المستثمر فى ضوء ظروف كل حالة.
وتعرض اللجنة تقريرا بما تتوصل إلية بشأن حالة التسوية على مجلس الوزراء يبين جميع عناصرها، وتكون تلك التسوية بعد اعتمادها من مجلس الوزراء واجبة النفاذ وملزمة للجهات الإدارية المختصة ولها قوة السند التنفيذى.$m229$,'a8cbf6cfde062d55d979dbba6684e86b',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(90,0,1,$m229$تجوز تسوية منازعات الاستثمار المتعلقة بتنفيذ أحكام هذا القانون بالطريقة التى يتفق عليها المستثمر أو وفقا لأحكام قانون التحكيم فى المواد المدنية والتجارية الصادر بالقانون رقم 27 لسنة 1994.
كما يجوز للطرفين، فى أى وقت من الأوقات خلال النزاع، الإتفاق على التماس سبل التسوية بمختلف أنواعها طبقا للقواعد المعمول بها لتسوية المنازعات، بما فى ذلك اللجوء إلى التحكيم غير المؤسسي(الحر)، أو التحكيم المؤسسى.$m229$,'f099294ae93b8f49126603f8ea2e1807',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(91,0,1,$m229$ينشأ مركز مستقل للتحكيم والوساطة يسمي (المركز المصرى للتحكيم والوساطة) تكون له الشخصية الاعتبارية، ويتخذ من محافظة القاهرة مقرا له.
ويتولى المركز تسوية منازعات الاستثمار التى قد تنشأ بين المستثمرين، أو بينهم وبين الدولة أو إحدى الجهات التابعة لها عامة أو خاصة، إذا ما اتفقوا فى أى مرحلة على تسوية النزاع عن طريق التحكيم أو الوساطة أمام هذا المركز، وذلك كله مع مراعاة أحكام القوانين المصرية المنظمة للتحكيم وتسوية المنازعات.
ويتولى إدارة المركز مجلس إدارة، يتكون من خمسة أعضاء من ذوى الخبرة والتخصص والكفاءة والسمعة الطيبة يصدر بتعينهم قرار من رئيس مجلس الوزراء.
و تكون مدة مجلس الإدارة خمس سنوات يجوز تجديدها مرة واحدة، و لا يجوز عزل أحد أعضاء مجلس الإدارة طوال هذه المدة الإ اذا فقد الصلاحية الطبية لممارسة مهام عمله أو فقد الثقة و الاعتبار أو أخل إخلالا جسيما بواجبات عمله وفقا للنظام الأساسى للمركز.
و ينتخب اعضاء مجلس الإدارة من بينهم رئيسا للمجلس، و يكون للمركز مدير تنفيذى يصدر بتعيينه و تحديد معاملته المالية قرار من مجلس الإدارة.
و يصدر بالنظام الأساسى لهذا المركز و نظام العمل فيه و القواعد المهنية و الإجراءات المنظمة له و مقابل الخدمات التى يقدمها و قوائم المحكمين و الوسطاء و اتعباهم قرار من مجلس إدارة المركز و ينشر النظام الأساسى للمركز فى الوقائع المصرية.
و تتكون مواد المركز المالية من مقابل الخدمات التى يقدمها وفقا لما يحدده النظام الأساسى له و توفر فى الثلاث سنوات الأولى من تاريخ العمل بهذا القانون مواد مالية كافية للمركز من الخزانة العامة للدولة، و لا يجوز بخلاف ما تقدم الحصول على اى أموال من الدولة أو إحدى أجهزتها.$m229$,'ea9083617ec5346c6b4a986529b15fac',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(91,1,1,$m229$يعاقب المسئول عن الإدارة الفعلية للشخص الاعتبارى على مخالفة حكم البند (14) من المادة (74) من هذا القانون بالغرامة التى لا تجاوز خمسين ألف جنيه، إذا ثبت علمه بالمخالفة وكان إخلاله بالواجبات التى تفرضها عليه تلك الإدارة قد أسهم ف وقوع الجريمة.
*مضافة بموجب قانون رقم 141 لسنة 2019.$m229$,'82fa35c1c7754b0ba854dec5e9d8f868',DATE '2019-08-01',NULL,'active',141,2019,$m229$مضافة بموجب قانون رقم 141 لسنة 2019. تاريخ النفاذ المسجل: تاريخ العمل بـالقانون 141 لسنة 2019 (إصدار 31/7/2019؛ العمل به 1/8/2019).$m229$),
(92,0,1,$m229$فى الأحوال التى ترتكتب فيها الجريمة باسم الشخص الأعتبارى الخاص و لحسابه، لا يعاقب المسئول عن الإدارة الفعلية الإ اذا ثبت علمه بالجريمة و اتجهت إرادته لارتكابها تحقيقا لمصلحة نفسه أو غيره و ذلك دون الإخلال باحكام المسئولية المدنية.
و فى الحالة التى لا تثبت فيها مسئولية الشخص الطبيعى على النحو المحدد فيها من الفقرة السابقة يعاقب الشخص الاعتبارى بغرامة لا تقل عن اربعة امثال الغرامة المقررة قانونا للجريمة و لا تجاوز عشرة امثالها و فى حالة العود يحكم بالغاء الترخيص أو حل الشخص الاعتبارى بحسب الأحوال و ينشر الحكم فى جريدتين يوميتين واسعتى الأنتشار على نفقة الشخص الاعتبارى.$m229$,'4670f5d56ed01e11fece38c65b45f1c6',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(93,0,1,$m229$فى غير حالة التلبس يكون طلب الدعوى الجنائية فى الجرائم المنصوص عليها فى قانون الجمارك الصادر بالقانون 66 لسنة 1963، و قانون الضريبى على الدخل الصادر بالقانون 91 لسنة 2005، و قانون الضريبة على القيمة المضافة الصادر بالقانون 67 لسنة 2016، بعد أخذ راى الوزير المختص اذا كان المتهم بارتكاب الجريمة تابعا لأحد المشروعات الاستثمارية الخاضعة لأحكام هذا القانون.
و يتعين على الوزير المختص ابداء الراى فى هذا الشأن خلال سبعة أيام من تاريخ ورود كتب استطلاع الراى اليه و الإ جاز رفع الدعوى طبقا للقواعد المقررة فى القوانين المشار اليها.$m229$,'1d50bbe0a20666336a36d449270a3ca6',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL),
(94,0,1,$m229$مع عدم الاخلال بالمادة 131 من قانون البنك المركزى و الجهاز المصرفى و النقد الصادر بالقانون 88 لسنة 2003، و المادة السادسة عشرة من القانون 10 لسنة 2009 بتنظيم الرقابة على الاسواق و الأدوات المالية غير المصرفية، لا يجوز رفع الدعوى الجنائية أو اتخاذ أى إجراء من إجراءات التحقيق قبل المستثمر فى الجرائم المنصوص عليها فى الباب الرابع من الكتاب الثانى من قانون العقوبات الا بعد أخذ راى الوزير المختص على النحو المنصوص عليه فى المادة (93) من هذا القانون بالقواعد ذاتها.$m229$,'87f880968ed33006c766651830afa6d9',DATE '2017-06-01',NULL,'active',NULL,NULL,NULL);

DO $m229$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m229_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m229_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[229] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m229_art) <> 107 OR (SELECT sum(char_length(body)) FROM m229_art) <> 84389 OR (SELECT count(*) FROM m229_ver) <> 114 THEN
    RAISE EXCEPTION '[229] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=72 AND law_year=2017 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%الاستثمار%' THEN
    RAISE EXCEPTION '[229] يوجد مستند آخر برقم 72 لسنة 2017 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (72, 2017, $t229$القانون رقم 72 لسنة 2017 بإصدار قانون الاستثمار (النسخة المحدثة بعد تعديلى القانونين رقم 141 لسنة 2019 ورقم 160 لسنة 2023)$t229$, $t229$قانون الاستثمار 72/2017$t229$, 'other', 'amended', NULL, DATE '2017-05-31', DATE '2023-07-26', 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m229_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m229_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m229_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 107 THEN
    RAISE EXCEPTION '[229] عدد صفوف النص % بدل 107', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 114 THEN
    RAISE EXCEPTION '[229] عدد نسخ النص % بدل 114', v_vcnt;
  END IF;
  RAISE NOTICE '[229] قانون 72/2017: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m229$;
